export const MODEL_FACTS = {
  "aachen-cathedral": {"article":"Aachen Cathedral","text":"Aachen Cathedral is a Catholic church in Aachen, Germany, and the cathedral of the Diocese of Aachen. One of the oldest cathedral buildings in Europe, it was constructed as the royal chapel of the Palace of Aachen of Emperor Charlemagne, who was buried there in 814. From 936 to 1531, the original Palatine Chapel saw the coronation of thirty-one German kings.","built":"9th century","architects":["Odo of Metz"]},
  "aapravasi-ghat": {"article":"Aapravasi Ghat","text":"Aapravasi Ghat ('The Immigration Depot') is a building complex located in Port Louis, Mauritius, the first British colony to receive indentured, or contracted, labour workforce from many countries. From 1849 to 1923, half a million Indian indentured labourers passed through the Immigration Depot, to be transported to plantations throughout the British Empire."},
  "abomey": {"article":"Royal Palaces of Abomey","text":"The Royal Palaces of Abomey are 10 palaces spread over an area of 47 hectares (120 acres) at the heart of the Abomey town in Benin, formerly the capital of the West African Kingdom of Dahomey. The Kingdom was founded in 1625 by the Fon people who developed it into a powerful military and commercial empire, which dominated trade with European slave traders on the Slave Coast until the late 19th century, to whom they sold their prisoners of war."},
  "abu-simbel": {"article":"Abu Simbel","text":"Abu Simbel is a historic site comprising two massive rock-cut temples in the village of Abu Simbel, Aswan Governorate, Upper Egypt, near the border with Sudan. It is located on the western bank of Lake Nasser, about 230 km (140 mi) southwest of Aswan (about 300 km (190 mi) by road). The twin temples were originally carved out of the mountainside in the 13th century BC, during the 19th Dynasty reign of the Pharaoh Ramesses II.","built":"1274 BC"},
  "acre": {"article":"Old City of Acre","text":"The Old City of Acre is the historical center of Acre, in northern Israel. Known for its cultural, architectural, and social heritage, the Old City is a UNESCO World Heritage Site. It is an ancient port city, with a history dating back to the Bronze Age. Due to its location providing access to Israel, it was a significant port for centuries."},
  "agadez": {"article":"Agadez","text":"Agadez, formerly spelled Agadès, is the fifth largest city in Niger, with a population of 110,497 based on the 2012 census. The capital of the eponymous Agadez Region, the city lies in the Sahara desert, and is also the capital of the Sultanate of Agadez, one of the traditional Tuareg–Berber federations. The historic centre of the town has been designated a World Heritage Site by UNESCO.","elevation":520},
  "agra-fort": {"article":"Agra Fort","text":"Agra Fort (Qila Agra), also known as the Red Fort of Agra (Lal-Qila) or Qila-i-Akbari (\"Akbar's Fort\"), is an historic fort in the city of Agra in Uttar Pradesh, India. A brick fortification on the site, noted as early as 1080 and later known as Badalgarh, was extensively rebuilt in red sandstone by the Mughal emperor Akbar from 1565 to 1573.","built":"1565","height":214},
  "agrigento": {"article":"Valle dei Templi","text":"The Valle dei Templi, or Valley of the Temples, is an archaeological site in Agrigento, Sicily. It is one of the most outstanding examples of ancient Greek art and architecture of Magna Graecia, and is one of the main attractions of Sicily. The term \"valley\" is a misnomer, the site being located on a ridge outside the town of Agrigento."},
  "ait-benhaddou": {"article":"Aït Benhaddou","text":"Aït Benhaddou is a historic ighrem or ksar (fortified village) along the former caravan route between the Sahara and Marrakesh in Morocco. It is considered a great example of Moroccan earthen clay architecture and has been a UNESCO World Heritage Site since 1987."},
  "ajanta": {"article":"Ajanta Caves","text":"The Ajanta Caves are 30 rock-cut Buddhist cave monuments dating from the second century BCE to about 480 CE in Aurangabad district of Maharashtra state in India. Ajanta Caves are a UNESCO World Heritage Site. Universally regarded as masterpieces of Buddhist religious art, the caves include paintings and rock-cut sculptures, described as among the finest surviving examples of ancient Indian art, particularly expressive paintings that present emotions through gesture, pose and form.","built":"2nd century BC"},
  "aksum": {"article":"Axum","text":"Axum, also spelled Aksum, is a town in the Tigray Region of Ethiopia with a population of 66,900 residents (as of 2015). It is the site of the historic capital of the Aksumite Empire. Axum is located in the Central Zone of the Tigray Region, near the base of the Adwa mountains. It has an elevation of 2,131 metres (6,991 feet) and is surrounded by La'ilay Maychew, a separately administered woreda of the Tigray region.","elevation":2131},
  "al-zubarah": {"article":"Al Zubara Fort","text":"Al Zubara Fort is a historic military fortress located in Zubarah, northern Qatar. It was built under the oversight of Sheikh Abdullah bin Jassim Al Thani in 1938 in the aftermath of the 1937 Qatari–Bahraini conflict.","built":"1938"},
  "ala-archa": {"article":"Ala-Archa","text":"The Ala-Archa is a river in Alamüdün District, Chüy Region, Kyrgyzstan, flowing through Bishkek. It belongs to the Chu river system and is traditionally regarded as a left tributary of the Chu. The river is 78 km (48 mi) long and has a drainage basin of 270 km2 (100 sq mi)."},
  "alamo": {"article":"Alamo Mission","text":"The Alamo is a historic Spanish mission and fortress compound founded in the 18th century by Catholic missionaries in what is now San Antonio, Texas, United States. It was the site of the Battle of the Alamo in 1836, a pivotal event of the Texas Revolution in which American folk heroes James Bowie and Davy Crockett were killed.","built":"1718"},
  "alamut": {"article":"Alamut Castle","text":"Alamut is a ruined mountain fortress located in the Alamut region in the South Caspian, near the village of Gazor Khan in Qazvin province in Iran, approximately 200 km (130 mi) from Tehran. In 1090 AD, the Alamut Castle, a mountain fortress in Iran, came into the possession of Hassan-i Sabbah, a champion of the Nizari Ismaili cause.","built":"AD 860","elevation":2131},
  "albi": {"article":"Albi Cathedral","text":"The Cathedral of Saint Cecilia of Albi, also known as Albi Cathedral, is the seat of the Catholic Archbishop of Albi. First built in the aftermath of the Albigensian Crusade, the exterior resembles a fortress, but the interior is lavishly decorated with art and sculpture, a very ornate choir screen, and walls in bright blues and golds, in the Toulousian or Southern French Gothic style.","built":"1282","height":78},
  "alcobaca": {"article":"Alcobaça Monastery","text":"The Alcobaça Monastery or Alcobasa Monastery is a Catholic monastic complex located in the town of Alcobaça, Oeste region of Portugal, 120 km (75 mi) north of Lisbon and 110 km (68 mi) south of Coimbra. The monastery was established in 1153 by the first Portuguese king, Afonso Henriques, and would develop a close association with the Portuguese monarchy throughout its seven-century-long history.","built":"1187"},
  "aleppo-citadel": {"article":"Citadel of Aleppo","text":"The Citadel of Aleppo is a large medieval fortified palace in the centre of the old city of Aleppo, northern Syria. It is considered to be one of the oldest and largest castles in the world. Usage of the Citadel hill dates back at least to the middle of the 3rd millennium BC. Occupied by many civilizations over time – including the Arameans, Assyrians, Romans, Byzantines, Arabs (Umayyads, Abbasids, etc.), Ayyubids, Mamluks and Ottomans – the majority of the construction as it stands today is thought to originate from the Ayyubid period.","built":"12th century","height":50},
  "alhambra": {"article":"Alhambra","text":"The Alhambra is a palace and fortress complex located in Granada, Spain. It is one of the most famous monuments of Islamic architecture and the only well-preserved palace from the medieval Islamic world. Additionally, the palace contains notable examples of Spanish Renaissance architecture. The building of the complex was begun in 1238 CE by Muhammad I Ibn al-Ahmar, the first Nasrid ruler and founder of the Emirate of Granada, the last Muslim state of al-Andalus.","built":"1239"},
  "aljaferia": {"article":"Aljafería","text":"The Aljafería Palace is a fortified medieval palace built during the second half of the 11th century in the Taifa of Zaragoza in Al-Andalus, present day Zaragoza, Aragon, Spain. It was the residence of the Arab Banu Hud dynasty during the era of Abu Jaffar Al-Muqtadir. The palace reflects the splendor attained by the Taifa of Zaragoza at its height."},
  "amalfi-coast": {"article":"Amalfi Coast","text":"The Amalfi Coast is a stretch of coastline overlooking the Tyrrhenian Sea and the Gulf of Salerno. It is located in the Province of Salerno, in the Campania region of southern Italy, south of the Sorrentine Peninsula and north of the Cilentan Coast. A UNESCO World Heritage Site since 1997, it is one of Italy's most popular seaside destinations."},
  "amber-fort": {"article":"Amber Fort","text":"Amer Fort or Amber Fort is a fort located in Amer, Rajasthan, India. Amer is a town with an area of 4 square kilometres (1.5 sq mi) located 11 kilometres (6.8 mi) from Jaipur, the capital of Rajasthan. Located high on a hill, it is the principal tourist attraction in Jaipur. Amer Fort is known for its artistic style elements.","built":"1592"},
  "ambohimanga": {"article":"Ambohimanga","text":"Ambohimanga is a hill and traditional fortified royal settlement (rova) in Madagascar, located approximately 24 kilometers (15 mi) northeast of the capital city of Antananarivo. It is situated in the commune of Ambohimanga Rova. The hill and the rova that stands on top are considered the most significant symbol of the cultural identity of the Merina people and the most important and best-preserved monument of the precolonial Merina Kingdom.","elevation":1468},
  "amiens-cathedral": {"article":"Amiens Cathedral","text":"The Cathedral of Our Lady of Amiens, or simply Amiens Cathedral, is a Catholic cathedral. The cathedral is the seat of the Bishop of Amiens. It is situated on a slight ridge overlooking the River Somme in Amiens, the administrative capital of the Picardy region of France, some 120 kilometres (75 miles) north of Paris. The cathedral was built almost entirely between 1220 and c. 1270, a remarkably short period of time for a Gothic cathedral, giving it an unusual unity of style.","built":"1220","height":42,"architects":["Robert of Luzarches"]},
  "amsterdam-canals": {"article":"Grachtengordel","text":"The Grachtengordel, known in English as the Canal District, is a neighborhood in Amsterdam, Netherlands located in the Centrum district. The seventeenth-century canals of Amsterdam, located in the center of Amsterdam, were added to the UNESCO World Heritage List in August 2010. The Amsterdam Canal District consists of the area around the city's four main canals: the Singel, the Herengracht, the Keizersgracht, and the Prinsengracht."},
  "angel-falls": {"article":"Angel Falls","text":"Angel Falls is a waterfall in Venezuela. It is the world's tallest uninterrupted waterfall, with a height of 979 metres (3,212 ft), and a plunge of 807 m (2,648 ft). The waterfall drops over the edge of the Auyán-tepui mountain in the Canaima National Park, a UNESCO World Heritage Site in the Gran Sabana region of Bolívar State.","height":907},
  "angel-of-independence": {"article":"Angel of Independence","text":"The Angel of Independence, most commonly known by the shortened name El Ángel and officially known as Monumento a la Independencia (\"Monument to Independence\"), is a victory column on a roundabout on the major thoroughfare of Paseo de la Reforma in downtown Mexico City. El Ángel was built in 1910 during the presidency of Porfirio Díaz by architect Antonio Rivas Mercado, to commemorate the centennial of the beginning of Mexico's War of Independence.","built":"1910","architects":["Antonio Rivas Mercado"]},
  "angkor-wat": {"article":"Angkor Wat","text":"Angkor Wat is a Theravada Buddhist temple complex, originally built as a Vaishnava Hindu temple, in Siem Reap, Cambodia. It is the largest religious complex in the world. Located on a site measuring 162.6 hectares within the medieval capital of Angkor, it was constructed between 1113 and 1150 CE during the reign of the Khmer king Suryavarman II as a Hindu temple dedicated to Vishnu.","built":"12th century","elevation":65},
  "ani": {"article":"Ani","text":"Ani is a ruined medieval Armenian city now situated in Turkey's province of Kars, next to the closed border with Armenia. Between 961 and 1045, it was the capital of the Bagratuni Armenian kingdom that covered much of present-day Armenia and eastern Turkey. The iconic city was often referred to as the \"City of 1,001 Churches,\" though the number was significantly less."},
  "anjar": {"article":"Anjar, Lebanon","text":"Anjar, also known as Hawsh Mousa, is a town of Lebanon, near the Syrian border, located in the Bekaa Valley. The population is 2,400, consisting almost entirely of Armenians. The total area is about twenty square kilometers (7.7 square miles). Since 1984, the ruins of the Umayyad settlement of Anjar have been recognized by UNESCO as a World Heritage Site.","elevation":950},
  "antequera-dolmens": {"article":"Dolmen of Menga","text":"The Dolmen of Menga is a megalithic burial mound called a tumulus, a long barrow form of dolmen, dating from the Neolithic period around 3750–3650 BCE. It is near Antequera, Málaga, Spain. It is one of the largest known ancient megalithic structures in Europe. It is 27.5 metres (90 ft) long, 6 metres (20 ft) wide and 3.5 metres (11 ft) high, and was built with thirty-two megaliths, the largest weighing about 180 tonnes (200 tons)."},
  "antigua-guatemala": {"article":"Antigua Guatemala","text":"Antigua Guatemala, commonly known as Antigua or La Antigua, is a city in the central highlands of Guatemala. The city was the capital of the Captaincy General of Guatemala from 1543 through 1773, with much of its Baroque-influenced architecture and layout dating from that period. Antigua Guatemala serves as the capital of the homonymous municipality and the Sacatepéquez Department.","built":"1543","elevation":1582},
  "anuradhapura": {"article":"Ruwanwelisaya","text":"The Ruwanweli Maha Seya, also known as the Maha Thupa, is a stupa (a hemispherical structure containing relics) in Anuradhapura, Sri Lanka. Two quarts or one Dona of the Buddha's relics are enshrined in the stupa, making it the largest collection of his relics anywhere. It was built by Sinhalese King Dutugemunu in c. 140 B.C., who became king of Sri Lanka after a war in which the Chola King Elāra (Ellalan) was defeated."},
  "aphrodisias": {"article":"Aphrodisias","text":"Aphrodisias was a Hellenistic Greek city in the historic Caria cultural region of western Asia Minor, today's Anatolia in Turkey. It is located near the modern village of Geyre, about 100 km (62 mi) east/inland from the coast of the Aegean Sea, and 230 km (140 mi) southeast of İzmir. Aphrodisias was named after Aphrodite, the Greek goddess of love, who had here her unique cult image, the Aphrodite of Aphrodisias."},
  "appian-way": {"article":"Appian Way","text":"The Appian Way, also known by its Latin and Italian name, Via Appia, is one of the earliest and strategically most important Roman roads of the ancient republic. It connected Rome to Brindisi, in southeast Italy. Its importance is indicated by its common name, recorded by Statius, of Appia longarum... regina viarum ('the Appian Way, the queen of the long roads').","built":"312 BC"},
  "arc-de-triomphe": {"article":"Arc de Triomphe","text":"The Arc de Triomphe de l'Étoile, often simply called the Arc de Triomphe, is one of the most famous monuments in Paris, France. It is located at the western end of the Champs-Élysées, at the centre of the Place Charles de Gaulle—formerly known as the \"Place de l'Étoile\"—named for the star-shaped configuration formed by the convergence of twelve radiating avenues.","built":"1836","height":50,"architects":["Jean-François Chalgrin","Louis-Robert Goust","Jean-Nicolas Huyot"]},
  "arequipa": {"article":"Historic Centre of Arequipa","text":"In December 2000, UNESCO declared the historical center of Arequipa a World Heritage Site, stating the following: \"The historical center of Arequipa is an example of ornamented architecture, represents a masterpiece of the creative coalition of European and native characteristics. A colonial town challenged by the conditions of nature, the indigenous influences, the conquest process and evangelism as well as for a spectacular natural scenario.\""},
  "arles-arena": {"article":"Arles Amphitheatre","text":"The Arles Amphitheatre is a Roman amphitheatre in Arles, southern France. Two-tiered, it is likely the most prominent tourist attraction in the city which thrived in ancient Rome. The towers jutting out from the top are medieval add-ons. Built in 90 AD, the amphitheatre held over 20,000 spectators of chariot races and bloody hand-to-hand battles."},
  "as-salt": {"article":"As-Salt","text":"As-Salt, also known as Salt, is an ancient trading city and administrative centre in west-central Jordan. It is on the old main highway leading from Amman to Jerusalem. Situated in the Balqa highland, about 790–1,100 metres above sea level, the city is built in the crook of three hills, close to the Jordan Valley. One of the three hills, Jabal al-Qal'a, is the site of a 13th-century ruined fortress.","elevation":820},
  "asante-shrine": {"article":"Asante Traditional Buildings","text":"The Asante Traditional Buildings are a collection of 10 traditionally built buildings from the time of the Ashanti Empire in the area near Kumasi. These buildings served as fetish houses and shrines during the 18th and 19th centuries, during the golden age of the Ashanti Empire. When the empire fell during the British occupation of the area from 1806 to 1901, most Asante buildings of the period were destroyed during the era."},
  "ashur": {"article":"Assur","text":"Aššur, also known as Ashur and Qal'at Sherqat, was the capital of the Middle Assyrian Empire for a time, of the Neo-Assyrian Empire (911–609 BC) and a semi-independent state during the Parthian Empire between the 2nd century BC and mid 3rd century AD. The remains of the city lie on the western bank of the Tigris River, north of the confluence with its tributary, the Little Zab, in what is now Iraq, more precisely in the al-Shirqat District of the Saladin Governorate.","built":"2500 BC"},
  "assisi": {"article":"Basilica of Saint Francis of Assisi","text":"The Basilica of Saint Francis of Assisi is the mother church of the Roman Catholic Order of Friars Minor Conventual in Assisi, a town in the Umbria region in central Italy, where Saint Francis was born and died. It is a papal minor basilica and one of the most important places of Christian pilgrimage in Italy. With its accompanying friary, Sacro Convento, the basilica is a distinctive landmark to those approaching Assisi.","built":"1228","architects":["Elias of Cortona","Lapo Tedesco","Bernardo Rossellino"]},
  "astronomical-clock": {"article":"Prague astronomical clock","text":"The Prague astronomical clock, or Prague Orloj, is a medieval astronomical clock attached to the Old Town Hall in Prague, the capital of the Czech Republic.","built":"1410"},
  "avdat": {"article":"Avdat","text":"Avdat or Ovdat, and Abdah or Abde, are the modern names of an archaeological site corresponding to the ancient Nabataean, Roman and Byzantine settlement of Oboda or Eboda (Ptolemaeus 5:16, 4) in the Negev desert in southern Israel. It was inhabited with intermissions between the 3rd century BCE and the mid-7th century CE by Nabataeans, in their time becoming the most important city on the Incense Route after Petra, then by Roman army veterans, and Byzantines, and habitation continued well into the Early Muslim period."},
  "avignon": {"article":"Palais des Papes","text":"The Palais des Papes in Avignon, Southern France, is one of the largest and most important medieval Gothic buildings in Europe. Once a fortress and palace, the papal residence was a seat of Western Christianity during the 14th century. Six papal conclaves were held in the Palais, leading to the elections of Benedict XII in 1334, Clement VI in 1342, Innocent VI in 1352, Urban V in 1362, Gregory XI in 1370 and Benedict XIII in 1394.","architects":["Pierre Poisson","Jean de Louvres","Bertran Nogayrol"]},
  "avila": {"article":"Walls of Ávila","text":"The Walls of Ávila, completed between the 11th and 14th centuries, are the defensive walls of Ávila, Spain, and its principal historic feature. Forming a complete circuit around the old town, they are one of the country's most complete and best-preserved medieval fortifications and among the most notable examples in Europe."},
  "ayutthaya": {"article":"Wat Phra Si Sanphet","text":"Wat Phra Si Sanphet was the holiest temple on the site of the old Royal Palace in Thailand's ancient capital of Ayutthaya until the city was completely destroyed by the Burmese in 1767, during the Burmese–Siamese War.","built":"1350"},
  "baalbek": {"article":"Baalbek","text":"Baalbek is a city located east of the Litani River in Lebanon's Beqaa Valley, about 67 km (42 mi) northeast of Beirut. It is the capital of Baalbek-Hermel Governorate. In 1998, the city had a population of 82,608. Most of the population consists of Shia Muslims, followed by Sunni Muslims and Christians; in 2017, there was also a large presence of Syrian refugees.","elevation":1170},
  "bab-mansour": {"article":"Bab Mansur al-'Alj","text":"Bab Mansur al-'Alj or Bab Mansour (also variously spelled as Bab Mansour al-'Ilj, Bab Mansour al-Eulj, Bab el-Mansour, Bab Mansur, etc.) is a monumental gate in the city of Meknes, Morocco. Located on the south side of Place el-Hedim (el-Hedim Square) in the old city, it was originally the main ceremonial entrance to the Kasbah (royal citadel) of Sultan Moulay Isma'il, built in the late 17th and early 18th centuries.","built":"1732"},
  "babylon": {"article":"Ishtar Gate","text":"The Ishtar Gate was the eighth gate to the inner city wall of Babylon (in the area of present-day Hillah, Babylon Governorate, Iraq). It was constructed c. 569 BC by order of King Nebuchadnezzar II on the north side of the city. It was part of a grand walled processional way leading into the city. The original structure was a double gate with a smaller frontal gate and a larger and more grandiose secondary posterior section.","built":"575 BC"},
  "bagan": {"article":"Bagan","text":"Bagan is a medieval city and a UNESCO World Heritage Site in the Mandalay Region of Myanmar. From the 9th to 13th centuries, the city was the capital of the Pagan Kingdom, the first kingdom that unified the regions that would later constitute Myanmar. During the kingdom's height between the 11th and 13th centuries, more than 10,000 Buddhist temples, pagodas and monasteries were constructed in the Bagan plains alone, of which the remains of over 2,300 temples and pagodas survive.","built":"2nd century"},
  "bagerhat": {"article":"Sixty Dome Mosque","text":"The Sixty Dome Mosque is a historical mosque, located in Bagerhat, in the Khulna Division of Bangladesh. It is a part of the Mosque City of Bagerhat, a UNESCO World Heritage Site. It is the largest mosque in Bangladesh from the Bengal Sultanate period (1352–1576). It was built by Khan Jahan Ali, the governor of the Sundarbans."},
  "bahai-gardens": {"article":"Baháʼí World Centre buildings","text":"The Baháʼí World Centre buildings are buildings that are part of the Baháʼí World Centre in Israel. The Baháʼí World Centre buildings include both the Baháʼí holy places used for pilgrimage and the international administrative bodies of the Baháʼí Faith; they comprise more than 20 different administrative offices, pilgrim buildings, libraries, archives, historical residences, and shrines."},
  "bahla-fort": {"article":"Bahla Fort","text":"Bahla Fort is one of four historic fortresses situated at the foot of the Jebel Akhdar highlands in Oman and was the country's first UNESCO-listed fort added in 1987. In 1988, the Archaeological Sites of Bat, Al-Khutm and Al-Ayn became the second Omani site to be declared World Heritage by UNESCO. Bahla Fort underwent massive restoration efforts and reopened in 2012."},
  "bali-subak": {"article":"Subak (irrigation)","text":"Subak is the water management (irrigation) system for the paddy fields on Bali island, Indonesia. It was developed in the 9th century. For the Balinese, irrigation is not simply providing water for the plant's roots, but water is used to construct a complex, pulsed artificial ecosystem that is at the same time autonomous and interdependent."},
  "bam-citadel": {"article":"Arg-e Bam","text":"The Arg-e Bam, located in the city of Bam, Kerman province of southeastern Iran, is the largest adobe building in the world. The entire building was a large fortress containing the citadel, but because the citadel dominates the ruins, the entire fortress is now named Bam Citadel. Listed by UNESCO as part of the World Heritage Site \"Bam and its Cultural Landscape\", it can be traced back to at least the Achaemenid Empire (sixth to fourth centuries BC).","built":"5th century BC"},
  "bamberg": {"article":"Bamberg","text":"Bamberg is a town in Upper Franconia, Bavaria, Germany, on the river Regnitz close to its confluence with the river Main. Bamberg had 79,000 inhabitants in 2022. The town dates back to the 9th century, when its name was derived from the nearby Babenberch castle. Cited as one of Germany's most beautiful towns, with medieval streets and buildings, the old town of Bamberg with around 2,400 timber houses has been a UNESCO World Heritage Site since 1993.","elevation":262},
  "bamiyan": {"article":"Buddhas of Bamiyan","text":"The Buddhas of Bamiyan were two monumental Buddhist reliefs in the Bamiyan Valley of what is now Afghanistan, carved possibly around the 6th-century. Located 130 kilometres (81 mi) to the northwest of Kabul, at an elevation of 2,500 metres (8,200 ft), carbon dating of the structural components of the Buddhas has determined the smaller 38 m (125 ft) \"Eastern Buddha\" was built around 570 CE, and the larger 55 m (180 ft) \"Western Buddha\" was built around 618, which would date both to the time when the Hephthalites ruled the region.","height":53},
  "banaue": {"article":"Banaue Rice Terraces","text":"The Banaue Rice Terraces are terraces that were carved into the mountains of Banaue, Ifugao, in the Philippines, by the ancestors of the Igorot people. The terraces were built with minimal equipment, largely by hand. The terraces are located approximately 1,500 meters (4,900 feet) above sea level. These are fed by an ancient irrigation system from the rainforests above the terraces."},
  "barumini": {"article":"Su Nuraxi (Barumini)","text":"Su Nuraxi is a Nuragic archaeological site in Barumini, Sardinia, Italy. Su Nuraxi simply means \"The Nuraghe\" in Campidanese, the southern variant of the Sardinian language. Su Nuraxi is a settlement consisting of a seventeenth century BC nuraghe, a bastion of four corner towers plus a central one, and a village inhabited from the thirteenth to the sixth century BC, developed around the nuraghe."},
  "bassae": {"article":"Bassae","text":"Bassae is an archaeological site in Oichalia, a municipality in the northeastern part of Messenia, Greece. In classical antiquity, it was part of Arcadia. Bassae lies at an elevation of 1,131 m above sea level on the slopes of Cotylion Mountain. near the village of Skliros, northeast of Figaleia, south of Andritsaina and west of Megalopolis."},
  "bat-tombs": {"article":"Archaeological Sites of Bat, Al-Khutm and Al-Ayn","text":"The Archaeological Sites of Bat, Al-Khutm and Al-Ayn are a group of beehive tombs or necropolis from the Hafit period in the 3rd Millennium BC, located near a palm grove in Oman. They were declared World Heritage by UNESCO in 1988, becoming only the second such Omani site after the Bahla Fort was designated world heritage in 1987."},
  "batalha": {"article":"Batalha Monastery","text":"The Monastery of Batalha is a Dominican convent in the municipality of Batalha, historical Beira Litoral province, in the Centro of Portugal. Originally, and officially, known as the Monastery of Saint Mary of the Victory, it was erected in commemoration of the 1385 Battle of Aljubarrota and would serve as the burial church of the 15th-century Aviz dynasty of Portuguese royalty.","built":"1386","architects":["Afonso Domingues","Mateus Fernandes"]},
  "bath": {"article":"Bath, Somerset","text":"Bath is a city in Somerset, England, known for and named after its Roman-built baths. The city became a UNESCO World Heritage Site in 1987, and was later listed as one of the \"Great Spa Towns of Europe\". Bath is situated in the valley of the River Avon, 97 miles (156 km) west of London and 11 miles (18 km) southeast of Bristol, and is the largest city and urban settlement in Somerset.","built":"AD 43","elevation":132},
  "bauhaus": {"article":"Bauhaus Dessau","text":"Bauhaus Dessau, also Bauhaus-Building Dessau, is a building-complex in Dessau-Roßlau. It is considered the pinnacle of pre-war modern design in Europe and originated out of the dissolution of the Weimar School and the move by local politicians to reconcile the city's industrial character with its cultural past. The building was constructed between 1925 and 1926 according to plans by Walter Gropius as a school building for the Bauhaus School of Art, Design and Architecture.","architects":["Walter Gropius"]},
  "bayreuth-opera": {"article":"Margravial Opera House","text":"The Margravial Opera House is a Baroque opera house in the town of Bayreuth, Germany. Built between 1745 and 1750, it is one of Europe's few surviving theatres of the period and has been extensively restored. On 30 June 2012, the opera house was added to the UNESCO World Heritage List because of its exceptional Baroque architecture.","built":"1744","architects":["Joseph Saint-Pierre"]},
  "beaufort-castle": {"article":"Beaufort Castle, Lebanon","text":"Beaufort or Belfort Castle, known locally as Qal'at al-Shaqif or Shaqif Arnun, is a Crusader fortress in Nabatieh Governorate, Southern Lebanon, about 1 kilometre (0.62 mi) to the south-south-east of the village of Arnoun. There was a fortification on the site before it was captured by Fulk, King of Jerusalem, in 1139 and construction of the Crusader castle probably began soon after.","built":"12th century","elevation":717},
  "belem-tower": {"article":"Belém Tower","text":"Belém Tower, officially the Tower of Saint Vincent, is a 16th-century fortification located in Lisbon, Portugal, which served as a point of embarkation and disembarkation for Portuguese explorers and as a ceremonial gateway to Lisbon. The tower symbolizes Portugal's maritime and colonial power in early modern Europe. It was built during the height of the Portuguese Renaissance and is a prominent example of the Portuguese Manueline style, but it also incorporates other architectural styles, such as the minarets, which are inspired by Moorish architecture.","built":"1515","height":35,"architects":["Francisco de Arruda"]},
  "bellas-artes": {"article":"Palacio de Bellas Artes","text":"The Palacio de Bellas Artes (\"Palace of Fine Arts\") is a prominent cultural center in Mexico City. It hosts performing arts events, literature events and plastic arts galleries and exhibitions (including important permanent Mexican murals). \"Bellas Artes\" for short, has been called the \"art cathedral of Mexico\", and is located on the western side of the historic center of Mexico City which is close to the Alameda Central park.","built":"1934","height":53,"architects":["Adamo Boari","Federico Ernesto Mariscal Piña"]},
  "bellinzona": {"article":"Castles of Bellinzona","text":"The Castles of Bellinzona are a group of fortifications located around the town of Bellinzona, the capital of the Swiss canton of Ticino. Situated on the Alpine foothills, the group is composed of fortified walls and three castles named Castelgrande, Montebello and Sasso Corbaro. Castelgrande is located on a rocky peak overlooking the valley, with a series of walls that protect the old city and connect to Montebello."},
  "beni-hammad": {"article":"Qal'at Bani Hammad","text":"Qal'at Bani Hammad, also known as Qal'a Bani Hammad or Qal'at of the Beni Hammad (among other variants), is a fortified palatine city in Algeria. Now in ruins, in the 11th century, it served as the first capital of the Hammadid dynasty. It is in the Hodna Mountains northeast of M'Sila, at an elevation of 1,418 metres (4,652 ft), and receives abundant water from the surrounding mountains.","built":"1007"},
  "besancon": {"article":"Citadel of Besançon","text":"The Citadel of Besançon is a 17th-century fortress in Franche-Comté, France. It is one of the finest masterpieces of military architecture designed by Sébastien Le Prestre de Vauban. The Citadel occupies 11 hectares (27 acres) on Mount Saint-Etienne, one of the seven hills that protect Besançon, the capital of Franche-Comté.","built":"1668","architects":["Sébastien Le Prestre de Vauban"]},
  "biertan": {"article":"Biertan fortified church","text":"The Biertan fortified church is a Lutheran fortified church in Biertan, Sibiu County, in the Transylvania region of Romania. It was built by the ethnic German Transylvanian Saxon community at a time when the area belonged to the Kingdom of Hungary. Briefly Roman Catholic, it became Evangelical Lutheran following the Reformation.","built":"1524"},
  "big-ben": {"article":"Big Ben","text":"Big Ben is the nickname for the Great Bell of the Great Clock of Westminster, and, by extension, for the clock tower that stands at the north end of the Palace of Westminster in London, England. Originally named the Clock Tower, the structure was renamed the Elizabeth Tower in 2012 to mark the Diamond Jubilee of Queen Elizabeth II.","built":"1843","height":96,"architects":["Augustus Pugin","Charles Barry"]},
  "bijagos": {"article":"Bijagós Islands","text":"The Bijagós Islands, often misspelled Bijagos in English text and formerly known in English as Bissagots (often misspelled Bissagos), are a group of about 88 islands and islets located in the Atlantic Ocean off the coast of Guinea-Bissau."},
  "bikini-atoll": {"article":"Bikini Atoll","text":"Bikini Atoll, known as Eschscholtz Atoll between the 19th century and 1946, is a coral reef in the Marshall Islands consisting of 23 islands surrounding a 229.4-square-mile (594.1 km2) central lagoon. The atoll is at the northern end of the Ralik Chain, approximately 530 miles (850 km) northwest of the capital Majuro. After the Second World War, the atoll was chosen by the United States as a nuclear weapon testing site.","elevation":25},
  "blenheim": {"article":"Blenheim Palace","text":"Blenheim Palace is a country house in Woodstock, Oxfordshire, England. It is the seat of the Dukes of Marlborough, and the birthplace of Sir Winston Churchill. Originally called Blenheim Castle, it has been known as Blenheim Palace since the 19th century. One of England's largest houses, it was built between 1705 and 1722, and was designated a UNESCO World Heritage Site in 1987.","built":"1705","elevation":95},
  "blue-mosque": {"article":"Blue Mosque, Istanbul","text":"The Sultan Ahmed Mosque, popularly known as the Blue Mosque, is an Ottoman-era historical imperial mosque located in Istanbul, Turkey. It was constructed between 1609 and 1617 during the rule of Ahmed I. It attracts a large number of tourists and is one of the most iconic and popular monuments of Ottoman architecture. The mosque has a classical Ottoman layout with a central dome surrounded by four semi-domes over the prayer hall.","built":"1609","height":64,"architects":["Sedefkar Mehmed Ağa"]},
  "blue-mountains": {"article":"Blue and John Crow Mountains National Park","text":"Blue and John Crow Mountains National Park is a national park in Jamaica. The park covers 495.2 km2 and accounts for 4.5% of Jamaica's land surface. It derives its name from the Blue Mountains, the mountain range that runs through it, as well as from the common bird found in the park, the \"John crow\" (turkey vulture, Cathartes aura).","built":"1993"},
  "boat-lifts": {"article":"Boat Lifts on the Canal du Centre","text":"The lifts on the Canal du Centre are a series of four hydraulic boat lifts near the town of La Louvière in Belgium which are classified as a World Heritage Site by UNESCO. All four are located on the Canal du Centre in Belgium's historic sillon industriel industrial belt."},
  "boboli": {"article":"Boboli Gardens","text":"The Boboli Gardens is a large park in Florence, originally designed as the garden of the Medici family's Pitti Palace in the mid-16th century. It is an important early Italian garden which influenced aristocratic gardens across Europe. It houses statues of various styles and periods, large fountains, and artificial grottoes.","built":"1766"},
  "bock-casemates": {"article":"Bock (Luxembourg)","text":"The Bock is a promontory in the eastern corner of Luxembourg City's historical upper town, the Ville Haute. It was here that Count Siegfried built his Castle of Lucilinburhuc in 963, providing a basis for the development of the town that became Luxembourg. Over the centuries, the Bock and the surrounding defenses were reinforced, attacked, and rebuilt time and time again, as the armies of the Burgundians, Habsburgs, Spaniards, Prussians, and French vied for victory over one of Europe's most strategic strongholds, the Fortress of Luxembourg."},
  "bologna-towers": {"article":"Two Towers, Bologna","text":"The Two Towers, both leaning, are symbols of Bologna, Italy, and the most prominent of the Towers of Bologna. They are located at the intersection of the roads that lead to the five gates of the old ring wall (mura dei torresotti). The taller one is the Asinelli; the smaller, with a greater lean, is the Garisenda. They are named for the families which are traditionally credited with having constructed them between 1109 and 1119."},
  "bom-jesus-braga": {"article":"Sanctuary of Bom Jesus do Monte","text":"The Sanctuary of Bom Jesus do Monte is a Portuguese Catholic shrine in Tenões, outside the city of Braga, in northern Portugal. Its name means Good Jesus of the Mount. This sanctuary is a notable example of Christian pilgrimage site with a monumental, Baroque stairway that climbs 116 meters (381 feet). It is an important tourist attraction in Braga.","built":"1772"},
  "bom-jesus-goa": {"article":"Basilica of Bom Jesus","text":"The Basilica of Bom Jesus is a Catholic basilica in Goa, in the Konkan region of India. The church is a pilgrimage centre and recognised by UNESCO as a World Heritage Site. The basilica is located in Old Goa, the former capital of Portuguese India, and holds the body of St Francis Xavier. Bom Jesus (meaning, \"Good Jesus\" in Portuguese) is the name used for the Ecce Homo in Portuguese speaking countries.","built":"1605"},
  "boma": {"article":"Boma National Park","text":"Boma National Park is a protected area in eastern South Sudan near the Ethiopian border. It was established in 1977 and covers 22,800 km2 (8,800 sq mi) of grasslands and floodplains. The park is in the Somali-Maasai and Sudano-Guinean biomes. The southern part of the park has extensive short grasslands and acacia bush.","built":"1986"},
  "bordeaux": {"article":"Place de la Bourse, Bordeaux","text":"The Place de la Bourse is a square in Bordeaux, France, and one of the city's most recognisable sights. Built from 1730 to 1775 along the river Garonne, it was a multi-building development designed by the architect Jacques Gabriel and his son Ange-Jacques Gabriel. It is within the historic part of the city that has been recognized on the UNESCO World Heritage List as \"an outstanding urban and architectural ensemble\" of the 18th century.","built":"1749"},
  "borobudur": {"article":"Borobudur","text":"Borobudur, also transcribed Barabudur, is a 9th-century Mahayana Buddhist temple in Magelang Regency, near the town of Muntilan, northwest of the city of Yogyakarta, in Central Java, Indonesia. Constructed of gray andesite-like stone, the temple consists of nine stacked platforms, six square and three circular, topped by a central dome.","built":"8th century","architects":["Gunadharma"]},
  "bosra": {"article":"Ancient City of Bosra","text":"The Ancient City of Bosra is an archaeological site located in the city of Bosra, Syria. The site illustrates the Roman, Byzantine and Muslim civilizations, and was inscribed by UNESCO on the list of World Heritage Sites in 1980.","built":"1980"},
  "botanic-gardens": {"article":"Singapore Botanic Gardens","text":"The Singapore Botanic Gardens is a tropical garden located at the fringe of the Orchard Road shopping district in Singapore. It is one of three gardens, and the only tropical garden, to be honoured as a UNESCO World Heritage Site. The Botanic Gardens was founded at its present site in 1859 by the Agri-horticultural Society.","built":"1859","elevation":33},
  "boudhanath": {"article":"Boudha Stupa","text":"Boudha Stupa, Boudhanath Stupa, also known as Khasti Chaitya or Khāsa Chaitya, is a stupa and major spiritual landmark seen as the embodiment of the enlightened mind of all the Buddhas. Located in the northeast of Kathmandu Valley within the city of Kathmandu, Nepal and originally surrounded by rice paddies, the stupa is said in one text to have given birth to Tibetan Buddhism.","height":36},
  "bourges-cathedral": {"article":"Bourges Cathedral","text":"Bourges Cathedral or the Cathedral of Saint Stephen of Bourges is a Roman Catholic church located in Bourges, France. The cathedral is dedicated to Saint Stephen and is the seat of the Archbishop of Bourges. Built atop an earlier Romanesque church from 1195 until 1230, it is largely in the High Gothic or Classic Gothic architectural style and was constructed at about the same time as Chartres Cathedral.","built":"1195","architects":["Antoine-Nicolas Bailly","Colin Biard","Paul Boeswillwald"]},
  "boyana": {"article":"Boyana Church","text":"The Boyana Church is a medieval Bulgarian Orthodox church situated on the outskirts of Sofia, the capital of Bulgaria, in the Boyana quarter. In 1979, the building was added to the UNESCO World Heritage List. The east wing of the two-story church was originally constructed in the late 10th or early 11th century, then the central wing was added in the 13th century under the Second Bulgarian Empire, the whole building being finished with a further expansion to the west in the middle of the 19th century.","built":"10th century"},
  "bran-castle": {"article":"Bran Castle","text":"Bran Castle is a castle in Bran, 25 kilometres (16 mi) southwest of Brașov. The castle was built by Saxons in 1377 who were given the privilege by Louis I of Hungary. It is a national monument and landmark in Transylvania. The fortress is on the Transylvanian side of the historical border with Wallachia, on road DN73. Marketed outside Romania as Dracula's Castle, it is presented as the home of the title character in Bram Stoker's novel Dracula (1897).","built":"1289"},
  "brandenburg-gate": {"article":"Brandenburg Gate","text":"The Brandenburg Gate is an 18th-century neoclassical monument in Berlin, Germany. One of the best-known landmarks of the country, it was erected on the site of a former city gate that marked the start of the road from Berlin to Brandenburg an der Havel, the former capital of the Margraviate of Brandenburg. The current structure was built from 1788 to 1791 by orders of King Frederick William II of Prussia, based on designs by the royal architect Carl Gotthard Langhans.","built":"1791","height":26,"architects":["Carl Gotthard Langhans","Heinrich Strack"]},
  "brasilia": {"article":"Brasília","text":"Brasília is the capital city of Brazil and the Federal District. Located in the Brazilian Highlands in the country's Central-West region, it was founded by President Juscelino Kubitschek on 21 April 1960, to replace Rio de Janeiro as the national capital. Brasília is Brazil's third-most populous city after São Paulo and Rio de Janeiro, with a population of 2.8 million.","built":"1960","elevation":1171,"architects":["architectural ensemble"]},
  "bremen-roland": {"article":"Bremen Roland","text":"The Bremen Roland is a statue of Roland, erected in 1404. It stands in the market square (Rathausplatz) of Bremen, Germany, facing the cathedral, and shows Roland, paladin of the first Holy Roman Emperor Charlemagne and hero of the Battle of Roncevaux Pass. Statues of Roland appear in numerous cities of the former Holy Roman Empire, as emblems of city liberties, Stadtrechte.","height":5.5},
  "bridgetown": {"article":"Bridgetown","text":"Bridgetown (UN/LOCODE: BB BGI) is the capital and largest city of Barbados. Formerly The Town of Saint Michael, the Greater Bridgetown area is located within the parish of Saint Michael. Bridgetown is sometimes locally referred to as \"The City\", but the most common reference is simply \"Town\". As of 2014, its metropolitan population stands at roughly 110,000.","built":"1628","elevation":1},
  "brihadeeswarar": {"article":"Brihadisvara Temple","text":"Brihadisvara Temple, called Rajarajesvaram by its builder, and known locally as Thanjai Periya Kovil and Peruvudaiyar Kovil, is a Shaivite Hindu temple built in a Chola architectural style located on the south bank of the Cauvery river in Thanjavur, Tamil Nadu, India. It is one of the largest Hindu temples and an exemplar of Tamil architecture.","built":"1010","height":66},
  "brimstone-hill": {"article":"Brimstone Hill Fortress National Park","text":"Brimstone Hill Fortress National Park is a UNESCO World Heritage Site, a well-preserved fortress on a hill on the island of St. Kitts, in the Federation of St. Christopher (St. Kitts) and Nevis in the Eastern Caribbean. It was designed by British military engineers, and was built and maintained by enslaved Africans. It is one of the best preserved historical fortifications in the Americas.","built":"1987"},
  "bruges": {"article":"Bruges","text":"Bruges is the capital and largest city of the province of West Flanders, in the Flemish Region of Belgium. It is located in the northwest of the country, and is the sixth most populous city in Belgium. The predominant language is Dutch (West Flemish). The area of the whole city amounts to more than 14,099 hectares, including 1,075 hectares off the coast, at Zeebrugge (from Brugge aan zee, meaning 'Bruges by the Sea').","elevation":2},
  "bruhl": {"article":"Augustusburg and Falkenlust Palaces, Brühl","text":"The Augustusburg and Falkenlust Palaces form a historical building complex in Brühl, North Rhine-Westphalia, Germany. The buildings are connected by the spacious gardens and trees of the Schlosspark. Built in the early 18th century, the palaces and adjoining gardens are considered masterpieces of early rococo architecture and have been listed as a UNESCO cultural World Heritage Site since 1984."},
  "bryggen": {"article":"Bryggen","text":"Bryggen ('the dock'), also known as Tyskebryggen, is a series of Hanseatic heritage commercial buildings lining up the eastern side of the Vågen harbour in the city of Bergen, Norway. Bryggen has been on the UNESCO list for World Cultural Heritage sites since 1979. The city of Bergen was founded around 1070 within the boundaries of Tyskebryggen."},
  "buckingham-palace": {"article":"Buckingham Palace","text":"Buckingham Palace is the official residence and administrative headquarters of the monarch of the United Kingdom in London, England. Located in the City of Westminster, the palace is often at the centre of state occasions and royal hospitality. It has been a focal point for the British people at times of national rejoicing and mourning.","built":"1703","elevation":6.1,"architects":["William Winde","John Nash"]},
  "buda-castle": {"article":"Buda Castle","text":"Buda Castle, formerly also called the Royal Palace and the Royal Castle, is the historical castle and palace complex of the Hungarian kings in Budapest. First completed in 1265, the Baroque palace that occupies most of the site today was built between 1749 and 1769, severely damaged during the Siege of Budapest in World War II, and rebuilt in a simplified Baroque style during the state communist era.","built":"1244","architects":["Jean-Nicolas Jadot de Ville-Issey","Miklós Ybl","Alajos Hauszmann"]},
  "bukhara": {"article":"Kalyan Minaret","text":"The Kalyan Minaret is a minaret of the Po-i-Kalyan mosque complex in Bukhara, Uzbekistan and one of the most prominent landmarks in the city. The minaret, designed by Bako, was built on an earlier existing structure called Kalyan by the Qarakhanid ruler Mohammad Arslan Khan in 1127 to summon Muslims to prayer five times a day.","built":"1127"},
  "bulguksa": {"article":"Bulguksa","text":"Bulguksa is a Buddhist temple on Tohamsan, in Jinhyeon-dong, Gyeongju, North Gyeongsang Province, South Korea. It is a head temple of the Jogye Order of Korean Buddhism and contains six National Treasures, including the Dabotap and Seokgatap stone pagodas, Cheongun-gyo (Blue Cloud Bridge), and two gilt-bronze statues of Buddha."},
  "bunce-island": {"article":"Bunce Island","text":"Bunce Island (also spelled \"Bence,\" \"Bense,\" or \"Bance\" at different periods) is an island in the Sierra Leone River. It is situated in the estuary of the Rokel River and Port Loko Creek, about 20 miles (32 kilometres) upriver from Sierra Leone's capital city Freetown. The island measures about 1,650 feet (502.9 metres) by 350 feet (106.7 metres) and houses a castle that was built by the Royal Africa Company in c.1670."},
  "burgos-cathedral": {"article":"Burgos Cathedral","text":"The Metropolitan Cathedral Basilica Cathedral of Saint Mary is a Catholic church dedicated to the Virgin Mary located in the historical center of the Spanish city of Burgos. Its construction began in 1221, in the style of French Gothic architecture and is based on a Latin cross. After a hiatus of almost 200 years, it went through major embellishments of great splendor in the 15th and 16th centuries: the spires of the main facade, the capilla del Condestable, 'Chapel of the Constable' and dome of the transept.","built":"1221"},
  "burj-khalifa": {"article":"Burj Khalifa","text":"The Burj Khalifa (previously known as Burj Dubai prior to inauguration) is a megatall skyscraper in Dubai, United Arab Emirates. Designed by Skidmore, Owings & Merrill, it is the world's tallest structure, with a total height of 829.8 m (2,722 ft, or just over half a mile) and a roof height (excluding the antenna, but including a 242.6 m spire) of 828 m (2,717 ft).","built":"2004","height":828,"architects":["Adrian Smith","Marshall Strabala","George J. Efstathiou"]},
  "bursa": {"article":"Green Mosque, Bursa","text":"The Green Mosque, also known as the Mosque of Mehmed I, is a part of a larger complex (külliye) in eastern Bursa, Turkey, the former capital of the Ottoman Turks before Constantinople was captured in 1453. The complex consists of a mosque, a mausoleum known as the Green Tomb, a madrasa, a public kitchen, and a bathhouse.","built":"1420","architects":["Hacı İvaz Paşa"]},
  "butrint": {"article":"Butrint","text":"Butrint was an ancient Greek polis and later Roman city and the seat of an early Christian bishopric in Epirus. Originally a settlement of the Greek tribe of the Chaonians, it later became part of the state of Epirus and later a Roman colonia and a Byzantine bishopric. It entered into decline in Late Antiquity, before being abandoned during the Middle Ages after a major earthquake flooded most of the city."},
  "byblos": {"article":"Byblos Castle","text":"Byblos Castle is a Crusader castle in Byblos, Lebanon. In Crusader times it was known as the Castle of Gibelet, also spelled Giblet, which belonged to the Genoese Republic Embriaco family, Lords of the city. It is adjacent to the Phoenician archaeological site containing the ruins of the Temple of Baalat Gebal and the Temple of the Obelisks.","built":"1103"},
  "caernarfon-castle": {"article":"Caernarfon Castle","text":"Caernarfon Castle is a medieval fortress in Gwynedd, north-west Wales. The first fortification on the site was a motte-and-bailey castle built in the late 11th century, which King Edward I of England began to replace with the current stone structure in 1283. The castle and town established by Edward acted as the administrative centre of north Wales, and as a result the defences were built on a grand scale.","built":"1283","elevation":9.6,"architects":["James of Saint George","Walter de Hereford"]},
  "cahokia": {"article":"Cahokia","text":"The Cahokia Mounds is the site of a Native American city which existed c. 1050 – c. 1350 AD, directly across the Mississippi River from present-day St. Louis. The state archaeology park lies in south-western Illinois between East St. Louis and Collinsville. The park covers 2,200 acres, and contains about 80 manmade mounds, but the ancient city was much larger.","built":"1050"},
  "california-lighthouse": {"article":"California Lighthouse","text":"The California Lighthouse, known by locals as Faro stands tall on a limestone plateau at Hudishibana, near Arashi Beach and Sasariwichi dunes on the northwestern tip of Aruba. It holds the distinction of being the tallest structure in Aruba. This lighthouse derives its name from a British steamship, S.S. California, which sank in 1891, predating the lighthouse's construction (c. 1914–1916).","built":"1914","height":30},
  "canterbury-cathedral": {"article":"Canterbury Cathedral","text":"Canterbury Cathedral is the cathedral of the archbishop of Canterbury, the spiritual leader of the Church of England and symbolic leader of the worldwide Anglican Communion. Located in Canterbury, Kent, it is on the site of one of the oldest Christian structures in England and forms part of a World Heritage Site. Its formal title is the Cathedral and Metropolitical Church of Christ, Canterbury.","built":"7th century","height":72,"architects":["William of Sens","William the Englishman"]},
  "cape-coast-castle": {"article":"Cape Coast Castle","text":"Cape Coast Castle is one of about forty \"slave castles\", or large commercial forts, built on the Gold Coast of West Africa (now Ghana) by European traders. Cape Coast Castle is located in the Central Region of Ghana. It was originally a Portuguese \"feitoria\" or trading post, established in 1555, which was named Cabo Corso, meaning \"Short Cape.\"","built":"1653"},
  "cappadocia": {"article":"Cappadocia","text":"Cappadocia is a historical region in Central Anatolia region, Turkey. It is largely in the provinces of Nevşehir, Kayseri, Aksaray, Kırşehir, Sivas and Niğde. Today, the touristic Cappadocia Region is located in Nevşehir province. According to Herodotus, in the time of the Ionian Revolt (499 BC), the Cappadocians were reported as occupying a region from the Taurus Mountains to the vicinity of the Euxine (Black Sea)."},
  "caracas-university": {"article":"University City of Caracas","text":"The University City of Caracas, also known by the acronym CUC, is the main campus of the Central University of Venezuela (UCV), located in central Caracas, the capital of Venezuela. It was designed by the Venezuelan architect Carlos Raúl Villanueva and was declared a World Heritage Site by UNESCO in 2000. The Ciudad Universitaria de Caracas is considered a \"masterpiece\" of architecture and urban planning, and greatly influenced Venezuelan architecture."},
  "caral": {"article":"Caral","text":"The Sacred City of Caral-Supe, or simply Caral, is an archaeological site in Peru where the remains of the main city of the Caral civilization are found. It is located in the Supe District of Peru, near the current town of Caral, 182 kilometres (113 mi) north of Lima, 23 kilometres (14 mi) from the coast and 350 meters above sea level."},
  "carbet-falls": {"article":"Carbet Falls","text":"Carbet Falls is a series of waterfalls on the Carbet River in Guadeloupe, an overseas department of France located in the Leeward Islands of the eastern Caribbean region. Its three cascades are set amid the tropical rainforests on the lower slopes of the volcano La Soufrière. The falls are one of the most popular visitor sites in Guadeloupe, with approximately 400,000 visitors annually.","height":245},
  "carcassonne": {"article":"Carcassonne","text":"Carcassonne is a French city in the department of Aude, region of Occitania. It is the prefecture of the department. Inhabited since the Neolithic Period, Carcassonne is located in the plain of the Aude between historic trade routes, linking the Atlantic to the Mediterranean Sea and the Massif Central to the Pyrénées. Its strategic importance was quickly recognised by the Romans, who occupied its hilltop until the demise of the Western Roman Empire.","elevation":111},
  "carnac": {"article":"Carnac stones","text":"The Carnac stones are an exceptionally dense collection of megalithic sites near the south coast of Brittany in northwestern France, consisting of stone alignments (rows), dolmens (stone tombs), tumuli (burial mounds), and single menhirs. More than 3,000 prehistoric standing stones were hewn from local granite and erected by the pre-Celtic people of Brittany and form the largest such collection in the world."},
  "cartagena": {"article":"Cartagena, Colombia","text":"Cartagena, known since the imperial era as Cartagena de Indias, is a city and one of the major ports on the northern coast of Colombia in the Caribbean Coast Region, along the Caribbean Sea. Cartagena's past role as a link in the route to the West Indies provides it with important historical value for world exploration and preservation of heritage from the great commercial maritime routes.","built":"1533","elevation":2},
  "carthage": {"article":"Carthage","text":"Carthage was an ancient city in northern Africa founded by the legendary Phoenician queen Dido on the eastern side of the Lake of Tunis in what is now Tunisia. Carthage was one of the most important trading hubs of the Ancient Mediterranean and one of the most affluent cities of the classical world. It became the capital city of the civilization of Ancient Carthage and later Roman Carthage.","built":"9th century BC"},
  "casa-batllo": {"article":"Casa Batlló","text":"Casa Batlló is a building in the center of Barcelona, Spain. It was designed by Antoni Gaudí, and is considered one of his masterpieces. A remodel of a previously built house, it was redesigned in 1904 by Gaudí (although the actual construction had not begun at this point) and has been refurbished several times since. Gaudí's assistants Domènec Sugrañes i Gras, Josep Canaleta and Joan Rubió also contributed to the renovation project.","built":"1877","elevation":33,"architects":["Antoni Gaudí"]},
  "casco-viejo": {"article":"Casco Viejo, Panama","text":"Casco Antiguo (Spanish for Old Quarter), also known as Casco Viejo or San Felipe, is the historic district of Panama City. Completed and settled in 1673, it was built following the near-total destruction of the original Panamá city, Panamá Viejo in 1671, when the latter was attacked by pirates."},
  "caserta": {"article":"Royal Palace of Caserta","text":"The Royal Palace of Caserta is a former royal palace in Caserta, Campania, 35 kilometres (22 mi) north of Naples in southern Italy, constructed by the House of Bourbon-Two Sicilies as their main residence as Kings of Naples. With a volume of around 2 million m3, covering an area of 47,000 m2 and a floor area of 130,000 square metres distributed across five floors, the Royal Palace of Caserta is one of the largest palaces erected in Europe during the 18th century and one of the largest former royal residences in the world.","built":"1752","architects":["Luigi Vanvitelli"]},
  "castel-del-monte": {"article":"Castel del Monte, Apulia","text":"Castel del Monte is a 13th-century citadel and castle situated on a hill in Andria in the Apulia region of southeast Italy. It was built during the 1240s by King Frederick II, who had inherited the lands from his mother Constance of Sicily. In the 18th century, the castle's interior marbles and remaining furnishings were removed.","built":"1240","height":26},
  "castel-nuovo": {"article":"Castel Nuovo","text":"Castel Nuovo, often called Maschio Angioino, is a medieval castle located in front of Piazza Municipio and the city hall (Palazzo San Giacomo) in central Naples, Campania, Italy. Its scenic location and imposing size makes the castle, first erected in 1279, one of the main architectural landmarks of the city. It was a royal seat for kings of Naples, Aragon and Spain until 1815.","built":"1282","architects":["Pierre d'Angicourt"]},
  "castel-sant-angelo": {"article":"Castel Sant'Angelo","text":"Castel Sant'Angelo, also known as Mausoleum of Hadrian, is a towering rotunda in Parco Adriano, Rome, Italy. It was initially commissioned by the Roman Emperor Hadrian as a mausoleum for himself and his family. The popes later used the building as a fortress and castle dedicated to Saint Michael the Archangel, and it is now a museum.","built":"AD 139","architects":["Decriannus"]},
  "catalhoyuk": {"article":"Çatalhöyük","text":"Çatalhöyük is a tell (a mounded accretion resulting from long-term human settlement) of a very large Neolithic and Chalcolithic proto-city settlement in southern Anatolia, which existed from around 7500 BC to 5600 BC and flourished around 7000 BC. Çatalhöyük overlooks the Konya Plain, southeast of the present-day city of Konya (ancient Iconium) in Turkey, around 140 km (87 mi) from the twin-coned volcano of Mount Hasan.","built":"7500 BC"},
  "cedars-of-god": {"article":"Cedars of God","text":"The Cedars of God is a forest in the Kadisha Valley of Bsharre, Lebanon. It is a vestige of the extensive forests of the Lebanon cedar that thrived across Mount Lebanon in antiquity. Early modern travelers' accounts of the wild cedars appear to refer to the ones in Bsharri; the Christian monks of the monasteries in the Kadisha Valley venerated the trees for centuries."},
  "centennial-hall": {"article":"Centennial Hall (Wrocław)","text":"The Centennial Hall, formerly named People's Hall (Hala Ludowa), is a historic building in Wrocław, Poland. It was constructed according to the plans of architect Max Berg in 1911–1913. Max Berg designed Centennial Hall to serve as a multifunctional structure to host \"exhibitions, concerts, theatrical and opera performances, and sporting events\".","built":"1911","architects":["Max Berg"]},
  "cesky-krumlov": {"article":"Český Krumlov","text":"Český Krumlov is a town in the South Bohemian Region of the Czech Republic. It has about 13,000 inhabitants. The town is located on the Vltava River in the Bohemian Forest Foothills. Český Krumlov is known as a tourist centre, which is among the most visited places in the country. The historic centre with the Český Krumlov Castle complex is protected as an urban monument reservation, and since 1992, it has been a designated UNESCO World Heritage Site because of its well-preserved Gothic, Renaissance and Baroque architecture.","elevation":492},
  "chaco": {"article":"Pueblo Bonito","text":"Pueblo Bonito (Spanish for beautiful town) is the largest and best-known great house in Chaco Culture National Historical Park, northern New Mexico. It was built by the Ancestral Puebloans who occupied the structure between AD 828 and 1126. According to the National Park Service, \"Pueblo Bonito is the most thoroughly investigated and celebrated cultural site in Chaco Canyon.","elevation":1870},
  "chain-bridge": {"article":"Széchenyi Chain Bridge","text":"The Széchenyi Chain Bridge is a chain bridge that spans the River Danube between Buda and Pest, the western and eastern sides of Budapest, the capital of Hungary. Designed by English engineer William Tierney Clark and built by Scottish engineer Adam Clark, it was the first permanent bridge across the Danube in Hungary.","built":"1840","architects":["William Tierney Clark"]},
  "chambord": {"article":"Château de Chambord","text":"The Château de Chambord in Chambord, Centre-Val de Loire, France, is one of the most recognisable châteaux in the world because of its very distinctive French Renaissance architecture, which blends traditional French medieval forms with classical Renaissance structures. The building was commissioned by Francis I of France and built between 1519 and 1547.","built":"1519","architects":["Pierre Nepveu","Jacques Sourdeau"]},
  "champaner": {"article":"Champaner-Pavagadh Archaeological Park","text":"Champaner-Pavagadh Archaeological Park, a UNESCO World Heritage Site, is located in Panchmahal district in Gujarat, India. It is centered around the historic city of Champaner, which was founded by Vanraj Chavda, the most prominent king of the Chavda Dynasty, in the eighth century. He named it after his friend and general, Champa, also known later as Champaraj."},
  "chan-chan": {"article":"Chan Chan","text":"Chan Chan, sometimes called Chimor, was the capital city of the Chimor kingdom, a pre-Columbian era culture in South America. The city is now an archeological site in the department of La Libertad five kilometers (3.1 mi) west of Trujillo, Peru. Chan Chan is located in the mouth of the Moche Valley and was the capital of the historical empire of the Chimor from 900 to 1470, when they were defeated and incorporated into the Inca Empire.","built":"AD 850"},
  "changdeokgung": {"article":"Changdeokgung","text":"Changdeokgung is a former royal palace in Seoul, South Korea. A UNESCO World Heritage Site and a Historic Site of South Korea, it is among the best preserved of all Korean palaces. It and its neighboring palace Changgyeonggung have together been called the \"East Palace\". Changdeokgung was established in 1405. It was the second palace to be established in Seoul, after Joseon's official main palace Gyeongbokgung."},
  "charles-bridge": {"article":"Charles Bridge","text":"Charles Bridge is a medieval stone arch bridge that crosses the Vltava river in Prague, Czech Republic. Its construction started in 1357 under the auspices of King Charles IV, and finished in the early 15th century. The bridge replaced the old Judith Bridge built 1158–1172 that had been severely damaged by a flood in 1342.","built":"1357","height":13,"architects":["Peter Parler"]},
  "chartres": {"article":"Chartres Cathedral","text":"Chartres Cathedral is a Catholic cathedral in Chartres, France, about 80 km (50 miles) southwest of Paris, and is the seat of the Bishop of Chartres. Dedicated in honour of the Virgin Mary ('Our Lady'), it was mostly constructed between 1194 and 1220. It stands on the site of at least five cathedrals that have occupied the site since the Diocese of Chartres was formed as an episcopal see in the 4th century.","built":"1145","height":113,"architects":["Master of Chartres"]},
  "chateau-frontenac": {"article":"Château Frontenac","text":"The Fairmont Le Château Frontenac, commonly referred to as the Château Frontenac, is a historic hotel in Quebec City, Quebec, Canada. The hotel is situated in Old Quebec, within the historic district's Upper Town, on the southern side of Place d'Armes. The Château Frontenac was designed by New York architect Bruce Price in the Château style.","built":"1893","architects":["Bruce Price","Daniel John Crighton"]},
  "chavin": {"article":"Chavín de Huántar","text":"Chavín de Huántar is an archaeological site in Peru, containing ruins and artifacts constructed as early as 1200 BC, and occupied until around 400–500 BC by the Chavín, a major pre-Inca culture. The site is located in the Ancash Region, 434 kilometers (270 mi) north of Lima, at an elevation of 3,180 meters (10,430 ft), east of the Cordillera Blanca at the start of the Conchucos Valley."},
  "chengde": {"article":"Putuo Zongcheng Temple","text":"The Putuo Zongcheng Temple of Chengde, Hebei, China is a Buddhist temple complex built between 1767 and 1771. It is located near the Chengde Mountain Resort, which is south of the Putuo Zongcheng. Along with the equally famed Puning Temple, it is one of the Eight Outer Temples of Chengde. The temple was modeled after the Potala Palace of Tibet, the residence of the Dalai Lama built a century earlier.","built":"1771"},
  "cheomseongdae": {"article":"Cheomseongdae","text":"Cheomseongdae is an astronomical observatory in Gyeongju, South Korea. Cheomseongdae is the oldest surviving astronomical observatory in Asia, and possibly even the world. It was constructed during the Silla period, during the reign of Queen Seondeok (r. 632–647 AD). Cheomseongdae was designated as the country's 31st national treasure on December 20, 1962.","built":"7th century"},
  "chernivtsi": {"article":"Residence of Bukovinian and Dalmatian Metropolitans","text":"The Residence of Bukovinian and Dalmatian Metropolitans in Chernivtsi, Ukraine, was built for the Eastern Orthodox metropolitan bishop between 1864 and 1882 to the designs of the Czech architect Josef Hlávka from Austria-Hungary. The Residence, whose buildings are now part of Chernivtsi University, was declared a UNESCO World Heritage Site in 2011.","built":"1864","architects":["Josef Hlávka"]},
  "chichen-itza": {"article":"Chichen Itza","text":"Chichen Itza was a large pre-Columbian city built by the Maya people of the Terminal Classic period. The archeological site is located in Tinúm Municipality, Yucatán, Mexico, between the cities of Valladolid and Mérida. Chichen Itza was a major focal point in the Northern Maya Lowlands from the Late Classic (c. 600–900 AD) through the Terminal Classic (c. 800–900 AD) and into the early portion of the Postclassic period (c. 900–1200 AD).","built":"AD 455"},
  "chillon": {"article":"Chillon Castle","text":"Chillon Castle is a medieval island castle located on Lake Geneva, south of Veytaux in the Swiss canton of Vaud. It is situated at the eastern end of the lake, on the narrow shore between Montreux and Villeneuve, which gives access to the Alpine valley of the Rhône. Chillon is amongst the most visited medieval castles in Europe.","built":"1160","height":25,"architects":["James of Saint George"]},
  "chiloe-churches": {"article":"Churches of Chiloé","text":"The Churches of Chiloé in Chile's Chiloé Archipelago are a unique architectural phenomenon in the Americas and one of the most prominent styles of Chilotan architecture. Unlike classical Spanish colonial architecture, the churches of Chiloé are made entirely in native timber with extensive use of wood shingles. The churches were built from materials to resist the Chiloé Archipelago's humid and rainy oceanic climate."},
  "chinguetti": {"article":"Chinguetti","text":"Chinguetti is a ksar and a medieval trading center in northern Mauritania, located on the Adrar Plateau east of Atar. Chinguetti had a population of 4,800 as of 2013. Founded in the 13th century as the center of several trans-Saharan trade routes, this small city continues to attract a handful of visitors who admire its spare architecture, scenery, and ancient libraries.","elevation":495},
  "chogha-zanbil": {"article":"Chogha Zanbil","text":"Chogha Zanbil is an ancient Elamite complex in the Khuzestan province of Iran. It is one of the few existing ziggurats outside Mesopotamia. It lies approximately 30 km (19 mi) southeast of Susa and 80 km (50 mi) north of Ahvaz. The construction date of the city is unclear due to uncertainty in the chronology of the reign of Untash-Napirisha, but is clearly sometime in the 14th or 13th century BC."},
  "choirokoitia": {"article":"Khirokitia","text":"Khirokitia is an archaeological site on the island of Cyprus dating from the Neolithic age. It has been listed as a World Heritage Site by UNESCO since 1998. The site is known as one of the most important and best preserved prehistoric sites of the eastern Mediterranean. Much of its importance lies in the evidence of an organised functional society in the form of a collective settlement, with surrounding fortifications for communal protection.","built":"7th millennium BC","elevation":156},
  "christ-the-redeemer": {"article":"Christ the Redeemer (statue)","text":"Christ the Redeemer is an Art Deco statue of Jesus in Rio de Janeiro, Brazil, created by French-Polish sculptor Paul Landowski and built by Brazilian engineer Heitor da Silva Costa, in collaboration with French engineer Albert Caquot and Romanian sculptor Gheorghe Leonida who sculpted the face. Constructed between 1922 and 1931, the statue is 30 metres (98 ft) high, excluding its 8-metre (26 ft) pedestal, and faces east.","built":"1920","height":30,"architects":["Albert Caquot","Paul Landowski","Gheorghe Leonida"]},
  "church-of-the-nativity": {"article":"Church of the Nativity","text":"The Church of the Nativity, or Basilica of the Nativity, is a basilica located in Bethlehem, West Bank, Palestine. The grotto holds a prominent religious significance to Christians of various denominations as the birthplace of Jesus. The grotto is the oldest site continuously used as a place of worship in Christianity, and the basilica is the oldest major church in the Holy Land.","built":"AD 327"},
  "churches-of-peace": {"article":"Churches of Peace","text":"The Churches of Peace in Jawor and Świdnica in Lower Silesia. Poland, are 17th-century churches, named after the Peace of Westphalia of 1648. The treaty granted the Lutherans of Silesia to build three churches from wood, loam and straw outside the city walls, without steeples and church bells. The construction time was limited to one year."},
  "chusonji": {"article":"Chūson-ji","text":"Chūson-ji is a Buddhist temple in the town of Hiraizumi in southern Iwate Prefecture, Japan. It is the head temple of the Tendai sect in Tōhoku region of northern Honshu. The temple claims it was founded in 850 by Ennin, the third chief abbot of the sect. George Sansom states Chūson-jí was founded by Fujiwara no Kiyohira in 1095.","built":"1105"},
  "cibeles": {"article":"Plaza de Cibeles","text":"The Plaza de Cibeles is a square with a neo-classical complex of marble sculptures with fountains that has become a symbol for the city of Madrid. It sits at the intersection of Calle de Alcalá (running from east to west), Paseo de Recoletos (to the North) and Paseo del Prado (to the south). Plaza de Cibeles was originally named Plaza de Madrid, but in 1900, the City Council named it Plaza de Castelar, which was eventually replaced by its current name."},
  "cidade-velha": {"article":"Cidade Velha","text":"Cidade Velha (Portuguese for \"old city\", also: Santiago de Cabo Verde) is a city in the southern part of the island of Santiago, Cape Verde. Founded in 1462 by Portuguese traders, it is the oldest settlement in Cape Verde and its former capital. Once called Ribeira Grande by the Portuguese colonists, they changed its name to Cidade Velha in the late 18th century after relocating the capital to Praia.","built":"1462","elevation":1},
  "cinque-terre": {"article":"Cinque Terre","text":"The Cinque Terre is a coastal area within Liguria, in the northwest of Italy. It lies in the west of La Spezia Province, and comprises five villages: Monterosso al Mare, Vernazza, Corniglia, Manarola and Riomaggiore. The coastline, the five villages, and the surrounding hillsides are all part of the Cinque Terre National Park, a UNESCO World Heritage Site."},
  "citadelle": {"article":"Citadelle Laferrière","text":"The Citadelle Laferrière, commonly known as La Citadelle, is a large early-19th-century fortress located in Milot in Nord, Haiti. It is situated on the Bonnet à l'Evêque mountaintop located approximately 8 kilometres (5.0 mi) uphill from the town of Milot, 27 kilometres (17 mi) south of the city of Cap-Haïtien, and 15 kilometres (9.3 mi) southwest of the Three Bays Protected Area.","built":"1820","elevation":910},
  "ciudad-perdida": {"article":"Ciudad Perdida","text":"Ciudad Perdida is the archaeological site of an ancient city in the Sierra Nevada de Santa Marta of Colombia, within the jurisdiction of the municipality of Santa Marta. This city is believed to have been founded about 800 AD. If so, Ciudad Perdida predates Machu Picchu by about 650 years. It was built by the Tairona. Ciudad Perdida consists of a series of 169 terraces carved into the mountainside, a network of tiled roads, and several small circular plazas.","elevation":975},
  "cliffs-of-moher": {"article":"Cliffs of Moher","text":"The Cliffs of Moher are sea cliffs located at the southwestern edge of the Burren region in County Clare, Ireland. They run for about 14 kilometres (9 miles). At their southern end, they rise 120 metres (390 ft) above the Atlantic Ocean at Hag's Head, and, 8 kilometres (5 miles) to the north, they reach their maximum height of 214 metres (702 ft) just north of O'Brien's Tower, a round stone tower near the midpoint of the cliffs, built in 1835 by Sir Cornelius O'Brien, then continue at lower heights."},
  "cn-tower": {"article":"CN Tower","text":"The CN Tower is a 553.3-metre-high (1,815.3 ft) communications and observation tower in Toronto, Ontario, Canada. Completed in 1976, it is located in downtown Toronto, built on the former Railway Lands. Its name \"CN\" refers to Canadian National, the railway company that built the tower. Following the railway's decision to divest non-core freight railway assets prior to the company's privatization in 1995, it transferred the tower to the Canada Lands Company, a federal Crown corporation responsible for the government's real estate portfolio.","built":"1976","height":553,"architects":["John Andrews"]},
  "coimbra": {"article":"University of Coimbra","text":"The University of Coimbra (UC) is a public research university in Coimbra, Portugal. Officially chartered by King Denis on 1 March 1290, and recognised by Pope Nicholas IV on 9 August 1290, it is the oldest university in Portugal and one of the world's oldest in continuous operations, having begun operations in Lisbon before moving permanently to Coimbra in 1537.","built":"1290"},
  "cologne-cathedral": {"article":"Cologne Cathedral","text":"Cologne Cathedral is a Catholic cathedral in Cologne, North Rhine-Westphalia, Germany. It is the seat of the Archbishop of Cologne and of the administration of the Archdiocese of Cologne. It is a renowned monument of German Catholicism and Gothic architecture and was declared a World Heritage Site in 1996. It is Germany's most visited landmark, attracting an average of 6 million people a year.","built":"1248","height":157,"architects":["Andreas von Everdingen","Arnold Wolff","Barbara Schock-Werner"]},
  "colonia": {"article":"Colonia del Sacramento","text":"Colonia del Sacramento is a city in southwestern Uruguay, by the Río de la Plata, facing Buenos Aires, Argentina. It is one of the oldest towns in Uruguay and the capital of the Colonia Department. As of the 2023 census, it has a population of around 32,174. Its historic quarter is a UNESCO World Heritage Site. Modern Colonia del Sacramento produces textiles and has a free trade zone, in addition to a polytechnic centre and various government buildings.","built":"1680","elevation":27},
  "colosseum": {"article":"Colosseum","text":"The Colosseum is an elliptical amphitheatre in the centre of the city of Rome, Italy, just east of the Roman Forum. It is the largest ancient amphitheatre ever built, and is the largest standing amphitheatre in the world. Construction began under Emperor Vespasian (r. 69–79 AD) in 72 and was completed in AD 80 under his successor and heir, Titus (r. 79–81).","built":"AD 82","height":48},
  "colossi-of-memnon": {"article":"Colossi of Memnon","text":"The Colossi of Memnon are two large stone statues of the Pharaoh Amenhotep III, which stand at the front of the ruined Mortuary Temple of Amenhotep III, the largest temple in the Theban Necropolis. They have stood since 1350 BC, and were well known to ancient Greeks and Romans, as well as early modern travelers and Egyptologists.","height":18},
  "command-ridge": {"article":"Command Ridge","text":"Command Ridge is considered the highest point of Nauru, with an elevation of 65 metres (213 ft). Passing close to Command Ridge is the boundary between Aiwo and Buada districts.","elevation":71},
  "congonhas": {"article":"Sanctuary of Bom Jesus de Matosinhos","text":"The Sanctuary of Bom Jesus de Matosinhos is an 18th-century Roman Catholic basilica in Congonhas, Minas Gerais, Brazil. It was designed in the Baroque style with an Italian-inspired Rococo interior. The basilica is noted for its grand outdoor stairway with statues of Old Testament prophets. The interior has seven side chapels which illustrate the Stations of the Cross; each has a polychrome sculpture made by the artist Aleijadinho (b. 1730 or 1738 – 1814) and his assistants.","built":"1757"},
  "copan": {"article":"Copán","text":"Copán is an archaeological site of the Maya civilization in the Copán Department of western Honduras, not far from the border with Guatemala. It is one of the most important sites of the Maya civilization, which was not excavated until the 19th century. The ruined citadel and imposing public squares reveal the three main stages of development before the city was abandoned in the early 10th century."},
  "cordoba-mezquita": {"article":"Mosque–Cathedral of Córdoba","text":"The Mosque–Cathedral of Córdoba is the cathedral of the Roman Catholic Diocese of Córdoba in the Spanish region of Andalusia. Officially called the Cathedral of Our Lady of the Assumption, it is dedicated to the Assumption of Mary. Due to its status as a former mosque, it is also known as the Mezquita (Spanish for 'mosque') and, in a historical sense, as the Great Mosque of Córdoba.","built":"AD 786","height":54,"architects":["Hernán Ruiz","Juan de Ochoa","Ahmad Ben Baso"]},
  "cordouan": {"article":"Cordouan Lighthouse","text":"Cordouan lighthouse is an active lighthouse located 7 kilometres (4.3 miles) at sea, near the mouth of the Gironde estuary in France. At a height of 67.5 metres (221 ft), it is the tenth-tallest \"traditional lighthouse\" in the world. The Tour de Cordouan, the 'Patriarch of Lighthouses' is by far the oldest lighthouse in France, with construction starting in 1584 and finishing in 1611.","built":"1615","height":68},
  "corfu": {"article":"Old Fortress, Corfu","text":"The Old Fortress of Corfu is a Venetian fortress in the city of Corfu, Greece. The fortress covers the promontory which initially contained the old town of Corfu that had emerged during Byzantine times. Before the Venetian era the promontory, which lies between the Gulf of Kerkyra to the north and Garitsa Bay to the south, was defended by Byzantine fortifications which the Venetians largely replaced with fortifications of their own design.","built":"1545"},
  "cornwall-mines": {"article":"Botallack Mine","text":"The Botallack Mine is a former mine in Botallack in the west of Cornwall, UK. Since 2006 it has been part of the UNESCO World Heritage Site – Cornwall and West Devon Mining Landscape. The mine is within the Aire Point to Carrick Du Site of Special Scientific Interest (SSSI) and the South West Coast Path passes along the cliff."},
  "corvey": {"article":"Princely Abbey of Corvey","text":"The Princely Abbey of Corvey is a former Benedictine abbey and ecclesiastical principality now in North Rhine-Westphalia, Germany. It was one of the half-dozen self-ruling princely abbeys of the Holy Roman Empire from the Late Middle Ages until 1792 when Corvey was elevated to a prince-bishopric. Corvey, whose territory extended over a vast area, was in turn secularized in 1803 in the course of the German mediatisation and absorbed into the newly created Principality of Nassau-Orange-Fulda.","built":"9th century"},
  "crespi-dadda": {"article":"Crespi d'Adda","text":"Crespi d'Adda is a village in northern Italy and hamlet (frazione) of Capriate San Gervasio, a municipality in the province of Bergamo, Lombardy. It is a historic settlement and an outstanding example of the 19th and early 20th-century \"company towns\" built in Europe and North America by enlightened industrialists to meet the workers' needs.","built":"1877","elevation":180},
  "cristo-rei-dili": {"article":"Cristo Rei of Dili","text":"The Cristo Rei of Dili (Christ the King of Dili) statue is a 27.0-metre-high (88.6 ft) colossal statue of Jesus Christ situated atop a globe at Cape Fatucama in Dili, Timor-Leste. It is one of the country's main tourist attractions. The statue was designed, and its construction supervised, by Mochamad Syailillah. It was officially unveiled by President Suharto of Indonesia in 1996 as a gift from the Indonesian Government to the people of Timor Timur, the then Indonesian province.","built":"1996"},
  "cromford": {"article":"Cromford Mills","text":"Cromford Mills is the world's first cotton spinning mill powered by water, which was established in 1771 by Richard Arkwright at Cromford, Derbyshire, England. The mill structure is classified as a Grade I listed building. With a multi-use visitor centre having shops, galleries, restaurants and cafes, it is the centrepiece of the wider area known as Derwent Valley Mills, a UNESCO World Heritage Site stretching along the Upper Derwent Valley.","built":"1771"},
  "crystal-palace-retiro": {"article":"Palacio de Cristal del Retiro","text":"The Palacio de Cristal (\"Glass Palace\") is a 19th-century conservatory located in the Buen Retiro Park in Madrid, Spain. It is currently used for art exhibitions. The Palacio de Cristal, in the shape of a Greek cross, is made almost entirely of glass set in an iron framework on a brick base, which is decorated with ceramics.","built":"1887","architects":["Ricardo Velázquez Bosco"]},
  "cst-mumbai": {"article":"Chhatrapati Shivaji Terminus","text":"Chhatrapati Shivaji Terminus (CST), officially Chhatrapati Shivaji Maharaj Terminus (CSMT) and formerly known as Victoria Terminus (VT), is a historic railway terminus and UNESCO World Heritage Site in Mumbai (Bombay), Maharashtra, India. The terminus was designed by a British architectural engineer Frederick William Stevens from an initial design by Axel Haig, in an exuberant Indo Gothic style.","architects":["Frederick William Stevens","Axel Haig"]},
  "cuenca-hanging-houses": {"article":"Hanging Houses of Cuenca","text":"The Hanging Houses is a complex of houses located in Cuenca, Spain. In the past, houses of this kind were frequent along the eastern border of the ancient city, located near the ravine of the river Huécar. Today, however, there are only a few of them remaining. Of all of these structures, the most well-known is a group of three with wooden balconies."},
  "cusco": {"article":"Cusco Cathedral","text":"The Cathedral of Cusco or Cathedral Basilica of the Virgin of the Assumption is the main temple of the city of Cusco, in Peru and houses the headquarters of the Archdiocese of Cusco. The Cathedral Basilica of Cusco, together with the Triunfo temple make up the Cathedral Complex, it is located in the northeast sector of the current Plaza de Armas of Cusco.","built":"1559"},
  "cyrene": {"article":"Cyrene, Libya","text":"Cyrene, also sometimes anglicized as Kyrene, was an ancient Greek colony and Roman city near present-day Shahhat in northeastern Libya in North Africa. It was part of the Pentapolis, an important group of five cities in the region, and gave the area its classical and early modern name Cyrenaica. Cyrene lies on a ridge of the Jebel Akhdar uplands.","built":"630 BC"},
  "dakhla": {"article":"Dakhla Bay","text":"Dakhla Bay is a bay in the Atlantic Ocean formed by the peninsula where the city of Dakhla is located, in the part of Western Sahara administered de facto by Morocco."},
  "dambulla": {"article":"Dambulla cave temple","text":"Dambulla cave temple, also known as the Golden Temple of Dambulla, is a World Heritage Site (1991) in Sri Lanka, situated in the central part of the country. This site is situated 148 kilometres (92 mi) east of Colombo, 72 kilometres (45 mi) north of Kandy and 43 kilometres (27 mi) north of Matale. Dambulla is the largest and best-preserved cave temple complex in Sri Lanka."},
  "dancing-house": {"article":"Dancing House","text":"The Dancing House, or Ginger and Fred, is the nickname given to the Nationale-Nederlanden building on the Rašínovo nábřeží (Rašín Embankment) in Prague, Czech Republic. It was designed by the Croatian-Czech architect Vlado Milunić in cooperation with Canadian-American architect Frank Gehry on a vacant riverfront plot. The building was designed in 1992.","built":"1996","architects":["Vlado Milunić","Frank Gehry"]},
  "darjeeling-railway": {"article":"Darjeeling Himalayan Railway","text":"The Darjeeling Himalayan Railway, also known as the DHR, is a 610 mm (2 ft) gauge railway that runs between New Jalpaiguri and Darjeeling in the Indian state of West Bengal. Built between 1879 and 1881, it is about 88 km (55 mi) long. It climbs from about 100 m (330 ft) above sea level at New Jalpaiguri to about 2,200 m (7,200 ft) at Darjeeling, using six zig zags and three loops (originally five) to gain altitude.","built":"1881"},
  "darmstadt": {"article":"Darmstadt Artists' Colony","text":"The Darmstadt Artists' Colony refers to the Jugendstil artists' group and buildings near Rosenhöhe Park in Mathildenhöhe, Darmstadt, where these artists lived and worked in the late 19th and early 20th centuries. They were largely financed by patrons and worked with one another, taste permitting. UNESCO recognized the Mathildenhöhe artists' colony in Darmstadt as a World Heritage Site in 2021, because of its testimony to early modern architecture and landscape design, and its influence on the reform movements of the early 20th century.","built":"1899"},
  "darvaza": {"article":"Darvaza gas crater","text":"The Darvaza gas crater, also known as the Door to Hell or Gates of Hell, and known officially as the Shining of Karakum, is a burning natural gas field collapsed into a cavern near Darvaza, Turkmenistan. Hundreds of natural gas fires illuminate the floor and rim of the crater. The gas crater has been burning since 1971.","built":"1971","elevation":137},
  "dazu": {"article":"Dazu Rock Carvings","text":"The Dazu Rock Carvings are a series of Chinese religious sculptures and carvings and UNESCO World Heritage Site located in Dazu District, Chongqing, China. The carvings date back as far as the 7th century AD, depicting and influenced by Buddhist, Confucian and Taoist beliefs. Some are in rock-cut cave shrines, in the usual Chinese Buddhist style, but many others are rock reliefs carved into the open rock faces."},
  "deadvlei": {"article":"Deadvlei","text":"Deadvlei is a white clay pan located near the more famous salt pan of Sossusvlei, in a valley between the dunes in the Namib-Naukluft Park in Namibia. Also written DeadVlei or Dead Vlei, its name means \"dead marsh\" (from English dead, and Afrikaans vlei, meaning lake or marsh). Its Afrikaans name is Dooie Vlei. Many Internet references erroneously translate its name as \"dead valley\"; a vlei is not a valley (which in Afrikaans is \"vallei\")."},
  "delos": {"article":"Delos","text":"Delos or Dilos, is a small Greek island near Mykonos, close to the centre of the Cyclades archipelago. Though only 3.43 km2 (1.32 sq mi) in area, it is one of the most important mythological, historical, and archaeological sites in Greece. The ongoing excavations in the island are among the most extensive in the Mediterranean, and many of the artefacts found are displayed at the Archaeological Museum of Delos and the National Archaeological Museum of Athens.","elevation":112},
  "delphi": {"article":"Delphi","text":"Delphi, in legend previously called Pytho, was an ancient sacred precinct in central Greece. It was the seat of Pythia, the high priestess role which was consulted as a major oracle for important decisions throughout the ancient classical world. The ancient Greeks considered the centre of the world to be in Delphi, marked by the stone monument known as the Omphalos of Delphi.","elevation":570},
  "derbent": {"article":"Naryn-Kala","text":"Naryn-Kala is an ancient pre-Arab citadel, part of the Derbent fortress, connected to the Caspian Sea by double walls designed to block the so-called Caspian gates to the Persian state. It is included in the UNESCO World Heritage List.","built":"6th century"},
  "deyr-e-gachin": {"article":"The Persian Caravanserai","text":"The Persian Caravanserai is a UNESCO World Heritage Site composed of 54 different caravanserais. It was inscribed in 2023. Caravanserais were roadside inns, which would provide shelter to travelers."},
  "dholavira": {"article":"Dholavira","text":"Dholavira is an archaeological site at Khadirbet in Bhachau Taluka of Kutch District, in the state of Gujarat, western India, which is named after a modern-day village 1 kilometre (0.62 mi) south of it. This village is 165 km (103 mi) from Radhanpur. Also known locally as Kotada timba, the site contains ruins of a city of the ancient Indus Valley Civilization."},
  "diocletians-palace": {"article":"Diocletian's Palace","text":"Diocletian's Palace is an ancient Roman palace and fortress complex in Split, Croatia. It was built at the end of the third century AD by the Roman Emperor Diocletian as his retirement residence. About half of the complex was for Diocletian's personal use, with the rest housing the military garrison. The complex was built on a peninsula six kilometres (3.7 mi) southwest from Salona, the former capital of Dalmatia, one of the largest cities of the late empire with 60,000 people and the birthplace of Diocletian.","built":"AD 293"},
  "diriyah": {"article":"At-Turaif District","text":"At-Turaif is a historic district located in Diriyah, north-west of Riyadh. It is regarded as one of the more important political and historical sites in Saudi Arabia, as it represented the capital of the early Saudi kingdom. It was the original home of the House of Saud and was the country's first capital from 1727 until Ottoman conquest of the area in 1818."},
  "divrigi": {"article":"Divriği Great Mosque and Hospital","text":"Divriği Great Mosque and Hospital was built in 1228–1229 by the local dynasty of the Mengujekids in the small Anatolian town of Divriği, now in Sivas Province, Turkey. The complex is in the upper town, below the citadel. The exquisite stone carvings and eclectic architecture of the complex place it among the most important works of architecture in Anatolia and led to its inclusion on UNESCO's World Heritage List in 1985.","built":"1229"},
  "dja": {"article":"Dja Faunal Reserve","text":"Dja Faunal Reserve, located in southeastern Cameroon, is a UNESCO World Heritage Site inscribed in 1987. Causes of inscription include diversity of species present in the park, the presence of five threatened species of mammal, and lack of disturbance within the park. It is managed by Dja Conservation Services (DCS), which is led by a conservator.","built":"1987"},
  "djemila": {"article":"Djémila","text":"Djémila, formerly Cuicul, is a small mountain village in Algeria, near the northern coast east of Algiers, where some of the best preserved Roman ruins in North Africa are found. It is in the region bordering the Constantinois and Petite Kabylie (Basse Kabylie). In 1982 Djémila became a UNESCO World Heritage Site for its unique adaptation of Roman architecture to a mountain environment."},
  "djenne": {"article":"Great Mosque of Djenné","text":"The Great Mosque of Djenné in the Sudano-Sahelian architectural style is the largest adobe brick building in the world. The mosque is located in the city of Djenné, Mali, on the flood plain of the Bani River. The first mosque on the site was built around the 13th century, but the current structure dates from 1907. As well as being the centre of the community of Djenné, it is one of the most famous landmarks in Africa.","built":"1906","height":16},
  "dolomites": {"article":"Tre Cime di Lavaredo","text":"The Tre Cime di Lavaredo, also called the Drei Zinnen (German for 'Three Merlons'), are three distinctive battlement-like peaks, in the Sexten Dolomites of northeastern Italy. They are one of the best-known mountain groups in the Alps. The three peaks, from east to west, are: Cima Piccola / Kleine Zinne (\"little peak\")","elevation":2999},
  "dome-of-the-rock": {"article":"Dome of the Rock","text":"The Dome of the Rock is an octagonal Islamic shrine at the center of the Al-Aqsa mosque compound on the Temple Mount in the Old City of Jerusalem. It is the world's oldest surviving work of Islamic architecture, the earliest archaeologically-attested religious structure to be built by a Muslim ruler and contains the earliest inscriptions proclaiming Islam and the prophet Muhammad.","built":"AD 691"},
  "dougga": {"article":"Dougga","text":"Dougga or Thugga or TBGG was a Berber, Punic and Roman settlement near present-day Téboursouk in northern Tunisia. The current archaeological site covers 75 hectares (190 acres). UNESCO qualified Dougga as a World Heritage Site in 1997, believing that it represents \"the best-preserved Roman small town in North Africa\"."},
  "drakensberg": {"article":"Maloti-Drakensberg Park","text":"The Maloti-Drakensberg Park is a World Heritage Site, established on 11 June 2001 by linking the Sehlabathebe National Park in the Kingdom of Lesotho and the uKhahlamba Drakensberg Park in KwaZulu-Natal, South Africa. The highest peak is Thaba Ntlenyana rising to 3,482 metres. Proposed extensions to the main park include the Golden Gate Highlands National Park, Sterkfontein Dam Nature Reserve (Free State) and Royal Natal National Park (KwaZulu-Natal) in South Africa; and the Bokong Nature Reserve and Ts'ehlanyane National Park in Lesotho.","built":"2013"},
  "drottningholm": {"article":"Drottningholm Palace","text":"Drottningholm Palace is a royal palace in Drottningholm, on the island of Lovön in Ekerö Municipality, Stockholm County, Sweden. Built beginning in 1662, it served as a regular summer residence of the Swedish royal court during much of the 18th century and is today the residence of the Swedish royal family. The palace is part of the Royal Domain of Drottningholm, which was inscribed on the UNESCO World Heritage List in 1991 under criterion (iv).","built":"1699","architects":["Nicodemus Tessin the Elder","Nicodemus Tessin the Younger"]},
  "dubrovnik": {"article":"Dubrovnik","text":"Dubrovnik, historically also known as Ragusa, is a city in southern Dalmatia, Croatia, by the Adriatic Sea. It is one of the most prominent tourist destinations in the Mediterranean, a seaport and the centre of the Dubrovnik-Neretva County. In 2021, its total population was 41,562. Recognizing its outstanding medieval architecture and fortifications, UNESCO inscribed the Old City of Dubrovnik as a World Heritage Site in 1979.","built":"7th century","elevation":10},
  "durham": {"article":"Durham Cathedral","text":"Durham Cathedral, formally the Cathedral Church of Christ, Blessed Mary the Virgin and St Cuthbert of Durham, is a Church of England cathedral in the city of Durham, England. The cathedral is the seat of the Bishop of Durham and is the mother church of the diocese of Durham. It also contains the shrines of the Anglo-Saxon saints Cuthbert and Bede.","built":"1093","height":22},
  "east-rennell": {"article":"East Rennell","text":"East Rennell is the southern portion of Rennell Island in the Solomon Islands which is designated a UNESCO World Heritage Site. Rennell is the largest raised coral atoll in the world and the area in East Rennell surrounding Lake Tegano contains many endemic species. In 2013, the World Heritage Committee added East Rennell to the List of World Heritage in Danger because of the threat of logging activities to the site's outstanding universal value."},
  "echmiatsin": {"article":"Etchmiadzin Cathedral","text":"Echmiatsin Cathedral is the mother church of the Armenian Apostolic Church, located in the city dually known as Echmiatsin (Ejmiatsin) and Vagharshapat, Armenia. Constructed at the turn of the fourth century, it is usually considered the first cathedral built in ancient Armenia, and often regarded as the oldest cathedral in the world.","built":"AD 303","height":27},
  "edinburgh-castle": {"article":"Edinburgh Castle","text":"Edinburgh Castle is a historic castle in Edinburgh, Scotland. It stands on Castle Rock, which has been occupied by humans since at least the Iron Age. There has been a royal castle on the rock since the reign of Malcolm III in the 11th century, and the castle continued to be a royal residence until 1633. From the 15th century, the castle's residential role declined, and by the 17th century it was principally used as a military garrison.","built":"12th century"},
  "eggenberg": {"article":"Eggenberg Palace, Graz","text":"Eggenberg Palace in Graz, is the most significant Baroque palace complex in the Austrian state of Styria. With its preserved accouterments, the extensive scenic gardens, as well as some special collections from the Universalmuseum Joanneum housed in the palace and surrounding park, Schloss Eggenberg ranks among the most valuable cultural treasures of Austria.","built":"1635","architects":["Giovanni Pietro de Pomis"]},
  "eiffel-tower": {"article":"Eiffel Tower","text":"The Eiffel Tower is a lattice tower on the Champ de Mars in Paris, France. It is named after the engineer Gustave Eiffel, whose company designed and built the tower from 1887 to 1889. Locally nicknamed \"La dame de fer\" (French for \"Iron Lady\") for its use of wrought iron, it was constructed as the centrepiece of the 1889 World's Fair, and to crown the centennial anniversary of the French Revolution.","built":"1887","height":330,"architects":["Stéphen Sauvestre"]},
  "eisinga": {"article":"Eise Eisinga Planetarium","text":"The Royal Eise Eisinga Planetarium is an 18th-century orrery in Franeker, Friesland, Netherlands. It is currently a museum and open to the public. The orrery has been on the top 100 Dutch heritage sites list since 1990. In September 2023, it received the status of UNESCO World Heritage Site. It is the oldest working orrery in the world.","built":"1781"},
  "el-escorial": {"article":"El Escorial","text":"The Royal Site of San Lorenzo de El Escorial, also called Monasterio de El Escorial or simply El Escorial, is a historical residence of the king of Spain located in the town of San Lorenzo de El Escorial, 2.06 kilometres (1.28 mi) up the valley (4.1 km [2.5 mi] road distance) from the town of El Escorial and about 45 kilometres (28 mi) northwest of the Spanish capital Madrid.","built":"1563"},
  "el-jem": {"article":"Amphitheatre of El Jem","text":"The Amphitheatre of El Jem is an oval amphitheatre in the modern-day city of El Djem, Tunisia, formerly Thysdrus in the Roman province of Africa. It has been listed by UNESCO since 1979 as a World Heritage Site.","built":"AD 238"},
  "el-morro": {"article":"Castillo San Felipe del Morro","text":"Castillo San Felipe del Morro, most commonly known as El Morro (The Promontory), is a large fortress and citadel in the Old San Juan historic quarter of San Juan, the capital city and municipality of Puerto Rico. Commissioned by King Charles I of Spain in 1539, it was first built as a fortified tower in honor of King Philip II, who oversaw its expansion into a hornwork bastion fort by 1595.","built":"1539"},
  "el-tajin": {"article":"El Tajín","text":"El Tajín is a pre-Columbian archeological site in the Mexican state of Veracruz and is one of the largest and most important cities of the Classic era of Mesoamerica. A part of the Classic Veracruz culture, El Tajín flourished from 600 to 1200 AD and during this time numerous temples, palaces, ballcourts, and pyramids were built."},
  "elephanta": {"article":"Elephanta Caves","text":"The Elephanta Caves form a collection of cave temples predominantly dedicated to the Hindu god Shiva; UNESCO has designated them as a World Heritage Site. They are located on Elephanta Island, or Gharapuri (literally meaning \"the city of the caves\"), in Mumbai Harbour, 10 kilometres (6.2 mi) east of Mumbai in the Indian state of Maharashtra."},
  "ellora": {"article":"Kailasa Temple, Ellora","text":"The Kailasha or Kailasha-natha temple is the largest of the rock-cut Hindu temples at the Ellora Caves in Chhatrapati Sambhaji Nagar district of Maharashtra, India. A megalith carved into a cliff face, it is considered one of the most remarkable cave temples in the world because of its size, architecture, and sculptural treatment.","built":"AD 773"},
  "elvas": {"article":"Elvas","text":"Elvas, officially the City of Elvas, is a Portuguese municipality, former episcopal city and frontier fortress of easternmost central Portugal, located in the district of Portalegre in Alentejo. It is situated about 200 kilometres (120 mi) east of Lisbon, and about 8 kilometres (5.0 mi) west of the Spanish fortress of Badajoz, by the Madrid-Badajoz-Lisbon railway."},
  "endless-column": {"article":"Sculptural Ensemble of Constantin Brâncuși at Târgu Jiu","text":"The Sculptural Ensemble of Constantin Brâncuși at Târgu Jiu is an homage to the Romanian heroes of the First World War. The ensemble comprises three sculptures: The Table of Silence (Masa tăcerii), The Gate of the Kiss (Poarta sărutului), and the Endless Column (Coloana fără Sfârșit) on an axis 1.3 km (3⁄4 mile) long, oriented west to east.","built":"1938"},
  "engelsberg": {"article":"Engelsberg Ironworks","text":"Engelsberg Ironworks is an ironworks in Ängelsberg, a village in Fagersta Municipality in Västmanland County, Sweden. It was built in 1681 by Per Larsson Gyllenhöök (1645–1706) and developed into one of the world's most modern ironworks in the period 1700–1800. It is listed as a UNESCO World Heritage Site since 1993.","built":"1681"},
  "ennedi": {"article":"Ennedi Plateau","text":"The Ennedi Plateau is located in the northeast of Chad, in the regions of Ennedi-Ouest and Ennedi-Est. It is considered a part of the group of mountains known as the Ennedi Massif found in Chad, which is one of the nine countries that make up the Sahelian belt that spans the Atlantic Ocean to Sudan. The Ennedi is a sandstone bulwark in the middle of the Sahara, which was formed by erosion from wind and temperature."},
  "ephesus": {"article":"Library of Celsus","text":"The Library of Celsus is an ancient Roman building in Ephesus, Anatolia, located near the modern town of Selçuk, in the İzmir Province of western Turkey. The building was commissioned in the years 110s CE by a consul of the Roman Empire, Tiberius Julius Aquila Polemaeanus, as a funerary monument for his father Tiberius Julius Celsus Polemaeanus, former proconsul of Asia, and completed during the reign of the Roman Emperor Hadrian, sometime after Aquila's death."},
  "epidaurus": {"article":"Ancient Theatre of Epidaurus","text":"The Ancient Theatre of Epidaurus is a theatre in the Greek city of Epidaurus, located on the southeast end of the sanctuary dedicated to the ancient Greek God of medicine, Asclepius. It is built on the west side of Cynortion Mountain, near modern Lygourio, and belongs to the Epidaurus Municipality. Constructed in the late 4th century BC, it is considered to be the most perfect ancient Greek theatre with regard to acoustics and aesthetics.","built":"4th century","elevation":455,"architects":["Polykleitos the Younger"]},
  "eram-garden": {"article":"Eram Garden","text":"Eram Garden is a historic Persian garden in Shiraz, Iran. The garden, and the building within it, are located at the northern shore of the Khoshk River in the Fars province.","built":"1824"},
  "erbil-citadel": {"article":"Citadel of Erbil","text":"The Citadel of Erbil, locally called Qellat, is a tell or occupied mound, and the historical city centre of Erbil in the Kurdistan Region of Iraq. The citadel was added to the World Heritage List on 21 June 2014. The earliest evidence for occupation of the citadel mound dates to the 5th millennium BC, and possibly earlier."},
  "eremitage": {"article":"Hermitage Hunting Lodge","text":"The Hermitage Hunting Lodge is located in Dyrehaven north of Copenhagen, Denmark. The hunting lodge was built by architect Lauritz de Thurah in Baroque style from 1734 to 1736 for Christian VI of Denmark-Norway in order to host royal banquets during royal hunts in Dyrehaven.","built":"1736","architects":["Lauritz de Thurah"]},
  "essaouira": {"article":"Medina of Essaouira","text":"The Medina of Essaouira, formerly Mogador, is a Medina quarter in Essaouira, Morocco. It was designated by the UNESCO as a World Heritage Site in 2001."},
  "etosha": {"article":"Etosha National Park","text":"Etosha National Park is a national park in northwestern Namibia and one of the largest national parks in Africa. It was proclaimed a game reserve in March 1907 in Ordinance 88 by the Governor of German South West Africa, Friedrich von Lindequist. It was designated as Wildschutzgebiet in 1958, and was awarded the status of national park in 1967, by an act of parliament of the Republic of South Africa.","built":"1907"},
  "euphrasian": {"article":"Euphrasian Basilica","text":"The Euphrasian Basilica or the Cathedral Basilica of the Assumption of Mary is a Roman Catholic basilica in the Istrian town of Poreč, Croatia. The episcopal complex, which comprises the basilica itself, a sacristy, a baptistery and the bell tower of the nearby archbishop's palace, is an excellent example of early Byzantine architecture in the Mediterranean region.","built":"AD 553"},
  "everest": {"article":"Mount Everest","text":"Mount Everest (known in Nepali as Sagarmāthā, in Sherpa as Chamolangma, and in Tibetan as Jomolangma/Čhomolangma) is the highest mountain on Earth above sea level. It lies in the Mahalangur Himal sub-range of the Himalayas and marks part of the China–Nepal border at its summit. Its height was most recently measured in 2020 through a joint survey by Nepalese and Chinese authorities as 8,848.86 m (29,031 ft 8+1⁄2 in).","elevation":8849},
  "everglades": {"article":"Everglades","text":"The Everglades is a natural region of flooded grasslands in the southern portion of the U.S. state of Florida, comprising the southern half of the Kissimmee-Okeechobee-Everglades watershed. The Everglades is in the Neotropical realm. The system begins near Orlando with the Kissimmee River, which discharges into the vast but shallow Lake Okeechobee."},
  "evora": {"article":"Roman Temple of Évora","text":"The Roman Temple of Évora, also referred to as the Templo de Diana (albeit wrongly, after Diana, the ancient Roman goddess of the moon, the hunt, and chastity) is an ancient temple in the Portuguese city of Évora (civil parish of Sé e São Pedro). The temple is part of the historical centre of the city, which was included in the classification by UNESCO as a World Heritage Site."},
  "fagus-factory": {"article":"Fagus Factory","text":"The Fagus Factory is a shoe last factory in Alfeld on the Leine, Lower Saxony, Germany, and serves as an important example of early modern architecture. Commissioned by owner Carl Benscheidt who wanted a radical structure to express the company's break from the past, the factory was designed by Walter Gropius and Adolf Meyer.","built":"1911","architects":["Walter Gropius","Adolf Meyer"]},
  "fallingwater": {"article":"Fallingwater","text":"Fallingwater is a house museum in Stewart Township in the Laurel Highlands of southwestern Pennsylvania, United States. Designed by the architect Frank Lloyd Wright, it is built partly over a waterfall on the Bear Run stream. The three-story residence was developed as a weekend retreat for Edgar J. Kaufmann Sr., the owner of Kaufmann's Department Store in Pittsburgh, and his wife Liliane.","built":"1936","architects":["Frank Lloyd Wright"]},
  "falun": {"article":"Falun Mine","text":"Falun Mine was a mine in Falun, Sweden, that operated for a millennium from the 10th century to 1992. It produced as much as two-thirds of Europe's copper needs and helped fund many of Sweden's wars in the 17th century. Technological developments at the mine had a profound influence on mining globally for two centuries.","built":"10th century"},
  "fatehpur-sikri": {"article":"Fatehpur Sikri","text":"Fatehpur Sikri is a town in the Agra District of Uttar Pradesh, India. Situated 35.7 kilometres (22.2 mi) from the district headquarters of Agra, Fatehpur Sikri itself was founded as the capital of the Mughal Empire in 1571 by Emperor Akbar, serving this role from 1571 to 1585, when Akbar abandoned it due to a campaign in Punjab and was later completely abandoned in 1610.","built":"1569","elevation":213},
  "ferapontov": {"article":"Ferapontov Monastery","text":"The Ferapontov Monastery is a monastery of the Russian Orthodox Church in Ferapontovo, Kirillovsky District, Vologda Oblast, Russia. The monastery was founded by Saint Ferapont in 1398. In 2000, the monastery was added to the UNESCO list of World Heritage Sites.","built":"1398"},
  "ferrara": {"article":"Castello Estense","text":"The Castello Estense ('Este castle') or castello di San Michele ('St. Michael's castle') is a moated medieval castle in the center of Ferrara, northern Italy. It consists of a large block with four corner towers.","built":"14th century","architects":["Bartolino da Novara"]},
  "fez-tanneries": {"article":"Chouara Tannery","text":"Chouara Tannery (sometimes spelled Chouwara) is one of the three tanneries in the city of Fez, Morocco. It is the largest tannery in the city and one of the oldest. It is located in Fes el Bali, the oldest medina quarter of the city, near the Saffarin Madrasa along the Oued Fes (also known as the Oued Bou Khrareb). Since the inception of the city, the tanning industry has been continually operating in the same fashion as it did in the early centuries."},
  "fiat-tagliero": {"article":"Fiat Tagliero Building","text":"The Fiat Tagliero Building is a Futurist-style filling station in Asmara, Eritrea. It was completed in 1938 and designed by the Italian engineer Giuseppe Pettazzi.","built":"1938","architects":["Guido Ferrazza"]},
  "finlandia-hall": {"article":"Finlandia Hall","text":"The Finlandia Hall is a congress and event venue in the centre of Helsinki on the Töölönlahti Bay, owned by the City of Helsinki. The building, which was designed by architect Alvar Aalto, was completed in 1971. Every detail in the building is designed by Aalto. The designs were completed in 1962, with building taking place between 1967 and 1971.","built":"1971","architects":["Alvar Aalto"]},
  "fishermans-bastion": {"article":"Fisherman's Bastion","text":"The Halászbástya or Fisherman's Bastion is one of the best known historical monuments in Budapest, located near the Buda Castle, in the Várkerület (Buda Castle District). Since 1987, it has been designated a UNESCO World Heritage Site as part of the Várkerület District (Buda Castle District). It offers a unique panorama of Budapest from its Neo-Romanesque lookout terraces.","architects":["Frigyes Schulek"]},
  "florence-duomo": {"article":"Florence Cathedral","text":"Florence Cathedral, formally the Cathedral of Saint Mary of the Flower, is the cathedral of the Catholic Archdiocese of Florence in Florence, Italy. Commenced in 1296 in the Gothic style to a design of Arnolfo di Cambio and completed by 1436 with a dome engineered by Filippo Brunelleschi, the basilica's exterior is faced with polychrome marble panels in various shades of green and pink, alternated by white, and features an elaborate 19th-century Gothic Revival western façade by Emilio De Fabris.","built":"1296","height":115,"architects":["Arnolfo di Cambio","Filippo Brunelleschi","Andrea Pisano"]},
  "fontainebleau": {"article":"Palace of Fontainebleau","text":"Palace of Fontainebleau, located 55 kilometers (34 miles) southeast of the center of Paris, in the commune of Fontainebleau, is one of the largest French royal châteaux. It served as a hunting lodge and autumn residence for many of the French monarchs, including Louis VII, Francis I, Henry II, Louis-Philippe, Napoleon I, and Napoleon III."},
  "fontenay": {"article":"Abbey of Fontenay","text":"The Abbey of Fontenay is a former Cistercian abbey located in the commune of Marmagne, near Montbard, in the département of Côte-d'Or in France. It was founded by Saint Bernard of Clairvaux in 1118, and built in the Romanesque style. It is one of the oldest and most complete Cistercian abbeys in Europe, and became a UNESCO World Heritage Site in 1981.","built":"1118"},
  "forbidden-city": {"article":"Forbidden City","text":"The Forbidden City is the imperial palace complex in the center of the Imperial City in Beijing, China. It was the residence of twenty-four Ming and Qing dynasty Emperors and was the center of political power in China from 1420 to 1924. The palace is now administered by the Palace Museum and has been a UNESCO World Heritage Site since 1987.","built":"1420","architects":["Kuai Xiang"]},
  "fort-george": {"article":"Fort George, Grenada","text":"Fort George is a former military fortification in Grenada. The fort overlooks the harbour of the capital St. George's and was built by the French between 1706 and 1710, as Fort Royal. The island passed into British hands in 1763 and the fort was renamed Fort George after the reigning monarch George III. The fort surrendered to a French force during the Anglo-French War (1778–1783) but passed back to Britain after the end of that war."},
  "fort-jesus": {"article":"Fort Jesus","text":"Fort Jesus, is a fort located on Mombasa Island. Designed by the Italian architect Giovanni Battista Cairati, it was built between 1593 and 1596 by order of King Felipe II of Spain, who also reigned as King Filipe I of Portugal and the Algarves, to guard the Old Port of Mombasa. Fort Jesus was the only fort maintained by the Portuguese on the Swahili coast and is recognised as a testament to the first successful attempt by a Western power to establish influence over the Indian Ocean trade.","built":"1593","architects":["Giovanni Battista Cairati"]},
  "fort-louis": {"article":"Fort Louis (Saint Martin)","text":"Fort Louis (or Fort St. Louis) is a historic French military fort on the Caribbean island of Saint Martin. It is located in Marigot, the capital of the French side of the island, overlooking Marigot Bay. The fort was built in the 18th century to defend Marigot's harbor and its warehouses. It was built during the reign of King Louis XVI.","built":"1789"},
  "forth-bridge": {"article":"Forth Bridge","text":"The Forth Bridge is a cantilever railway bridge across the Firth of Forth in the east of Scotland, 9 miles (14 kilometres) west of central Edinburgh. Completed in 1890, it is considered a symbol of Scotland (having been voted Scotland's greatest man-made wonder in 2016), and is a UNESCO World Heritage Site. It was designed by English engineers Sir John Fowler and Sir Benjamin Baker.","built":"1890","height":110},
  "fountains-abbey": {"article":"Fountains Abbey","text":"Fountains Abbey is a ruined Cistercian monastery near Ripon in North Yorkshire, England. It was founded in 1132 under the direction of Thurstan, archbishop of York, and over the next four centuries became one of the wealthiest monasteries in England thanks to its large and diverse landholdings. The monastery was dissolved in 1539 as part of the English Reformation and its estates sold.","built":"12th century"},
  "fourviere": {"article":"Basilica of Notre-Dame de Fourvière","text":"The Basilica of Notre-Dame de Fourvière is a minor basilica in Lyon, France. It was built with private funds between 1872 and 1896 in a dominant position overlooking the city. The site it occupies was once the Roman forum of Trajan, the forum vetus (old forum), thus its name (as an inverted corruption of the French Vieux-Forum).","built":"1872","architects":["Pierre Bossan","Louis Sainte-Marie-Perrin"]},
  "fouta-djallon": {"article":"Fouta Djallon","text":"Fouta Djallon is a highland region in the center of Guinea, roughly corresponding with Middle Guinea, in West Africa.","elevation":1515},
  "fujian-tulou": {"article":"Fujian tulou","text":"The Fujian tulou are Chinese rural dwellings unique to the Hakka in the mountainous areas in southeastern Fujian, China. They were mostly built between the 12th and the 20th centuries. A tulou is usually a large, enclosed and fortified earth building, most commonly rectangular or circular in configuration, with very thick load-bearing rammed earth walls between three and five stories high and housing up to 800 people."},
  "funafuti": {"article":"Funafuti Conservation Area","text":"The Funafuti Conservation Area is a marine conservation area covering 33 square kilometers (12.74 square miles) of reef, lagoon and motu (islets) on the western side of Funafuti atoll in Tuvalu. The marine environment of the conservation area includes reef, lagoon, channel and ocean; and are home to many species of fish, corals, algae and invertebrates.","built":"1999"},
  "fushimi-inari": {"article":"Fushimi Inari-taisha","text":"Fushimi Inari-taisha is the head shrine of the kami Inari, located in Fushimi-ku, Kyoto, Japan. The shrine sits at the base of a mountain, also named Inari, which is 233 metres (764 ft) above sea level, and includes trails up the mountain to many smaller shrines which span 4 kilometres (2.5 mi) and take approximately 2 hours to walk up.","built":"AD 711"},
  "galapagos": {"article":"Galápagos Islands","text":"The Galápagos Islands are an archipelago of volcanic islands in the Eastern Pacific, located around the equator, 485 nautical miles west of the mainland of South America. They form the Galápagos Province of the Republic of Ecuador, with a population of slightly over 33,450 in 2020. The province is divided into the cantons of San Cristóbal, Santa Cruz, and Isabela, the three most populated islands in the chain."},
  "galata-tower": {"article":"Galata Tower","text":"Galata Tower, or Galata Tower Museum, its name since it began to be used as a museum, is a tower located in the Beyoğlu district of Istanbul. It takes its name from the Galata neighborhood where it stands. Built as a watchtower within the Walls of Galata, the tower has served various purposes over different periods and has functioned as an exhibition venue and museum since 2020.","built":"1349","height":63},
  "galle-fort": {"article":"Galle Fort","text":"Galle Fort, in the Bay of Galle on the southwest coast of Sri Lanka, was built first in 1588 by the Portuguese, then extensively fortified by the Dutch during the 17th century from 1649 onwards. It is a historical, archaeological and architectural heritage monument, which even after more than 437 years maintains a polished appearance, due to extensive reconstruction work done by the Archaeological Department of Sri Lanka.","built":"1584"},
  "gammelstad": {"article":"Gammelstad Church Town","text":"Gammelstad Church Town is a UNESCO World Heritage Site situated in Gammelstaden 10 km north of Luleå, Sweden, at the northern end of the Gulf of Bothnia. It is the best preserved example of a type of settlement called kyrkstad (\"church town\") that was once widespread throughout northern Scandinavia. As Church Village of Gammelstad, Luleå, it was listed as a World Heritage Site in 1996."},
  "gamzigrad": {"article":"Gamzigrad","text":"Gamzigrad is an archaeological site, spa resort, and UNESCO World Heritage Site of Serbia, located south of the Danube river, in the city of Zaječar. It is the location of the ancient Roman complex of palaces and temples Felix Romuliana, built by Emperor Galerius in Dacia Ripensis. The main area covers 10 acres (40,000 m2)."},
  "gateway-of-india": {"article":"Gateway of India","text":"The Gateway of India is an arch-monument, completed in 1924, on the waterfront of Mumbai, Maharashtra, India. It was erected to commemorate the landing of King George V of the United Kingdom for his coronation as the Emperor of India in December 1911 at Strand Road near Wellington Fountain. He was the first British monarch to visit India.","built":"1924","height":26,"architects":["George Wittet"]},
  "gebel-barkal": {"article":"Jebel Barkal","text":"Jebel Barkal or Gebel Barkal is a mesa located 400 km north of Khartoum, next to Karima in Northern State in Sudan, and near the Nile River in Nubia. The Jebel is 104 meters tall, has a flat top, and came to have religious significance for both ancient Kush and ancient Egyptian occupiers. In 2003, the mountain, together with the extensive archaeological site at its base, were named as a World Heritage Site by UNESCO.","elevation":287},
  "geghard": {"article":"Geghard","text":"Geghard is a medieval monastery in the Kotayk province of Armenia, which is partially carved out of the adjacent mountain, surrounded by cliffs. It is listed as a UNESCO World Heritage Site with enhanced protection status. While the main chapel was built in 1215, the monastery complex was founded in the 4th century by Gregory the Illuminator at the site of a sacred spring inside a cave.","built":"1215"},
  "geirangerfjord": {"article":"Geirangerfjord","text":"Geirangerfjorden (Norwegian) or Geiranger Fjord (English) is a fjord in the Sunnmøre region of Møre og Romsdal county, Norway. It is located entirely in Stranda Municipality. It is a 15-kilometre-long (9+1⁄2 mi) branch off the Sunnylvsfjorden, which itself is a branch off the Storfjorden. The small village of Geiranger is located at the end of the fjord where the Geirangelva river empties into it."},
  "gelati": {"article":"Gelati Monastery","text":"Gelati is a medieval monastic complex near Kutaisi in the Imereti region of western Georgia. One of the first monasteries in Georgia, it was founded in 1106 by King David IV of Georgia as a monastic and educational center. The monastery is a UNESCO World Heritage Site and was a cultural, educational and scientific center in medieval Georgia.","built":"1106"},
  "ggantija": {"article":"Ġgantija","text":"Ġgantija is a megalithic temple complex from the Neolithic era (c. 3600–2500 BC), on the Mediterranean island of Gozo in Malta. The Ġgantija temples are the earliest of the Megalithic Temples of Malta and are older than the pyramids of Egypt. Their makers erected the two Ġgantija temples during the Neolithic, which makes these temples more than 5,500 years old and the world's second-oldest existing manmade religious structures after Göbekli Tepe in present-day Turkey.","built":"3600 BC"},
  "ghadames": {"article":"Ghadames","text":"Ghadames or Ghadamis is an oasis town in the Nalut District of the Tripolitania region in northwestern Libya. Ghadames, known as 'the pearl of the desert', stands in an oasis. It is one of the oldest pre-Saharan cities and an example of a traditional settlement. Its domestic architecture is characterized by a vertical division of functions: the ground floor used to store supplies; the first floor is for the family, overhanging covered alleys that create what is almost an underground network of passageways; and, at the top, open-air terraces reserved for the women.","elevation":357},
  "giants-causeway": {"article":"Giant's Causeway","text":"The Giant's Causeway is an area of approximately 40,000 interlocking basalt columns, the result of an ancient volcanic fissure eruption, part of the North Atlantic Igneous Province active in the region during the Paleogene period. It is located in County Antrim on the north coast of Northern Ireland, about three miles (five kilometres) northeast of Bushmills."},
  "gobekli-tepe": {"article":"Göbekli Tepe","text":"Göbekli Tepe is a Neolithic archaeological site in Upper Mesopotamia (al-Jazira) in modern-day Turkey. The settlement was inhabited from around 9500 BCE to at least 8000 BCE, during the Pre-Pottery Neolithic. It is known for its large circular structures that contain large stone pillars – among the world's oldest known megaliths.","built":"10th millennium BC","elevation":760},
  "gobustan": {"article":"Gobustan Rock Art Cultural Landscape","text":"The Gobustan Rock Art Cultural Landscape is a historic site in Azerbaijan, comprising a large collection of petroglyphs that reflect the flora, fauna, hunting practices, social structures, and cultural expressions of human societies from prehistoric to medieval times. These engravings provide detailed depictions of anthropomorphic figures, such as lance-bearers and ritualistic dance scenes, as well as various animal species, bullfighting events, camel caravans, and celestial symbols such as the sun and other stars."},
  "golden-gate-bridge": {"article":"Golden Gate Bridge","text":"The San Francisco Golden Gate Bridge is a suspension bridge spanning the Golden Gate, the one-mile-wide (1.6 km) strait connecting San Francisco Bay and the Pacific Ocean in California, United States. The structure links San Francisco—the northern tip of the San Francisco Peninsula—to Marin County, carrying both U.S. Route 101 and California State Route 1 across the strait.","built":"1937","height":227,"architects":["Joseph Strauss"]},
  "golden-temple": {"article":"Golden Temple","text":"The Golden Temple is a gurdwara located in Amritsar, Punjab, India. It is the pre-eminent spiritual site of Sikhism and its holiest site. The gurdwara complex is a collection of buildings around the sanctum sanctorum and the sarovar (holy pool), known as the Amrit Sarovar. One of these is Akal Takht, part of the Panj Takht (five seats of authority in Sikhism) and the chief centre of religious authority of Sikhism.","built":"1589"},
  "golestan": {"article":"Golestan Palace","text":"The Golestan Palace is the former official royal Qajar complex in Tehran, Iran. One of the oldest historic monuments in the capital and a UNESCO World Heritage Site, the Golestan Palace consists of a group of eight palatial royal structures surrounded by a wall, today used mainly as museums, surrounded by an outer wall, which were once enclosed within the defensive walls of Tehran's citadel."},
  "gonbad-e-qabus": {"article":"Gonbad-e Kavus","text":"Gonbad-e Kabus is a city in the Central District of Gonbad-e Kavus County, Golestan province, Iran, serving as capital of both the county and the district. The modern name is a reference to an imposing ancient tower, the Tomb of Qabus. The monument itself was assigned to the neighboring historical city of Astarabad in the 1930s by the Iranian government.","elevation":52},
  "gondar": {"article":"Fasil Ghebbi","text":"The Fasil Ghebbi is a fortress located in Gondar, Amhara Region, Ethiopia. It was founded in the 17th century by Emperor Fasilides and was the home of Ethiopian emperors. Its unique architecture shows diverse influences including Portuguese, Hindu, and Arab characteristics. Because of its historical importance and architecture, the fortress was inscribed as a UNESCO World Heritage Site in 1979."},
  "gordion": {"article":"Gordion","text":"Gordion was the capital city of ancient Phrygia. It was located at the site of modern Yassıhüyük, about 70–80 km (43–50 mi) southwest of Ankara (capital of Turkey), in the immediate vicinity of Polatlı district. Gordion's location at the confluence of the Sakarya and Porsuk rivers gave it a strategic location with control over fertile land."},
  "goree": {"article":"Gorée","text":"Île de Gorée is one of the 19 communes d'arrondissement (i.e., districts) of the city of Dakar, Senegal. It is an 18.2-hectare (45-acre) island located two kilometres at sea from the main harbour of Dakar (14°40′N 17°24′W), famous as a destination for people interested in the Atlantic slave trade. Its population as of the 2013 census was 1,680 inhabitants, giving a density of 5,802 inhabitants per square kilometre (15,030/sq mi), which is only half the average density of the city of Dakar."},
  "gracanica": {"article":"Gračanica Monastery","text":"The Gračanica Monastery is a Serbian Orthodox monastery located in Kosovo. It was built by the Serbian king Stefan Milutin in 1321. The monastery was declared a Monument of Culture of Exceptional Importance in 1990 and in 2006 it was placed on UNESCO's World Heritage List under the name of Medieval Monuments in Kosovo as an extension of the Visoki Dečani site, which was overall placed on the List of World Heritage in Danger.","built":"1315"},
  "grace-bay": {"article":"Providenciales","text":"Providenciales (known locally as Provo) is an island in the northwest Caicos Islands, part of the Turks and Caicos Islands, a British Overseas Territory. The island has an area of 98 km2 (38 mi2) and had a population of 23,769 as of 2012, the latest date for which an island-by-island census was published by the government."},
  "grand-bassam": {"article":"Grand-Bassam","text":"Grand-Bassam is a town in southeastern Ivory Coast, lying east of Abidjan. It is a sub-prefecture of and the seat of Grand-Bassam Department; it is also a commune. During the late 19th century, Grand-Bassam was briefly the French colonial capital of Ivory Coast. Because of its outstanding examples of colonial architecture and town-planning, and the juxtaposition of the colonial town with a traditional Nzema village, the historic center of Grand-Bassam was designated a UNESCO World Heritage Site in 2012.","elevation":7},
  "grand-canyon": {"article":"Grand Canyon","text":"The Grand Canyon is a steep-sided canyon carved by the Colorado River in Arizona, United States. The Grand Canyon is 277 miles (446 km) long, up to 18 miles (29 km) wide and attains a depth of over a mile (6,093 feet or 1,857 meters). The canyon and adjacent rim are contained within Grand Canyon National Park, the Kaibab National Forest, Grand Canyon–Parashant National Monument, the Hualapai Indian Reservation, the Havasupai Indian Reservation and the Navajo Nation."},
  "grand-palace-bangkok": {"article":"Grand Palace","text":"The Grand Palace is a complex of buildings at the heart of Bangkok, Thailand. The palace has been the official residence of the Kings of Siam (and later Thailand) since 1782. The king, his court, and his royal government were based on the grounds of the palace until 1925. King Bhumibol Adulyadej (Rama IX), resided at the Chitralada Royal Villa and his successor King Vajiralongkorn (Rama X) resides at the Amphorn Sathan Residential Hall, both in the Dusit Palace, but the Grand Palace is still used for official events.","built":"1782"},
  "grand-place": {"article":"Grand-Place","text":"The Grand-Place or Grote Markt is the central square of Brussels, Belgium. It is surrounded by opulent Baroque guildhalls of the former Guilds of Brussels and two larger edifices: the city's Flamboyant Town Hall, and the neo-Gothic King's House or Bread House building, housing the Brussels City Museum. The square measures 68 by 110 metres (223 by 361 ft) and is entirely paved.","elevation":30},
  "graz-clock-tower": {"article":"Schlossberg (Graz)","text":"The Schlossberg is a tree-clad hill and the site of a fortress in the centre of the city of Graz, Austria. The hill, at 473 m (1,552 ft) above sea level, is now a public park and affords extensive views of the city. It is the site of several entertainment venues, cafés, and restaurants, and is managed by Holding Graz, the city-owned utility company.","elevation":474},
  "great-barrier-reef": {"article":"Great Barrier Reef","text":"The Great Barrier Reef is the world's largest coral reef system, composed of over 2,900 individual reefs and 900 islands stretching for over 2,300 kilometres (1,400 mi) over an area of approximately 344,400 square kilometres (133,000 mi2). The reef is located in the Coral Sea, off the coast of Queensland, Australia. It is separated from the coast by a channel 160 kilometres (100 mi) wide in places and over 61 metres (200 ft) deep."},
  "great-blue-hole": {"article":"Great Blue Hole","text":"The Great Blue Hole is a large marine sinkhole off the coast of Belize. It lies near the center of Lighthouse Reef, a small atoll 70 km (43 mi) from the mainland and Belize City. The hole is circular in shape, 318 m (1,043 ft) across and 124 m (407 ft) deep. It has a surface area of 70,650 square metres (760,500 sq ft)."},
  "great-smoky-mountains": {"article":"Great Smoky Mountains","text":"The Great Smoky Mountains are a mountain range rising along the Tennessee–North Carolina border in the southeastern United States. They are a subrange of the Appalachian Mountains and form part of the Blue Ridge Physiographic Province. The range is also known as the Smoky Mountains, and the name is commonly shortened to the Smokies.","elevation":2025},
  "great-wall": {"article":"Great Wall of China","text":"The Great Wall of China is a series of fortifications in China. They were built across the historical northern borders of ancient Chinese states and Imperial China as protection against various nomadic groups from the Eurasian Steppe. The first walls date to the 7th century BC; these were joined together in the Qin dynasty.","built":"700s BC","height":5.1},
  "great-zimbabwe": {"article":"Great Zimbabwe","text":"Great Zimbabwe was a city in the south-eastern hills of the modern country of Zimbabwe, near Masvingo. It was settled by ancestral Shona people from around 1000 AD, and served as the capital of the Kingdom of Great Zimbabwe from the 13th century. Major construction on the city began in the 11th century and continued until the 15th century."},
  "greenwich": {"article":"Royal Observatory, Greenwich","text":"The Royal Observatory, Greenwich is an observatory situated on a hill in Greenwich Park in south east London, overlooking the River Thames to the north. It played a major role in the history of astronomy and navigation, and because the Prime Meridian passed through it, it gave its name to Greenwich Mean Time, the precursor to today's Coordinated Universal Time (UTC).","built":"1675","elevation":68,"architects":["Christopher Wren"]},
  "grimeton": {"article":"Grimeton Radio Station","text":"Grimeton Radio Station in southern Sweden, close to Varberg in Halland, is an early longwave transatlantic wireless telegraphy station built in 1922–1924, that has been preserved as a historical site. Beginning in the 1920s, it was used for wireless communications to North America and other countries, and during World War II was one of Sweden's few telecommunication links to the rest of the world.","built":"1925"},
  "guadalupe": {"article":"Monastery of Saint Mary of Guadalupe","text":"The Royal Monastery of Saint Mary of Guadalupe is a Roman Catholic monastic establishment built during the 14th century located in Guadalupe, in Extremadura, Spain. It is located at the foot of the eastern side of the Sierra de las Villuercas and was one of the finest and most important monasteries in the country for more than four centuries."},
  "guaita-tower": {"article":"Guaita","text":"The Guaita, also known as the Rocca, is one of three towered peaks overlooking the city of San Marino, the capital of San Marino. The other two are Cesta and Montale."},
  "guanajuato": {"article":"Guanajuato","text":"Guanajuato, officially the Free and Sovereign State of Guanajuato, is one of the 32 states that make up the Federal Entities of Mexico. It is divided into 46 municipalities and its capital city is Guanajuato. It is located in central Mexico and is bordered by the states of Jalisco to the west, Zacatecas to the northwest, San Luis Potosí to the north, Querétaro to the east, and Michoacán to the south.","built":"1823","elevation":2072},
  "guilin": {"article":"Li River","text":"The Li River or Li Jiang is the name for the upper reaches of the Gui River in northeastern Guangxi, China. It is part of the Xijiang River system in the Pearl River basin, flowing 164 kilometres (102 mi) from Xing'an County to Pingle County."},
  "gustavia": {"article":"Gustavia","text":"Gustavia is the main town and capital of the island of Saint Barthélemy. Originally called Le Carénage, it was renamed in honor of King Gustav III of Sweden.","built":"1785"},
  "gyeongbokgung": {"article":"Gyeongbokgung","text":"Gyeongbokgung is a former royal palace in Seoul, South Korea. Established in 1395, it was the first royal palace of the Joseon dynasty, and is now one of the most significant tourist attractions in the country. The palace was among the first landmarks to be established in Seoul. It flourished under the 1418–1450 reign of Sejong the Great; Sejong led the creation of the native Korean script Hangul at the palace.","built":"1395"},
  "ha-long-bay": {"article":"Hạ Long Bay","text":"Hạ Long Bay or Halong Bay is a bay located in Northeastern Vietnam, administered by the city of Quảng Ninh. The name Hạ Long means \"descending dragon\". It features thousands of limestone karsts and islets in various shapes and sizes, for which it is listed as a UNESCO World Heritage Site and a popular travel destination."},
  "haamonga": {"article":"Haʻamonga ʻa Maui","text":"Haʻamonga ʻa Maui (\"The Burden of Maui\") is a stone trilithon located in Tonga, on the eastern part of the island of Tongatapu, in the village of Niutōua, in Heketā. It was built in the 13th century by King Tuʻitātui in honor of his two sons. The monument is sometimes called the \"Stonehenge of the Pacific\".","built":"13th century","height":5.2},
  "hadrians-villa": {"article":"Hadrian's Villa","text":"Hadrian's Villa was a monumental villa or palace complex built around AD 120 by emperor Hadrian (r.117–138) near Tivoli, about 20 km from Rome. Its remains are now included in a UNESCO World Heritage Site. It is one of the most imposing and complex Roman villas known. The complex contains over 30 monumental and scenic buildings arranged on a series of artificial esplanades at different heights and surrounded by gardens decorated with water basins and nymphaea (fountains)."},
  "hadrians-wall": {"article":"Hadrian's Wall","text":"Hadrian's Wall is a former defensive fortification of the Roman province of Britannia, begun in AD 122 in the reign of the Emperor Hadrian. Running from Wallsend on the River Tyne in the east to Bowness-on-Solway in the west of what is now northern England, it was a stone wall (in its final version) with large ditches in front and behind, stretching across the whole width of the island.","built":"AD 122","height":3.5},
  "haeinsa": {"article":"Haeinsa","text":"Haeinsa is a Buddhist temple in Gayasan National Park, South Gyeongsang Province, South Korea. It is the head temple of the Jogye Order of Korean Seon Buddhism. Haeinsa is most notable for being the home of the Tripitaka Koreana, the whole of the Buddhist Scriptures carved onto 81,350 wooden printing blocks, which it has housed since 1398.","built":"AD 802"},
  "haghpat": {"article":"Haghpat Monastery","text":"Haghpat Monastery, also known as Haghpatavank, is a medieval Armenian monastery complex in Haghpat, Armenia, built between the 10th and 13th century.","built":"10th century"},
  "hagia-sophia": {"article":"Hagia Sophia","text":"Hagia Sophia, officially the Hagia Sophia Grand Mosque, is a mosque and a major cultural and historical site in Istanbul, Turkey. It was formerly a church (360–1453) and a museum (1935–2020). The last of three church buildings to be successively erected on the site by the Eastern Roman Empire, it was completed in AD 537, becoming the world's largest interior space and among the first to employ a fully pendentive dome.","built":"AD 532","height":55,"architects":["Isidore of Miletus","Anthemius of Tralles"]},
  "hahoe": {"article":"Hahoe Folk Village","text":"The Hahoe Folk Village is a traditional village from the Joseon Dynasty, located in Andong, North Gyeongsang Province, South Korea. The 'Ha' is short for river and 'hoe' means to 'turn around, return, come back. The village is a valuable part of Korean culture because it preserves Joseon period-style architecture, folk traditions, valuable books, and an old tradition of clan-based villages."},
  "half-dome": {"article":"Half Dome","text":"Half Dome is a quartz monzonite batholith at the eastern end of Yosemite Valley in Yosemite National Park, California. It is a well-known rock formation in the park, named for its distinct shape. One side is a sheer face while the other three sides are smooth and round, making it appear like a dome cut in half. It stands at over 8,800 feet above sea level and is composed of quartz monzonite, an igneous rock that solidified several thousand feet within the Earth.","elevation":2693},
  "hallstatt": {"article":"Hallstatt","text":"Hallstatt is a small town in the Gmunden District of the Austrian state of Upper Austria. Situated between the southwestern shore of Hallstätter See and the steep slopes of the Dachstein massif, the town lies in the Salzkammergut region, on the national road linking Salzburg and Graz. Hallstatt is known for its production of salt, dating back to prehistoric times, and gave its name to the Hallstatt culture, the archaeological culture linked to Proto-Celtic and early Celtic people of the Early Iron Age in Europe, c. 800–450 BC.","elevation":511},
  "halsingland": {"article":"Decorated Farmhouses of Hälsingland","text":"The Decorated Farmhouses of Hälsingland is a World Heritage Site inscribed on 1 July 2012 as Sweden's fifteenth entry on the list. Seven farmhouses erected in the 19th century were eventually selected to represent the most distinguished and well preserved examples of local architectural and decorative tradition. Preparations for a nomination began during the 1990s.","built":"2012"},
  "hampi": {"article":"Hampi","text":"Hampi or Hampe, also referred to as the Group of Monuments at Hampi, is a UNESCO World Heritage Site located in the town of Hampi in Vijayanagara district, east-central Karnataka, India. Hampi predates the Vijayanagara Empire; it is mentioned in the Ramayana and the Puranas of Hinduism as Pampa Devi Tirtha Kshetra. Hampi continues as a religious centre, with the Virupaksha Temple, an active Adi Shankara-linked monastery and various monuments belonging to the old city.","elevation":467},
  "hashima": {"article":"Hashima Island","text":"Hashima Island, commonly called Gunkanjima, is an abandoned island about 15 kilometres (8 nautical miles) from the centre of Nagasaki, Japan. It is one of 505 uninhabited islands in Nagasaki Prefecture. The island's most notable features are its abandoned concrete buildings, undisturbed except by nature, and the surrounding seawall."},
  "hassan-tower": {"article":"Hassan Tower","text":"Hassan Tower or Tour Hassan is the minaret of an incomplete mosque in Rabat, Morocco. It was commissioned by Abu Yusuf Yaqub al-Mansur, the third caliph of the Almohad Caliphate, near the end of the 12th century. The tower was intended to be the largest minaret in the world, and the mosque, if completed, would have been the largest in the western Muslim world.","built":"1190s"},
  "hatra": {"article":"Hatra","text":"Hatra was an ancient city in Upper Mesopotamia located in present-day eastern Nineveh Governorate in northern Iraq. The ruins of the city lie 290 km (180 mi) northwest of Baghdad and 110 km (68 mi) southwest of Mosul. It was a strongly fortified caravan city and capital of the Arab Kingdom of Hatra, located between the Roman and Parthian/Sasanian Empires."},
  "hattusa": {"article":"Hattusa","text":"Hattusa, also Hattuşa, Ḫattuša, Hattusas, or Hattusha, was the capital of the Hittite Empire in the late Bronze Age during two distinct periods. Its ruins lie near modern Boğazkale, Turkey (originally Boğazköy), within the great loop of the Kızılırmak River. French archeologist Charles Texier brought attention to the ruins after his visit in 1834."},
  "hawa-mahal": {"article":"Hawa Mahal","text":"The Hawa Mahal is a palace in the city of Jaipur, Rajasthan, India. Built from red and pink sandstone, it is on the edge of the City Palace, Jaipur, and extends to the Zenana, or women's chambers. Hawa Mahal, also known as the \"Palace of Winds\", was built in 1799 by Maharaja Sawai Pratap Singh. The palace is known for its honeycomb-like façade, featuring numerous small windows and balconies.","built":"1799","architects":["Lal Chand Ustad"]},
  "hawaii-volcanoes": {"article":"Kīlauea","text":"Kīlauea is an active shield volcano in the Hawaiian Islands, located along the southeastern shore of Hawaii Island. The volcano is between 210,000 and 280,000 years old and grew above sea level about 100,000 years ago. Since the islands were settled, it has been the most active of the five volcanoes that together form the island and among the most active volcanoes on Earth.","elevation":1247},
  "hegra": {"article":"Hegra","text":"Hegra, also known as Mada'in Salih, is an archaeological site located in the area of Al-'Ula within Medina Province in the Hejaz region, Saudi Arabia. A majority of the remains date from the time of the Nabataean Kingdom, when the city was founded. The site constituted the kingdom's southernmost and second largest city after its capital, Petra (modern-day Jordan)."},
  "hercules-kassel": {"article":"Hercules monument (Kassel)","text":"The Hercules monument is a landmark in the German city of Kassel. It is located in the Bergpark Wilhelmshöhe (Wilhelmshöhe Mountainpark) in northern Hesse, Germany. Hercules is a copper statue depicting the ancient Greek demigod Heracles. The statue is located at the top of a pyramid, which stands on top of the octagon; the statue and the other parts of the monument were constructed at different times.","built":"1717"},
  "himeji-castle": {"article":"Himeji Castle","text":"Himeji Castle is a hilltop Japanese castle complex situated in Himeji, a city in Hyōgo Prefecture, Japan. The castle is regarded as the finest surviving example of prototypical Japanese castle architecture, comprising a network of 83 structures with advanced defensive systems from the feudal period. The castle is frequently known as Hakuro-jō or Shirasagi-jō (\"White Egret Castle\" or \"White Heron Castle\") because of its brilliant white exterior and supposed resemblance to a bird taking flight.","built":"1347"},
  "hiroshima-peace-memorial": {"article":"Hiroshima Peace Memorial","text":"The Hiroshima Peace Memorial, originally the Hiroshima Prefectural Industrial Promotion Hall, and now commonly called the Genbaku Dome, Atomic Bomb Dome or A-Bomb Dome, is part of Hiroshima Peace Memorial Park in Hiroshima, Japan, and was designated a UNESCO World Heritage Site in 1996. The building is a prominent structure that remained standing in the area around the atomic bombing of Hiroshima on 6 August 1945, three days before the atomic bombing of Nagasaki and nine days before Japan surrendered, ending World War II.","built":"1915","height":25},
  "historic-cairo": {"article":"Cairo Citadel","text":"The Citadel of Cairo or Citadel of Saladin is a medieval Islamic-era fortification in Cairo, Egypt. Its construction was begun by Salah ad-Din al-Ayubi (Saladin) in 1176 and continued by subsequent Egyptian rulers. It was the seat of government in Egypt and the residence of its rulers for nearly 700 years from the 13th century until the construction of Abdeen Palace in the 19th century.","built":"1176"},
  "historic-jeddah": {"article":"Al-Balad, Jeddah","text":"Al-Balad, also known as Jeddah Historic District, is the historical area of Jeddah, the second largest city of Saudi Arabia. Al-Balad can literally be translated to \"The Town\". Al-Balad is the historic center of the City of Jeddah. Traditional Hijazi houses are characterized by their wooden Roshan windows, and wooden mushrabiyas."},
  "hoi-an": {"article":"Hội An Ancient Town","text":"Hoi An Ancient Town is a heritage site and ancient trading post located in Hoi An, which served as an important trading post for foreign traders to Vietnam from the 15th until the 19th century, the status of which is still partly maintained by the newer city today. The ancient town contains a network of buildings and structures, consisting of 1360 ancient and unique monuments & heritage sites, including 1068 preserved houses and the Japanese Bridge."},
  "holasovice": {"article":"Holašovice","text":"Holašovice is a small historic village located in the south of the Czech Republic, 16 kilometres west of České Budějovice. Village belongs to the municipality Jankov. To the south lies the protected landscape area of Blanský Forest. The village was deserted after the Second World War, allowing its medieval plan and vernacular buildings in the South Bohemian Folk or Rural Baroque style to remain intact.","elevation":505},
  "holloko": {"article":"Hollókő","text":"Hollókő is a village in northern Hungary, located in Nógrád County. The village, which was constructed in the 13th century and developed in the 18th and 19th centuries, is a well-preserved ethnographic village of the Palóc people, with traditional wooden architecture and layout of buildings, farms, and orchards. Because of its exceptional preservation and testimony to rural life before the arrival of modern farming practices, the village was inscribed as a UNESCO World Heritage Site in 1987."},
  "holstentor": {"article":"Holsten Gate","text":"The Holsten Gate (Low German and German: Holstentor) is a city gate marking off the western boundary of the old center of the Hanseatic city of Lübeck. Built in 1464, the Brick Gothic construction is one of the relics of Lübeck's medieval city fortifications and one of two remaining city gates, the other being the Citadel Gate (Burgtor)."},
  "holy-sepulchre": {"article":"Church of the Holy Sepulchre","text":"The Church of the Holy Sepulchre, also known as the Church of the Resurrection, is a fourth-century church in the Christian Quarter of the Old City of Jerusalem. The church is simultaneously the seat of the Armenian Patriarchate of Jerusalem, the Greek Orthodox Patriarchate of Jerusalem, and the Catholic Latin Patriarchate of Jerusalem.","built":"AD 335"},
  "holy-trinity-column": {"article":"Holy Trinity Column, Olomouc","text":"The Holy Trinity Column in Olomouc, in the Czech Republic is a Baroque monument (Trinity column) that was built between 1716 and 1754. The main purpose was to celebrate the Catholic Church and faith, partly caused by feeling of gratitude for ending a plague, which struck Moravia (now in the Czech Republic) between 1713 and 1715.","built":"1715","height":35,"architects":["Wenzel Render"]},
  "horezu": {"article":"Horezu Monastery","text":"The Horezu Monastery or Hurezi Monastery was founded in 1690 by Prince Constantin Brâncoveanu in the town of Horezu, Wallachia, Romania. It is considered to be a masterpiece of \"Brâncovenesc style\", known for its architectural purity and balance, the richness of its sculpted detail, its treatment of religious compositions, its votive portraits, and its painted decorative works.","built":"1687","height":14},
  "horyu-ji": {"article":"Hōryū-ji","text":"Hōryū-ji is a Buddhist temple that was once one of the powerful Seven Great Temples, located in Ikaruga, Nara Prefecture, Japan. Built shortly after Buddhism was introduced to Japan, it is also one of the oldest Buddhist sites in the country. Its full name is Hōryū Gakumonji, or Learning Temple of the Flourishing Law, with the complex serving as both a seminary and monastery.","built":"AD 607"},
  "hosios-loukas": {"article":"Hosios Loukas","text":"Hosios Loukas is a historic walled monastery situated near the town of Distomo, in Boeotia, Greece. Founded in the mid-10th century, the monastery is one of the most important monuments of Middle Byzantine architecture and art, and has been listed on UNESCO's World Heritage Sites since 1990, along with the monasteries of Nea Moni and Daphnion.","built":"10th century"},
  "hospicio-cabanas": {"article":"Hospicio Cabañas","text":"The Hospicio Cabañas or Cabañas Museum in Guadalajara, Jalisco was one of the oldest and largest orphanage and hospital complexes in the Americas. Now turned into a museum, the main hall hosts the magnum opus frescoes of muralist painter José Clemente Orozco. The place was designated a UNESCO World Heritage Site in 1997.","built":"1810","architects":["Manuel Tolsá"]},
  "huangshan": {"article":"Huangshan","text":"Huangshan, literally meaning the Yellow Mountain(s), is a mountain range in southern Anhui province in eastern China. It was originally called \"Yishan\", and it was renamed because of a legend that the Yellow Emperor once made alchemy here. Vegetation on the range is thickest below 1,100 meters (3,600 ft), with trees growing up to the treeline at 1,800 meters (5,900 ft).","elevation":1864},
  "hue": {"article":"Imperial City of Huế","text":"The Imperial City or Imperial Palace also known as Đại Nội, is a royal enclosure within the walled city of Huế, the former imperial capital of Vietnam during the Nguyễn dynasty. It contains the palaces that housed the imperial family, as well as shrines, gardens, and offices for mandarins. Constructed in 1804 under Emperor Gia Long as a new capital and later re-modelled and enlarged to its current scale in 1833, it mostly served as a ceremonial function and imperial residence during the French colonial period.","built":"1833"},
  "humahuaca": {"article":"Quebrada de Humahuaca","text":"The Quebrada de Humahuaca is a narrow mountain valley located in the province of Jujuy in northwest Argentina, 1,649 km (1,025 mi) north of Buenos Aires (23°11′59″S 65°20′56″W). It is about 155 km (96 mi) long, oriented north–south, bordered by the Altiplano in the west and north, by the Sub-Andean hills in the east, and by the warm valleys (Valles Templados) in the south.","elevation":3224},
  "humayuns-tomb": {"article":"Humayun's tomb","text":"Humayun's tomb is the tomb of the Mughal Emperor Humayun located in Delhi, India. The tomb was commissioned by Humayun's first wife and chief consort, Empress Bega Begum, under her patronage in 1558, and designed by the Persian architects Mirak Mirza Ghiyas and his son, Sayyid Muhammad, whom she personally chose. It was the first garden-tomb on the Indian subcontinent, and is located in Nizamuddin East, Delhi, close to the Dina-panah Citadel, also known as Purana Qila (Old Fort), that Humayun founded in 1538.","built":"1560","height":43},
  "humberstone": {"article":"Humberstone and Santa Laura Saltpeter Works","text":"Humberstone and Santa Laura Saltpeter Works are two former saltpeter refineries located in northern Chile. They were declared a UNESCO World Heritage Site in 2005, as a testament to the historical importance of saltpeter mining in Chile and the culture and social agenda that developed around it in the late 19th century."},
  "hungarian-parliament": {"article":"Hungarian Parliament Building","text":"The Hungarian Parliament Building, also known as the Parliament of Budapest after its location, is the seat of the National Assembly of Hungary, a notable landmark of Hungary, and a popular tourist destination in Budapest. It is situated on Kossuth Square in the Pest side of the city, on the eastern bank of the Danube.","built":"2nd millennium","height":96,"architects":["Imre Steindl"]},
  "hvalsey": {"article":"Hvalsey Church","text":"Hvalsey Church was a Catholic church at the abandoned Greenlandic Norse homestead of Hvalseyjarfjord (near modern-day Qaqortoq). The best preserved Norse ruins in Greenland, the church was also the location of the last written record of the Greenlandic Norse, a wedding in September 1408."},
  "hwaseong": {"article":"Hwaseong Fortress","text":"Hwaseong Fortress or Suwon Hwaseong is a Korean fortress surrounding the centre of Suwon, the provincial capital of Gyeonggi Province, South Korea. It was built from 1794 to 1796 by King Jeongjo of Joseon to house and honor the remains of his biological father, Crown Prince Sado. Sado had been executed by being locked in a rice chest by his father, King Yeongjo."},
  "iguazu-falls": {"article":"Iguazu Falls","text":"The Iguazú Falls or Iguaçu Falls are waterfalls of the Iguazu River on the border of the Argentine province of Misiones and the Brazilian state of Paraná. Together, they make up the largest waterfall system in the world. The falls divide the river into the upper and lower Iguazu. The Iguazu River rises near the heart of the city of Curitiba.","height":82},
  "ilulissat": {"article":"Ilulissat Icefjord","text":"Ilulissat Icefjord is a fjord in western Greenland. Located 250 km north of the Arctic Circle, the Ilulissat Icefjord runs west 40 km (25 mi) from the Greenland ice sheet to Disko Bay just south of the town of Ilulissat. Ilulissat Icefjord was declared a UNESCO World Heritage Site in 2004 because of its natural beauty and the importance of the fast-moving Jacobshavn Glacier in developing the current scientific understanding of anthropogenic climate change.","built":"2003"},
  "independence-hall": {"article":"Independence Hall","text":"Independence Hall is a historic civic building in Philadelphia, Pennsylvania, where both the Declaration of Independence and the Constitution of the United States were debated and adopted by the Founding Fathers of the United States. The building, which is the centerpiece of Independence National Historical Park, was designated a World Heritage Site in 1979.","built":"1753","architects":["Edmund Woolley","Andrew Hamilton","William Strickland"]},
  "ironbridge": {"article":"The Iron Bridge","text":"The Iron Bridge is a cast iron arch bridge that spans the Ironbridge Gorge of the River Severn in Shropshire, England. Opened in 1781, it was the first major bridge in the world to be made of cast iron. Its success inspired the widespread use of cast iron as a structural material, and today the bridge is celebrated as a symbol of the Industrial Revolution.","built":"1779","height":30,"architects":["Thomas Farnolls Pritchard"]},
  "itsukushima": {"article":"Itsukushima Shrine","text":"Itsukushima Shrine is a Shinto shrine on the island of Itsukushima (popularly known as Miyajima), best known for its \"floating\" torii. It is in the city of Hatsukaichi, in Hiroshima Prefecture in Japan, accessible from the mainland by ferry at Miyajimaguchi Station. The shrine complex is listed as a UNESCO World Heritage Site, and the Japanese government has designated several buildings and possessions as National Treasures.","built":"AD 593"},
  "ivanovo": {"article":"Rock-hewn Churches of Ivanovo","text":"The Rock-hewn Churches of Ivanovo are a group of monolithic churches, chapels and monasteries hewn out of solid rock and completely different from other monastery complexes in Bulgaria, located near the village of Ivanovo, 20 kilometers (12 mi) south of Rousse, on the high rocky banks of the Rusenski Lom, 32 meters (105 ft) above the river.","built":"AD 13"},
  "jameh-isfahan": {"article":"Jameh Mosque of Isfahan","text":"The Jāmeh Mosque of Isfahān or Jāme' Mosque of Isfahān, also known as the Atiq Mosque and the Friday Mosque of Isfahān, is a historic congregational mosque (Jāmeh), located in Isfahan, Iran. The mosque is the result of continual construction, reconstruction, additions and renovations on the site from c. 771 CE to the end of the 20th century.","built":"AD 841"},
  "jantar-mantar": {"article":"Jantar Mantar","text":"A Jantar Mantar is an assembly of stone-built astronomical instruments, designed to be used with the naked eye. There were five Jantar Mantars in India, built between 1724 and 1735. All were built at the command of the Sawai Jai Singh II, who had a keen interest in mathematics, architecture and astronomy. A total of five Jantar Mantars were constructed across North India: Jaipur, Delhi, Ujjain, Varanasi, and Mathura (the last of which no longer exists)."},
  "jelling": {"article":"Jelling stones","text":"The Jelling stones are massive carved runestones from the 10th century, found at the town of Jelling in Denmark. The older of the two Jelling stones was raised by King Gorm the Old in memory of his wife Thyra. The larger of the two stones was raised by King Gorm's son, Harald Bluetooth, in memory of his parents, celebrating his conquest of Denmark and Norway, and his conversion of the Danes to Christianity."},
  "jeronimos": {"article":"Jerónimos Monastery","text":"The Jerónimos Monastery or Hieronymites Monastery is a former monastery of the Order of Saint Jerome near the Tagus river in the parish of Belém, in the Lisbon Municipality, Portugal. It became the necropolis of the Portuguese royal dynasty of Aviz in the 16th century but was secularized on 28 December 1833 by state decree and its ownership transferred to the charitable institution, Real Casa Pia de Lisboa.","built":"1502","architects":["Diogo de Boitaca","Diego de Torralva","Nicolau Chanterene"]},
  "jiangjun-tomb": {"article":"Capital Cities and Tombs of the Ancient Koguryo Kingdom","text":"The Capital Cities and Tombs of the Ancient Koguryo Kingdom is an UNESCO World Heritage Site which includes a number of archaeological sites currently in Ji'an, Jilin Province and Huanren, Liaoning Province in Northeast China. Goguryeo (or Koguryo, \"Gaogouli\" in Chinese), (37 BCE – 668 CE) was a Korean Kingdom located in the northern and central parts of the Korean Peninsula and the southern and central parts of Manchuria."},
  "jiuzhaigou": {"article":"Jiuzhaigou","text":"Jiuzhaigou is a nature reserve and national park located in the north of Sichuan Province in southwestern China. A long valley running north to south, Jiuzhaigou was inscribed by UNESCO as a World Heritage Site in 1992 and a World Biosphere Reserve in 1997. It belongs to the category V (Protected Landscape) in the IUCN system of protected area categorization.","built":"1978"},
  "jodrell-bank": {"article":"Jodrell Bank Observatory","text":"Jodrell Bank Observatory in Cheshire, England, hosts a number of radio telescopes as part of the Jodrell Bank Centre for Astrophysics at the University of Manchester. The observatory was established in 1945 by Bernard Lovell, a radio astronomer at the university, to investigate cosmic rays after his work on radar in the Second World War.","built":"1945","elevation":77},
  "jongmyo": {"article":"Jongmyo","text":"Jongmyo is a Confucian royal ancestral shrine in the Jongno District of Seoul, South Korea. It was originally built during the Joseon period (1392–1897) for memorial services for deceased kings and queens. According to UNESCO, the shrine is the oldest royal Confucian shrine preserved and the ritual ceremonies continue a tradition established in the 14th century."},
  "joya-de-ceren": {"article":"Joya de Cerén","text":"Joya de Cerén (Jewel of Cerén in Spanish) is an archaeological site in La Libertad Department, El Salvador, containing the remains of a pre-Columbian Maya farming village. The site is located in the Zapotitán Valley, approximately 36 km (22 mi) northwest of San Salvador. It is often called the \"Pompeii of the Americas\", for its similar preservation beneath volcanic ash."},
  "jungfrau": {"article":"Jungfrau-Aletsch protected area","text":"The Jungfrau-Aletsch protected area (officially Swiss Alps Jungfrau-Aletsch) is located in south-western Switzerland between the cantons of Bern and Valais. It is a mountainous region in the easternmost side of the Bernese Alps, containing the northern wall of Jungfrau and Eiger, and the largest glaciated area in western Eurasia, comprising the Aletsch Glacier.","built":"2001"},
  "kaesong": {"article":"Kaesong","text":"Kaesong is a special city in the southern part of North Korea (formerly in North Hwanghae Province), and the capital of Korea during the Taebong kingdom and subsequent Goryeo dynasty. The city is near the Kaesong Industrial Region close to the border with South Korea and contains the remains of the Manwoldae palace. Called Songdo while it was the ancient capital of Goryeo, the city prospered as a trade centre that produced Korean ginseng.","elevation":489},
  "kaieteur": {"article":"Kaieteur Falls","text":"Kaieteur Falls is one of the most powerful single-drop waterfalls in the world. It is located on the Potaro River in Kaieteur National Park, central Essequibo Territory, Guyana. It is 226 metres (741 ft) high when measured from its plunge over a sandstone and conglomerate cliff to the first break. It then flows over a series of steep cascades that, when included in the measurements, bring the total height to 251 metres (822 ft).","height":226},
  "kaiping-diaolou": {"article":"Diaolou","text":"Diaolou are fortified multi-storey watchtowers in rural villages, generally made of reinforced concrete. These towers are located mainly in Kaiping, Guangdong province, China. In 2007, UNESCO designated the Kaiping Diaolou and Villages a World Heritage Site, which covers four separate Kaiping village areas: Sanmenli, Zilicun, Jinjiangli, and Majianglong village cluster."},
  "kairouan": {"article":"Great Mosque of Kairouan","text":"The Great Mosque of Kairouan, also known as the Mosque of Uqba, is a mosque situated in the UNESCO World Heritage town of Kairouan, Tunisia and is one of the largest Islamic monuments in North Africa. Established by the Arab general Uqba ibn Nafi in 50 AH (670/671 CE) at the founding of the city of Kairouan, the mosque occupies an area of over 9,000 square metres (97,000 sq ft).","built":"AD 670"},
  "kamchatka": {"article":"Volcanoes of Kamchatka","text":"The volcanoes of Kamchatka are a large group of volcanoes situated on the Kamchatka Peninsula, in eastern Russia. The Kamchatka River and the surrounding central side valley are flanked by large volcanic belts containing around 160 volcanoes, 29 of them still active. The peninsula has a high density of volcanoes and associated volcanic phenomena, with 29 active volcanoes being included in the six UNESCO World Heritage List sites in the Volcanoes of Kamchatka group, most of them on the Kamchatka Peninsula."},
  "karakul": {"article":"Karakul (Tajikistan)","text":"Karakul or Qarokul is an endorheic lake, 25 km (16 mi) in diameter, located within a 52 km (32 mi) impact crater. It is located in the Tajik National Park in the Pamir Mountains in Tajikistan.","elevation":3900},
  "karnak": {"article":"Karnak","text":"The Karnak Temple Complex, commonly known as Karnak, comprises a vast mix of temples, pylons, chapels, and other buildings near Luxor, Egypt. Construction at the complex began during the reign of Senusret I (reigned 1971–1926 BCE) in the Middle Kingdom (c. 2000–1700 BC) and continued into the Ptolemaic Kingdom (305–30 BCE), although most of the extant buildings date from the New Kingdom.","built":"1900 BC"},
  "karthala": {"article":"Mount Karthala","text":"Mount Karthala or Karthola is an active shield volcano and the highest point of the Comoros at 2,361 m (7,746 ft) above sea level. It is the southernmost and larger of the two volcanoes forming Grande Comore island, the largest island in the nation of Comoros. The Karthala volcano is very active, having erupted more than 20 times since the 19th century.","elevation":2361},
  "kasbah-of-algiers": {"article":"Casbah of Algiers","text":"The Casbah of Algiers, commonly referred to as the Casbah, corresponds to the old town or medina of Algiers, founded in 944 by the Zirids. It is a historic district that has been listed as a UNESCO World Heritage Site since 1992. Administratively, it is located within the municipality of Casbah, in the province of Algiers."},
  "kasubi-tombs": {"article":"Kasubi Tombs","text":"The Kasubi Tombs in Kampala, Uganda, is the site of the burial grounds for four kabakas (kings of Buganda) and other members of the Baganda royal family. As a result, the site remains an important spiritual and political site for the Ganda people, as well as an important example of traditional architecture. It became a UNESCO World Heritage Site in December 2001, when it was described as \"one of the most remarkable buildings using purely vegetal materials in the entire region of sub-Saharan Africa\"."},
  "kathmandu-durbar": {"article":"Kathmandu Valley","text":"The Kathmandu Valley, also known as the Nepal Valley, Nepa Valley or Swaniga:, National Capital Area, is a bowl-shaped valley located in the Himalayan mountains of Nepal. It lies at the crossroads of ancient civilizations of the Indian subcontinent and the broader Asian continent, and has at least 130 important monuments, including several pilgrimage sites for Hindus and Buddhists."},
  "kazan-kremlin": {"article":"Kazan Kremlin","text":"The Kazan Kremlin is the chief historic citadel of Kazan, a city in Russia. It was built at the behest of Ivan the Terrible on the ruins of the former castle of Kazan khans. It was declared a World Heritage Site in 2000."},
  "kazanlak": {"article":"Thracian Tomb of Kazanlak","text":"The Thracian Tomb of Kazanlak is a vaulted-brickwork \"beehive\" (tholos) tomb that is located near the town of Kazanlak in central Bulgaria. The tomb is part of a large royal Thracian necropolis in the Valley of the Thracian Rulers near their ancient capital of Seuthopolis in a region where more than a thousand tombs of royalty and members of the Thracian aristocracy can be found."},
  "kew-gardens": {"article":"Palm House, Kew Gardens","text":"The Palm House is a large palm house in the Royal Botanic Gardens, Kew, in London, that specialises in growing palms and other tropical and subtropical plants. It was completed in 1848. Many of its plants are endangered or extinct in the wild. Features include an upper walkway, taking the visitor into the branches of the larger plants.","built":"1848","architects":["Decimus Burton"]},
  "khajuraho": {"article":"Kandariya Mahadeva Temple","text":"The Kandariya Mahadeva Temple, meaning \"the Great God of the Cave\", is the largest and most ornate Hindu temple in the medieval temple group found at Khajuraho in Madhya Pradesh, India. It is considered as one of the best examples of temples preserved from the medieval period in India. Because of its outstanding preservation and testimony to the Chandela culture, the temple was inscribed on the UNESCO World Heritage List in 1986."},
  "khami": {"article":"Khami","text":"Khami (also written as Khame, Kame, or Kami) is a ruined city located 22 kilometres (14 mi) west of Bulawayo, in Zimbabwe. It was once the capital of the Kingdom of Butua of the Torwa dynasty. It is now a national monument and became a UNESCO World Heritage Site in 1986."},
  "khiva": {"article":"Itchan Kala","text":"Itchan Kala is the walled inner town of the city of Khiva, Uzbekistan. Since 1990, it has been protected as a World Heritage Site. The old town retains more than 50 historic monuments and 250 old houses, dating primarily from the 18th or 19th centuries. Juma Mosque, for instance, was established in the 10th century and rebuilt from 1788 to 1789, although its celebrated hypostyle hall still retains 112 columns taken from ancient structures."},
  "kibira": {"article":"Kibira National Park","text":"The Kibira National Park is a national park in northwestern Burundi. Overlapping four provinces and covering 400 km2 (150 sq mi), Kibira National Park lies atop the mountains of the Congo-Nile Divide. It extends north from the provincial town of Muramvya to the border of Rwanda where it is contiguous with the Nyungwe National Park.","built":"1933"},
  "kilimanjaro": {"article":"Mount Kilimanjaro","text":"Mount Kilimanjaro is a large dormant stratovolcano in Tanzania. It is the highest mountain in Africa and the highest free-standing mountain above sea level in the world, at 5,895 m (19,341 ft) above sea level and 4,900 m (16,100 ft) above its plateau base. It is also the highest volcano in the Eastern Hemisphere and the fourth most prominent peak on Earth.","elevation":5895},
  "kinabalu": {"article":"Mount Kinabalu","text":"Mount Kinabalu is the highest mountain in Malaysia and Maritime Southeast Asia, located on the island of Borneo in Sabah. With a height of 4,095 metres (13,435 ft), it is the third-highest peak of an island on Earth, the 28th-highest peak in Southeast Asia, and 20th-most-prominent mountain in the world. The mountain is located in Ranau district, West Coast Division of Sabah, Malaysia.","elevation":4095},
  "kinderdijk": {"article":"Kinderdijk windmills","text":"The Kinderdijk windmills are a group of 19 monumental windmills in the Alblasserwaard polder, in the province of South Holland, Netherlands. Most of the mills are part of the village of Kinderdijk in the municipality of Molenlanden, and one mill, De Blokker, is part of the municipality of Alblasserdam. Built in 1738 and 1740, to keep water out of the polder, it is the largest concentration of old windmills in the Netherlands and one of the best-known Dutch tourist sites."},
  "kinkakuji": {"article":"Kinkaku-ji","text":"Kinkaku-ji, officially named Rokuon-ji, is a Zen Buddhist temple in Kyoto, Japan and a tourist attraction. It is designated as a World Heritage Site, a National Special Historic Site, a National Special Landscape, and one of the 17 Historic Monuments of Ancient Kyoto. The temple is nicknamed after its reliquary (shariden), the Golden Pavilion, whose top two floors are coated in 0.5 μm gold leaf.","built":"1397"},
  "kissama": {"article":"Quiçama National Park","text":"Quiçama National Park, also known as Kissama National Park, is a national park in northwestern Angola. It is the only functioning national park in all of Angola, with the others being in disrepair due to the Angolan Civil War. The park is approximately 70 km from Luanda, the Angolan capital. The park covers 3 million acres (12,000 km²), more than twice the size of the U.S. state of Rhode Island.","built":"1957"},
  "kiyomizu-dera": {"article":"Kiyomizu-dera","text":"Kiyomizu-dera is a Buddhist temple located in eastern Kyoto, Japan. It belongs to the Kita-Hosso sect of Japanese Buddhism and its honzon is a hibutsu statue of Jūichimen Kannon. The temple's full name is Otowa-san Kiyomizu-dera. The temple is the 16th stop on the Saigoku Kannon Pilgrimage route. Along with Kōryū-ji and Kurama-dera, it is one of the few temples in Kyoto that predates the foundation of the capital to Heian-kyō.","built":"AD 778"},
  "kizhi": {"article":"Kizhi Pogost","text":"Kizhi Pogost is a historical site dating from the 17th century on Kizhi island. The island is located on Lake Onega in the Republic of Karelia (Medvezhyegorsky District), Russia. The pogost is the area inside a fence which includes two large wooden churches (the 22-dome Transfiguration Church and the 9-dome Intercession Church) and a bell-tower.","built":"1714"},
  "knossos": {"article":"Knossos","text":"Knossos is an archaeological site and ancient urban centre in Crete, Greece. It is located within the southern periphery of Heraklion, about 5 km (3.1 mi) south of the city's historic centre. The site was occupied from the Neolithic period into the first millennium AD and became the largest and best-known centre of the Minoan civilisation.","built":"7000 BC"},
  "koh-ker": {"article":"Koh Ker","text":"Koh Ker is a remote archaeological site in northern Cambodia about 120 kilometres (75 mi) away from Siem Reap and the ancient site of Angkor. It is a jungle filled region that is sparsely populated. More than 180 sanctuaries were found in a protected area of 81 square kilometres (31 sq mi). Only about two dozen monuments can be visited by tourists because most of the sanctuaries are hidden in the forest and the whole area is not fully demined."},
  "kokoda-track": {"article":"Kokoda Track","text":"The Kokoda Track or Kokoda Trail is a single-file foot thoroughfare that runs 96 kilometres (60 mi) overland – 60 kilometres (37 mi) in a straight line – through the Owen Stanley Range in Papua New Guinea (PNG). The track was the location of the 1942 World War II battle between Japanese and Allied – primarily Australian – forces in what was then the Australian territory of Papua."},
  "kolomenskoye": {"article":"Kolomenskoye","text":"Kolomenskoye is a former royal estate situated several kilometers to the southeast of the city center of Moscow, Russia, on the ancient road leading to the town of Kolomna (hence the name). The 390 hectare scenic area overlooks the steep banks of the Moskva River. It became a part of Moscow in the 1960s.","built":"1532"},
  "komodo": {"article":"Komodo National Park","text":"Komodo National Park is a national park in Indonesia within the Lesser Sunda Islands in the border region between the provinces of East Nusa Tenggara and West Nusa Tenggara. The park includes the three larger islands—Komodo, Padar and Rinca—and 26 smaller ones, with a total area of 1,733 km2 (669 sq mi), with 603 km2 (233 sq mi) of it land.","built":"1980","elevation":81},
  "konark": {"article":"Konark Sun Temple","text":"Konark Sun Temple is a 13th-century CE Hindu Sun temple at Konark about 35 kilometres (22 mi) northeast from Puri city on the coastline in Puri district, Odisha, India. The temple is attributed to king Narasingha Deva I of the Eastern Ganga dynasty about 1250 CE. Dedicated to the Hindu Sun-god Surya, it reflects the pinnacle of Kalingan architecture and artistic excellence, what remains of the temple complex has the appearance of a 30-metre (100 ft) high chariot with immense wheels and horses, all carved from stone.","built":"13th century"},
  "kotor": {"article":"Bay of Kotor","text":"The Bay of Kotor, also known as the Gulf of Kotor or just as the Boka, is a winding bay of the Adriatic Sea in southwestern Montenegro and the region of Montenegro concentrated around the bay. It is also the southernmost part of the historical region of Dalmatia. At the entrance to the Bay there is Prevlaka, a small peninsula in southern Croatia."},
  "kourou-space-centre": {"article":"Guiana Space Centre","text":"The Guiana Space Centre, also called Europe's Spaceport, is a spaceport to the northwest of Kourou in French Guiana, an overseas region of France in South America. Kourou is located approximately 500 kilometres north of the equator at a latitude of 5°. In operation since 1968, it is a suitable location for a spaceport because of its near equatorial location and open sea to the east and north.","built":"1964"},
  "koutammakou": {"article":"Koutammakou","text":"Koutammakou, the Land of the Batammariba is a cultural landscape designated in 2004 and expanded in 2023 as a UNESCO World Heritage Site at the border between northern Togo and Benin. The area features traditional mud tower-houses which remain the preferred style of living. The traditional mud houses are known as a national symbol of Togo."},
  "krak-des-chevaliers": {"article":"Krak des Chevaliers","text":"Krak des Chevaliers is a medieval castle in Syria and one of the most important preserved medieval castles in the world. The site was first inhabited in the 11th century by Kurdish troops garrisoned there by the Mirdasids. In 1142 it was given by Raymond II, Count of Tripoli, to the order of the Knights Hospitaller. It remained occupied by them until it was reconquered by the Muslims in 1271.","built":"1031"},
  "krakow": {"article":"Kraków","text":"Kraków, officially the Royal Capital City of Kraków, is the second-largest and one of the oldest cities in Poland. Situated on the Vistula river in Lesser Poland Voivodeship, the city has a population of 816,614 (2025), with 1,428,363 people living in the Kraków metropolitan area. Kraków was the official capital of Poland until 1596 and has traditionally been one of the leading centres of Polish academic, cultural and artistic life.","elevation":219},
  "kronborg": {"article":"Kronborg","text":"Kronborg is a castle and historical stronghold in the town of Helsingør, Denmark. Immortalised as Elsinore in William Shakespeare's play Hamlet, Kronborg is one of the most important Renaissance castles in Northern Europe. It was inscribed on the UNESCO World Heritage List in 2000. The castle is situated on the extreme northeastern tip of the island of Zealand at the narrowest point of the Øresund, the sound between present Denmark and the provinces of present Sweden.","built":"1585","elevation":16},
  "kunta-kinteh-island": {"article":"Kunta Kinteh Island","text":"Kunta Kinteh Island, formerly called James Island and St Andrew's Island, is an island in the Gambia River, 30 km (19 mi) from the river mouth and near Juffureh in the Republic of the Gambia. Fort James is located on the island. It is less than 3.2 km (2 miles) from Albreda on the river's northern bank. As an important historical site in the West African slave trade, it is listed as a UNESCO World Heritage Site, together with related sites including a ruined Portuguese chapel and a colonial warehouse in Albreda, the Maurel Frères Building in Juffureh, and Fort Bullen and Six-Gun Battery, which are located at the mouth of the Gambia River."},
  "kunya-urgench": {"article":"Konye-Urgench","text":"Konye-Urgench, also known as Köneürgenç, Old Urgench or Urganj, is a city in north Turkmenistan, just south from its border with Uzbekistan. In 2022, it had a total population of 37,176 people. It is the site of the ancient town of Gurgānj, which contains the ruins of the capital of Khwarazm. The inhabitants of the ancient city deserted it in the early eighteenth century in order to develop a new settlement, and Konye-Urgench has remained undisturbed ever since."},
  "kutna-hora": {"article":"St. Barbara's Church, Kutná Hora","text":"Saint Barbara's Church is a Roman Catholic Church in Kutná Hora (Bohemia) in the style of a cathedral, and is sometimes referred to as the Cathedral of St Barbara. It is one of the most famous Gothic churches in central Europe and it is a UNESCO World Heritage Site. St Barbara is the patron saint of miners (among others), which was highly appropriate for a town whose wealth was based entirely upon its silver mines.","built":"14th century","architects":["Johann Parler"]},
  "kuwait-towers": {"article":"Kuwait Towers","text":"The Kuwait Towers are a group of three thin towers in Kuwait City, standing on a promontory into the Persian Gulf. They were the sixth, and last, group in the larger Kuwait Water Towers system of 34 towers, and were built in a style considerably different from the other five groups. The Kuwait Towers were officially inaugurated in March 1979 and are regarded as a landmark and symbol of modern Kuwait.","built":"1977","height":187,"architects":["Sune Lindström","Malene Bjørn"]},
  "la-soufriere-svg": {"article":"La Soufrière (Saint Vincent)","text":"La Soufrière or Soufrière Saint Vincent is an active volcano on the Caribbean island of Saint Vincent in Saint Vincent and the Grenadines. It is the highest peak on Saint Vincent, and has had eight recorded eruptions since 1718. The latest eruptive activity began on 27 December 2020 with the slow extrusion of a dome of lava, and culminated in a series of explosive events between 9 and 22 April 2021.","elevation":1220},
  "laas-geel": {"article":"Laas Geel","text":"Laas Geel, also spelled Laas Gaal, are cave formations on the rural outskirts of Hargeisa, Somaliland, situated in the Maroodi Jeex region of the country. They contain some of the earliest known cave paintings of domesticated African aurochs (Bos primigenius africanus) in the Horn of Africa. Laas Geel's rock art is estimated to be approximately 5,500 to 4,500 years old."},
  "lahore-fort": {"article":"Lahore Fort","text":"The Lahore Fort is a citadel in the Walled City of Lahore in Punjab, Pakistan. The fortress is located at the northern end of the Walled City and is spread over an area greater than 20 hectares (49 acres). It contains 21 notable monuments, some of which date to the era of emperor Akbar. It was almost entirely rebuilt in the 17th century, when the Mughal Empire was at its zenith."},
  "lake-assal": {"article":"Lake Assal (Djibouti)","text":"Lake Assal is a crater lake in central-western Djibouti. It is located at the western end of Gulf of Tadjoura between Arta Region, and Tadjoura Region, touching Dikhil Region, at the top of the Great Rift Valley, some 120 km (75 mi) west of Djibouti city. Lake Assal is a saline lake that lies 155 m (509 ft) below sea level in the Afar Triangle, making it the lowest point on land in Africa and the third-lowest point on Earth after the Sea of Galilee and the Dead Sea."},
  "lake-baikal": {"article":"Lake Baikal","text":"Lake Baikal is a rift lake and the deepest lake in the world. It is situated in southern Siberia, Russia, between the federal subjects of Irkutsk Oblast to the northwest and the Republic of Buryatia to the southeast. At 31,722 km2 (12,248 sq mi)—slightly larger than Belgium—Lake Baikal is the world's seventh-largest lake by surface area, as well as the second-largest lake in Eurasia after the Caspian Sea.","elevation":456},
  "lake-bled": {"article":"Lake Bled","text":"Lake Bled is a lake in the Julian Alps of the Upper Carniolan region of northwestern Slovenia, where it adjoins the town of Bled. The area is a tourist destination. The lake is 35 km (22 mi) from Ljubljana International Airport and 55 km (34 mi) from the capital city, Ljubljana. Lake Bled is 4.2 km (2.6 mi) from the Lesce–Bled train station.","elevation":475},
  "lake-district": {"article":"Lake District","text":"The Lake District, also known as the Lakes or Lakeland, is a mountainous region and national park in Cumbria, North West England. It is famous for its landscape, including its lakes, coast, and mountains, and for its literary associations with Beatrix Potter, John Ruskin, Arthur Ransome, and the Lake Poets. The Lakeland fells, or mountains, include England's highest: Scafell Pike, Helvellyn and Skiddaw.","built":"1951","elevation":978},
  "lake-malawi": {"article":"Lake Malawi National Park","text":"Lake Malawi National Park is a national park at the southern end of Lake Malawi in Malawi, Southeast Africa. It is the only national park in Malawi that was created with the purpose of protecting fish and aquatic habitats. Despite this being its main purpose, Lake Malawi National Park includes a fair amount of land, including a headland, the foreshore and several small rocky islands in Lake Malawi.","built":"1980"},
  "lalibela": {"article":"Lalibela","text":"Lalibela is a town in the Amhara Region of Ethiopia. Located in the Lasta district and North Wollo Zone, it is a tourist site for its famous rock-cut monolithic churches designed in contrast to the earlier monolithic churches in Ethiopia. The whole of Lalibela is a large and important site for the antiquity, medieval, and post-medieval civilization of Ethiopia.","elevation":2500},
  "lamu": {"article":"Lamu","text":"Lamu or Lamu Town is a small town on Lamu Island, which in turn is a part of the Lamu Archipelago in Kenya on the continent of Africa. Situated 341 kilometres (212 mi) by road northeast of Mombasa that ends at Mokowe Jetty, from where the sea channel has to be crossed to reach Lamu Island, it is the headquarter of Lamu County and a UNESCO World Heritage Site.","elevation":15},
  "landwasser-viaduct": {"article":"Landwasser Viaduct","text":"The Landwasser Viaduct is a single-track six-arched curved limestone railway viaduct. It spans the Landwasser between Schmitten and Filisur, in the canton of Graubünden, Switzerland. Designed by Alexander Acatos, the Landwasser Viaduct was constructed between 1901 and 1902 by Müller & Zeerleder on behalf of the Rhaetian Railway, which both owns and operates it through to the present day.","built":"1902","height":65},
  "lanse-aux-meadows": {"article":"L'Anse aux Meadows","text":"L'Anse aux Meadows is an archaeological site, first excavated in the 1960s, of a Norse settlement dating to approximately 1000 CE. The site is located near St. Anthony on the northernmost tip of the island of Newfoundland in the Canadian province of Newfoundland and Labrador. With carbon dating estimates between 990 and 1050 CE (mean date 1014) and tree-ring dating of 1021, L'Anse aux Meadows is the only undisputed site of pre-Columbian trans-oceanic contact of Europeans with the Americas outside of Greenland."},
  "last-supper": {"article":"Santa Maria delle Grazie, Milan","text":"Santa Maria delle Grazie is a church and Dominican convent in Milan, northern Italy, and a UNESCO World Heritage Site. The convent contains the mural of The Last Supper by Leonardo da Vinci, which is in the refectory.","built":"15th century","architects":["Guiniforte Solari","Donato Bramante","Piero Portaluppi"]},
  "le-havre": {"article":"St. Joseph's Church, Le Havre","text":"St. Joseph's Church, Le Havre is a Roman Catholic church in Le Havre, France. From 1945 to 1964, the City of Le Havre commissioned Auguste Perret and his studio to head the rebuilding of the entire city after it had been completely destroyed by the British during World War II. St. Joseph's was built between 1951 and 1957/58 as part of this reconstruction.","built":"1956","height":107,"architects":["Auguste Perret"]},
  "le-morne": {"article":"Le Morne Brabant","text":"Le Morne Brabant is a peninsula at the extreme southwestern tip of the Indian Ocean island of Mauritius. On it is a basaltic monolith of the same name 556 metres (1,824 ft) high. Its summit covers an area of over 12 hectares (30 acres). There are many caves and overhangs on the steep slopes. It is largely surrounded by a lagoon and is a well known tourist attraction.","elevation":556},
  "leaning-tower": {"article":"Leaning Tower of Pisa","text":"The Leaning Tower of Pisa, or simply the Tower of Pisa (torre di Pisa), is the campanile, or freestanding bell tower, of Pisa Cathedral. It is known for its nearly four-degree lean, the result of an unstable foundation. The tower is one of three structures in Pisa's Cathedral Square (Piazza del Duomo), which includes the cathedral and Pisa Baptistry.","built":"1173","height":58,"architects":["Bonanno Pisano","Diotisalvi"]},
  "lednice": {"article":"Lednice–Valtice Cultural Landscape","text":"The Lednice–Valtice Cultural Landscape (also Lednice–Valtice Area or Lednice–Valtice Complex, Czech: Lednicko-valtický areál) is a cultural-natural landscape complex of 283.09 square kilometres (109.30 sq mi) in the South Moravian Region of the Czech Republic. It comprises the municipalities of Lednice, Valtice and Hlohovec, and the rural area of Břeclav."},
  "lencois-maranhenses": {"article":"Lençóis Maranhenses National Park","text":"Lençóis Maranhenses National Park (Parque Nacional dos Lençóis Maranhenses) is a national park in Maranhão state in northeastern Brazil, just east of the Baía de São José. Protected on June 2, 1981, the 155,000 ha (380,000-acre) park includes 70 km (43 mi) of coastline, and an interior composed of rolling sand dunes. During the rainy season, the valleys among the dunes fill with freshwater lagoons, prevented from draining by the impermeable rock beneath.","built":"1981"},
  "leon-cathedral": {"article":"León Cathedral, Nicaragua","text":"The Cathedral of the Assumption of Mary, also known as the \"Royal and Renowned Basilica Cathedral of the Assumption of the Blessed Virgin Mary\", is a significantly important and historic landmark in León, Nicaragua. The cathedral was awarded World Heritage Site status with the United Nations Educational, Scientific and Cultural Organization (UNESCO).","built":"1860"},
  "leptis-magna": {"article":"Leptis Magna","text":"Leptis or Lepcis Magna, also known by other names in antiquity, was a prominent city of the Carthaginian Empire and Roman Libya at the mouth of the Wadi Lebda in the Mediterranean. Established as a Punic settlement prior to 500 BC, the city experienced significant expansion under Roman Emperor Septimius Severus (r. 193–211), who was born in the city.","built":"7th century BC"},
  "leshan-buddha": {"article":"Leshan Giant Buddha","text":"The Leshan Giant Buddha is a 71-meter (233 ft) tall stone statue, built between 712 and 804 AD (during the Tang dynasty). It is carved out of a cliff face of Cretaceous red bed sandstones that lies at the confluence of the Min River and Dadu River in the southern part of Sichuan Province in China, near the city of Leshan.","built":"AD 803","height":71},
  "liberty-bell": {"article":"Independence Hall","text":"Independence Hall is a historic civic building in Philadelphia, Pennsylvania, where both the Declaration of Independence and the Constitution of the United States were debated and adopted by the Founding Fathers of the United States. The building, which is the centerpiece of Independence National Historical Park, was designated a World Heritage Site in 1979.","built":"1753","architects":["Edmund Woolley","Andrew Hamilton","William Strickland"]},
  "lijiang": {"article":"Old Town of Lijiang","text":"Dayan, commonly called the Old Town of Lijiang is the historical center of Lijiang City, in Yunnan, China. It is a UNESCO World Heritage Site."},
  "lima": {"article":"Plaza Mayor, Lima","text":"The Plaza Mayor, also known as the Plaza de Armas, is the main public square of the historic centre of the city of Lima, Peru. It dates back to the foundation of the city by Francisco Pizarro on 18 January 1535. Delimited by Carabaya, Junín, Huallaga, and Unión streets, it is surrounded by a number of major landmarks, including the Government Palace, the Metropolitan Cathedral, the Archbishop's Palace, the Municipal Palace, and the Palacio de la Unión."},
  "litomysl": {"article":"Litomyšl Castle","text":"Litomyšl Castle is one of the largest Renaissance castles in the Czech Republic. It is owned by the Czech state. It is located in the centre of the town of Litomyšl and was declared a UNESCO World Heritage Site in 1999. Litomyšl Castle is an outstanding example of the arcade castle, a type of building first developed in Italy and modified in the Czech lands to create an evolved form of special architectural quality.","architects":["Giovanni Baptista Aostalli de Sala"]},
  "little-mermaid": {"article":"The Little Mermaid (statue)","text":"The Little Mermaid is a bronze statue by Edvard Eriksen, depicting a mermaid becoming human. The sculpture is displayed on a rock by the waterside at the Langelinie promenade in Copenhagen, Denmark. It is 1.25 metres (4.1 ft) tall and weighs 175 kilograms (385 lb). Based on the 1837 fairy tale of the same name by Danish author Hans Christian Andersen, the small and unimposing statue is a Copenhagen icon and has been a major tourist attraction since its unveiling in 1913.","built":"1913"},
  "loango": {"article":"Loango National Park","text":"Loango National Park is a national park in western Gabon. It protects diverse coastal habitats including part of the 220-square-kilometre (85 sq mi) Iguéla Lagoon, the only significant example of a typical western African lagoon system that is protected within a national park. Situated between the Nkomi and Ndogo Lagoons, Loango National Park spans 1,550 km2 (600 sq mi) of savanna, beach, forest, and mangroves.","built":"2002"},
  "london-eye": {"article":"London Eye","text":"The London Eye, originally the Millennium Wheel, is a cantilevered observation wheel on the South Bank of the River Thames in London. It is the world's tallest cantilevered observation wheel, and the most popular paid tourist attraction in the United Kingdom with more than three million visitors annually. It has been featured numerous times in popular culture.","built":"1999","height":135,"architects":["Julia Barfield","David Marks","kut kutjop"]},
  "longmen": {"article":"Longmen Grottoes","text":"The Longmen Grottoes or Longmen Caves are some of the finest examples of Chinese Buddhist art. Housing tens of thousands of statues of Shakyamuni Buddha and his disciples, they are located 12 kilometres (7.5 mi) south of present-day Luoyang in Henan province, China. The images, many once painted, were carved as outside rock reliefs and inside artificial caves excavated from the limestone cliffs of the Xiangshan and Longmenshan, running east and west."},
  "lonja-valencia": {"article":"Lonja de la Seda","text":"The Lonja de la Seda or Llotja de la Seda (in Valencian), is a late Valencian Gothic-style civil building in Valencia, Spain. It is a principal tourist attraction in the city.","height":17,"architects":["Pere Compte"]},
  "loropeni": {"article":"Ruins of Loropéni","text":"The ruins of Loropéni are a medieval heritage site near the town of Loropéni in southern Burkina Faso. They were added to the UNESCO World Heritage List in 2009. These ruins were the country's first World Heritage site. The site, which spans 1.113 hectares (2.75 acres), includes an array of stone walls that comprised a medieval fortress, the best preserved of ten in the area.","built":"14th century"},
  "lorsch": {"article":"Lorsch Abbey","text":"Lorsch Abbey, otherwise the Imperial Abbey of Lorsch, is a former Imperial abbey in Lorsch, Germany, about 10 km (6.2 mi) east of Worms. It was one of the most important monasteries of the Carolingian Empire. Even in its ruined state, its remains are among the most important pre-Romanesque–Carolingian style buildings in Germany.","built":"AD 764"},
  "louvre": {"article":"Louvre","text":"The Louvre is a national art museum in Paris, France. It is located on the Right Bank of the Seine in the city's 1st arrondissement (district) and home to some of the most canonical works of Western art, including the Mona Lisa, Venus de Milo, and Winged Victory. The museum is housed in the Louvre Palace, originally built in the late 12th to 13th century under Philip II.","built":"1793","elevation":44,"architects":["Pierre Lescot","Claude Perrault","Charles Le Brun"]},
  "luang-prabang": {"article":"Luang Prabang","text":"Luang Prabang, historically known as Xieng Thong, and alternatively spelled Luang Phabang or Louangphabang, is the capital of Luang Prabang Province in north-central Laos. Its name, meaning “Royal Buddha Image,” derives from the Phra Bang, a statue symbolizing Lao sovereignty. Designated a UNESCO World Heritage Site in 1995, the city is recognized for blending Lao architecture, European colonial buildings, and over 30 Buddhist temples.","elevation":305},
  "lugo-walls": {"article":"Roman walls of Lugo","text":"The Roman walls of Lugo are the ancient Roman defensive walls of the Roman colonia of Lucus Augusti –present-day Lugo, Spain–, in the Roman province of Hispania Tarraconensis. Stretching 2,120 metres (6,960 ft), they were built in the third century AD to defend the ancient Roman town. The fortifications, still largely intact, were declared a UNESCO World Heritage Site in 2000 and are a popular tourist attraction.","height":8},
  "lumbini": {"article":"Maya Devi Temple, Lumbini","text":"Maya Devi Temple is an ancient Buddhist temple situated at the UNESCO World Heritage Site of Lumbini, Nepal. It is the main temple at Lumbini, a site traditionally considered the birthplace of Gautama Buddha. The temple stands adjacent to a sacred pool (known as pushkarani) and a sacred garden. The archaeological remains at the site were previously dated to the third-century BCE brick buildings constructed by Ashoka."},
  "lunenburg": {"article":"Lunenburg, Nova Scotia","text":"Lunenburg is a port town on the South Shore of Nova Scotia, Canada. Founded in 1753, the town was one of the first British attempts to settle Protestants in Nova Scotia. Historically, Lunenburg's economy relied on the offshore fishery, and today it hosts Canada's largest secondary fish-processing plant. The town experienced prosperity in the late 1800s, and many of its architectural gems date back to that era.","built":"1753"},
  "lviv": {"article":"Lviv","text":"Lviv is the sixth-largest city in Ukraine, as well as the largest city in the western part of the country, with a population of 723,403 (2025 estimate). It serves as the administrative center of Lviv Oblast and Lviv Raion, and is one of the main cultural centers of Ukraine. The city also hosts the administration of Lviv urban hromada.","built":"10th century","elevation":296},
  "maasai-mara": {"article":"Maasai Mara","text":"Maasai Mara, sometimes also spelt Masai Mara and locally known simply as the Mara, is a large national game reserve in Narok County, Kenya, contiguous with the Serengeti National Park in Tanzania. It is named in honour of the Maasai people, the ancestral inhabitants of the area, who migrated to the area from the Nile Basin.","built":"1961"},
  "macao": {"article":"Ruins of Saint Paul's","text":"The Ruins of Saint Paul's are the remnants of a 17th-century Catholic religious complex in Santo António, Macau. They include what was originally St. Paul's College and the Church of St. Paul (Igreja de São Paulo), also known as \"Mater Dei\", a 17th-century Portuguese church dedicated to Saint Paul the Apostle. Today, the ruins are one of Macau's best-known landmarks and were named one of the Seven Wonders of Portuguese Origin in the World by the Portuguese government in 2010.","built":"1835","architects":["Charles Spinola"]},
  "machu-picchu": {"article":"Machu Picchu","text":"Machu Picchu is a 15th-century Inca citadel located in the Eastern Cordillera of southern Peru on a mountain ridge at 2,430 meters (7,970 ft). It is situated in the Machupicchu District of Urubamba Province about 80 kilometers (50 miles) northwest of Cusco, above the Sacred Valley and along the Urubamba River, which forms a deep canyon with a subtropical mountain climate.","built":"1450","elevation":2430},
  "madara-rider": {"article":"Madara Rider","text":"The Madara Rider or Madara Horseman is a large early medieval rock relief carved on the Madara Plateau east of Shumen in northeastern Bulgaria, near the village of Madara. The monument is dated to the very late 7th or more often the very early 8th century, during the reign of the Bulgar Khan Tervel. In 1979, the monument was listed as a UNESCO World Heritage Site.","built":"8th century"},
  "madriu-valley": {"article":"Madriu-Perafita-Claror Valley","text":"The Madriu-Perafita-Claror Valley is a glacial valley in the southeast of Andorra. It covers an area of 42.47 km2, approximately 9% of the total area of Andorra, and is part of the second largest watershed basin in Andorra. The isolated valley is recognised as a haven for rare or endangered wildlife, and the undeveloped valley has recently been considered to be the \"spiritual heart\" of Andorra."},
  "mafra": {"article":"Palace of Mafra","text":"The Palace of Mafra, also known as the Palace-Convent of Mafra and the Royal Building of Mafra (Real Edifício de Mafra), is a monumental Baroque and Neoclassical palace-monastery located in Mafra, Portugal, some 28 kilometres from Lisbon. Construction began in 1717 under King John V of Portugal and was completed in 1755.","architects":["João Frederico Ludovice"]},
  "mahabodhi": {"article":"Mahabodhi Temple","text":"The Mahabodhi Temple (literally: \"Great Awakening Temple\") or the Mahābodhi Mahāvihāra, is a restored Buddhist temple in Bodh Gaya, Bihar, India, marking the location where the Buddha is said to have attained enlightenment, according to the Buddhist faith. A UNESCO World Heritage Site, the site contains a tree believed to be a descendant of the Bodhi Tree under which the Buddha gained enlightenment and which has been a major pilgrimage destination of Buddhists for over two thousand years.","height":55},
  "maho-beach": {"article":"Maho Beach","text":"Maho Beach is a beach on the Dutch side of the Caribbean island of Saint Martin, in the territory of Sint Maarten. It has become famous for being adjacent to the Princess Juliana International Airport and therefore is a popular site for tourists and plane watchers, who visit the beach to watch aircraft fly very low over the beach on final approach to land at the airport."},
  "maiden-tower": {"article":"Maiden Tower (Baku)","text":"The Maiden Tower is a 12th-century monument in the Old City, Baku, Azerbaijan. Along with the Shirvanshahs' Palace, dated to the 15th century, it forms a group of historic monuments listed in 2001 under the UNESCO World Heritage List of Historical Monuments as cultural property, Category III. It was built, like most buildings in the Old City, by the Shirvanshahs, and is one of Azerbaijan's most distinctive national emblems, and is thus featured on Azerbaijani currency notes and official letterheads.","built":"12th century","height":30},
  "maison-carree": {"article":"Maison carrée","text":"The Maison carrée is an ancient Roman temple in Nîmes, southern France; it is one of the best-preserved Roman temples to survive in the territory of the former Roman Empire. It is a mid-sized Augustan provincial temple of the Imperial cult, a caesareum. The Maison carrée inspired the neoclassical Église de la Madeleine in Paris, St."},
  "malabo-cathedral": {"article":"St. Elizabeth's Cathedral, Malabo","text":"St. Elizabeth's Cathedral is a Roman Catholic cathedral located on Independencia Avenue (Avenida de la Independencia) in the city of Malabo, the former capital of Equatorial Guinea, home of the Archdiocese of Malabo. It is considered the largest Christian church in the nation. It was named after St. Elizabeth of Hungary."},
  "malbork": {"article":"Malbork Castle","text":"The Castle of the Teutonic Order in Malbork, commonly known as Malbork Castle, is a Brick Gothic castle complex located in the town of Malbork, Poland, built in the 13th and significantly expanded in the 14th century. It is the largest castle in the world measured by land area and a UNESCO World Heritage Site. It was constructed by the Teutonic Order, a German Catholic religious order of crusaders, in the form of an Ordensburg fortress and named Marienburg in honour of Mary, mother of Jesus.","built":"1270"},
  "managaha": {"article":"Mañagaha","text":"Mañagaha (or Managaha) is a small islet which lies off the west coast of Saipan within its lagoon in the Northern Mariana Islands. Although it has no permanent residents, Mañagaha is popular among Saipan's tourists as a day-trip destination due to its wide sandy beaches and a number of marine activities including snorkeling, parasailing and jet skiing.","elevation":3},
  "manovo-gounda": {"article":"Manovo-Gounda St. Floris National Park","text":"Manovo-Gounda St Floris National Park is a national park and UNESCO World Heritage Site located in the Central African Republic prefecture Bamingui-Bangoran, near the Chad border. It was inscribed to the list of World Heritage Sites in 1988 as a result of the diversity of life present within it.","built":"1979","elevation":425},
  "maramures": {"article":"Wooden churches of Maramureș","text":"The wooden churches of Maramureș in the Maramureș region of northern Transylvania are a group of almost one hundred Orthodox churches, and occasionally Greek-Catholic ones, of different architectural solutions from different periods and areas. The Maramureș churches are high timber constructions with characteristic tall, slim bell towers at the western end of the building."},
  "marina-bay-sands": {"article":"Marina Bay Sands","text":"Marina Bay Sands (often colloquially shortened to 'MBS') is an integrated resort fronting Marina Bay in Singapore and a landmark of the city. At its opening in 2010, it was deemed the world's most expensive standalone casino property at S$8 billion (US$6.88 billion).","built":"2010","architects":["Moshe Safdie"]},
  "marrakesh": {"article":"Jemaa el-Fnaa","text":"Jemaa el-Fnaa, also Jemaa el-Fna, Djema el-Fna or Djemaa el-Fnaa, is a square and market place in the medina quarter (old city) of Marrakesh, Morocco. It remains the main square of Marrakesh, used by locals and tourists."},
  "masada": {"article":"Masada","text":"Masada is a mountain-top fortress complex in the Judaean Desert, overlooking the western shore of the Dead Sea in southeastern Israel. The fort, built in the first century BC, was constructed atop a natural plateau rising over 400 m (1,300 ft) above the surrounding terrain, 20 km (12 mi) east of modern Arad. The most significant remains at the site date to the reign of Herod the Great, King of Judaea under Roman administration c. 37–4 BC, who transformed Masada into a fortified desert refuge early in his rule."},
  "matera": {"article":"Sassi di Matera","text":"The Sassi di Matera are two districts (Sasso Caveoso and Sasso Barisano) of the Italian city of Matera, Basilicata, well-known for their ancient cave dwellings inhabited since the Paleolithic period. The \"Sassi\" have been described by Fodor's as \"one of the most unique landscapes in Europe\". Along with the park of the Rupestrian Churches, it was named a World Heritage Site by UNESCO in 1993."},
  "matobo-hills": {"article":"Matobo National Park","text":"The Matobo National Park forms the core of the Matobo or Matopos Hills, an area of granite kopjes and wooded valleys commencing some 35 kilometres (22 mi) south of Bulawayo, southern Zimbabwe. The hills were formed over 2 billion years ago with granite being forced to the surface; it has eroded to produce smooth \"whaleback dwalas\" and broken kopjes, strewn with boulders and interspersed with thickets of vegetation.","built":"1926","elevation":1302},
  "matterhorn": {"article":"Matterhorn","text":"The Matterhorn is a mountain of the Alps, straddling the main watershed and border between Switzerland and Italy. It is a large, near-symmetric pyramidal peak in the extended Monte Rosa area of the Pennine Alps, whose summit is 4,478 metres (14,692 ft) above sea level, making it one of the highest summits in the Alps and Europe.","elevation":4478},
  "maulbronn": {"article":"Maulbronn Monastery","text":"Maulbronn Monastery is a former Cistercian abbey and ecclesiastical state in the Holy Roman Empire located at Maulbronn, Baden-Württemberg. The monastery complex, one of the best-preserved in Europe, was named a UNESCO World Heritage Site in 1993. The monastery was founded in 1147 and experienced rapid economic and political growth in the 12th century, but then hardship in the late 13th century and the 14th century.","built":"1147"},
  "mazagan": {"article":"El Jadida","text":"El Jadida is a major port city on the Atlantic coast of Morocco. It is located in the province of El Jadida, Casablanca-Settat, 96 kilometres (60 mi) south of the city of Casablanca. It has a population of 237,564 as of 2024. The fortified city, built by the Portuguese at the beginning of the 16th century and named Mazagan (Mazagão in Portuguese), was given up by the Portuguese in 1769 and incorporated into Morocco."},
  "mbanza-kongo": {"article":"M'banza-Kongo","text":"Mbanza Kongo is the capital of Angola's northwestern Zaire Province with a population of 221,141 in 2024. Mbanza Kongo was the capital of the Kingdom of Kongo since its foundation before the arrival of the Portuguese in 1483 until the abolition of the kingdom in 1915, aside from a brief period of abandonment during civil wars in the 17th century.","elevation":408},
  "medina-azahara": {"article":"Madinat al-Zahra","text":"Madinat al-Zahra or Medina Azahara was a fortified palace-city on the western outskirts of Córdoba in present-day Spain. Its remains are a major archaeological site today. The city was built in the 10th century by Abd ar-Rahman III (912–961), a member of the Umayyad dynasty and the first caliph of al-Andalus. It served as the capital of the Caliphate of Córdoba and its center of government.","built":"10th century"},
  "megiddo": {"article":"Tel Megiddo","text":"Tel Megiddo is the site of the ancient city of Megiddo, the remains of which form a tell or archaeological mound, situated in northern Israel at the western edge of the Jezreel Valley. During the Bronze Age, Megiddo was an important Canaanite city-state, and in the Iron Age, it became a royal city in the Kingdom of Israel.","built":"7000 BC","height":82},
  "melaka": {"article":"Malacca","text":"Malacca, officially the Historic State of Malacca, is a state in Malaysia located in the southern region of the Malay Peninsula, facing the Strait of Malacca. The state is bordered by Negeri Sembilan to the north and west and Johor to the south and east. The exclave of Tanjung Tuan borders Negeri Sembilan to the north.","built":"1948"},
  "menin-gate": {"article":"Menin Gate","text":"The Menin Gate, officially the Menin Gate Memorial to the Missing, is a war memorial in Ypres, Belgium, dedicated to the British and Commonwealth soldiers who were killed in the Ypres Salient of World War I and whose graves are unknown. The memorial is located at the eastern exit of the town and marks the starting point for one of the main roads that led Allied soldiers to the front line.","built":"1927","architects":["Reginald Blomfield"]},
  "merida-theatre": {"article":"Roman Theatre (Mérida)","text":"The Roman Theatre of Mérida is a Roman theatre in the Roman colonia of Emerita Augusta –present-day Mérida, Spain–, capital of the Roman province of Lusitania. Its construction was promoted by the consul Vipsanius Agrippa and was built in 16–15 BCE. It was used for Roman theatrical performances during ancient Rome. Since 1933, it houses the International Festival of Classical Theatre of Mérida."},
  "meroe": {"article":"Pyramids of Meroë","text":"The Pyramids of Meroë are a large number of Nubian pyramids, encompassing three cemeteries near the ancient city of Meroë. They are located in Sudan, approximately 200 kilometres (120 mi) northeast of Khartoum, near the village of Bagrawiya. The three cemeteries (Bagrawiya North, South, and West) are spread across low hills covering roughly a quarter of a square kilometre."},
  "merv": {"article":"Merv","text":"Merv, also called the Merve Oasis, was a major Iranian city in Central Asia, located on the historical Silk Road, near today's Mary, Turkmenistan. Human settlements on the site of Merv existed from the 3rd millennium BC until the 18th century AD. It changed hands repeatedly throughout history. Under the Achaemenid Empire, it was the center of the satrapy of Margiana."},
  "mesa-verde": {"article":"Cliff Palace","text":"Cliff Palace is the largest cliff dwelling in North America. The structure built by the Ancestral Puebloans is located in Mesa Verde National Park in their former homeland region. The cliff dwelling and park are in Montezuma County, in the southwestern corner of Colorado, Southwestern United States."},
  "meteora": {"article":"Meteora","text":"Meteora is a rock formation in the regional unit of Trikala, in Thessaly, in northwestern Greece, hosting one of the most prominent complexes of Eastern Orthodox monasteries, viewed locally as second in importance only to Mount Athos. Their height is more than 20 metres (66 ft). Twenty-four monasteries were established atop the giant natural pillars and hill-like rounded boulders that dominate the local area, mainly from the second half of the 14th century under the local rule of self-proclaimed Emperor of Serbs, Greeks and Albanians, Simeon Uroš."},
  "milan-cathedral": {"article":"Milan Cathedral","text":"Milan Cathedral, or Metropolitan Cathedral-Basilica of the Nativity of Saint Mary, is the cathedral church of Milan, Lombardy, Italy. Dedicated to the Nativity of St. Mary (Santa Maria Nascente), it is the seat of the Archbishop of Milan, currently Archbishop Mario Delpini. The cathedral took nearly six centuries to complete, beginning construction in 1386 and its final details completed in 1965.","built":"1386","height":109,"architects":["Simone da Orsenigo"]},
  "milford-sound": {"article":"Milford Sound","text":"Milford Sound (Māori: Piopiotahi, officially gazetted as Milford Sound / Piopiotahi) is a fiord in the south west of New Zealand's South Island within Fiordland National Park, Piopiotahi (Milford Sound) Marine Reserve, and the Te Wahipounamu World Heritage site. It has been judged the world's top travel destination in an international survey (the 2008 Travelers' Choice Destinations Awards by TripAdvisor) and is acclaimed as New Zealand's most famous tourist destination."},
  "minaret-of-jam": {"article":"Minaret of Jam","text":"The Minaret of Jam is a UNESCO World Heritage Site in western Afghanistan. It is located in a remote and nearly inaccessible region of Shahrak District, Ghor Province, between the Jam and Hari Rivers. The 62 m (203 ft) or 65 m (213 ft) high minaret was built c. 1190, entirely of baked bricks, and is famous for its intricate brick, stucco and glazed tile decoration, which consists of alternating bands of Kufic and Naskhi calligraphy, geometric patterns, and verses from the Qur'an.","built":"1194","height":65},
  "ming-tombs": {"article":"Ming tombs","text":"The Ming tombs are a collection of mausoleums built by the emperors of the Ming dynasty of China. The tomb of the first Ming ruler, the Hongwu Emperor (r. 1368–1398), is located near his capital Nanjing. However, the majority of the Ming tombs are located in a cluster near Beijing and collectively known as the Thirteen Tombs of the Ming dynasty."},
  "mir-castle": {"article":"Mir Castle Complex","text":"The Mir Castle Complex is a historic fortified castle and a UNESCO World Heritage Site in Belarus. It is located in the town of Mir, in Karelichy District of Grodno Oblast, 29 kilometres (18 mi) north-west of another World Heritage site, Nesvizh Castle. Mir Castle Complex is 164 metres (538 ft) above sea level. Erected in the 16th century in the late Brick Gothic style, it is one of the few remaining architectural monuments of the former Polish–Lithuanian Commonwealth in contemporary Belarus."},
  "mireuksa": {"article":"Mireuksa","text":"Mireuksa was the largest Buddhist temple in the ancient Korean kingdom of Baekje. The temple was established in 602 by King Mu and is located 36.012083 N, 127.031028 E, modern Iksan, North Jeolla Province, South Korea. The site was excavated in 1980, disclosing many hitherto unknown facts about Baekje architecture. Mireuksaji Stone Pagoda is one of two extant Baekje pagodas.","built":"AD 602"},
  "mlilwane": {"article":"Mlilwane Wildlife Sanctuary","text":"Mlilwane Wildlife Sanctuary is Eswatini's oldest protected area, owned and managed by a non-profit trust."},
  "moai": {"article":"Ahu Tongariki","text":"Ahu Tongariki is the largest ahu on Easter Island (Rapa Nui). Its moais were toppled during the island's civil wars, and in the twentieth century the ahu was swept inland by a tsunami. It has since been restored and has fifteen moai, including one that weighs eighty-six tonnes, the heaviest ever erected on the island. Ahu Tongariki is one kilometer from Rano Raraku and Poike in the Hotu-iti area of Rapa Nui National Park."},
  "modena": {"article":"Modena Cathedral","text":"Modena Cathedral is a Roman Catholic cathedral in Modena, Italy, dedicated to the Assumption of the Virgin Mary and Saint Geminianus. Formerly the seat of the Diocese, later Archdiocese, of Modena, it has been since 1986 the archiepiscopal seat of the Archdiocese of Modena-Nonantola. Consecrated in 1184, it is an important Romanesque building in Europe, and along with its bell tower, the Torre della Ghirlandina, is designated as a World Heritage Site.","built":"11th century","architects":["Wiligelmo","Lanfranco"]},
  "mogao-caves": {"article":"Mogao Caves","text":"The Mogao Caves, also known as the Thousand Buddha Grottoes or Caves of the Thousand Buddhas, form a system of 500 temples 25 km (16 mi) southeast of the center of Dunhuang, an oasis located at a religious and cultural crossroads on the Silk Road, in Gansu province, China. The caves may also be known as the Dunhuang Caves; however, this term is also used as a collective term to include other Buddhist cave sites in and around the Dunhuang area, such as the Western Thousand Buddha Caves, Eastern Thousand Buddha Caves, Yulin Caves, and Five Temple Caves."},
  "mohenjo-daro": {"article":"Mohenjo-daro","text":"Mohenjo-daro is an archaeological site in the Larkana District of Sindh, Pakistan. Built c. 2500 BCE, it was one of the largest settlements of the ancient Indus Valley Civilisation, and one of the world's earliest major cities, contemporaneous with the civilisations of ancient Egypt, Mesopotamia, Minoa, and Norte Chico."},
  "monaco-palace": {"article":"Prince's Palace of Monaco","text":"The Prince's Palace of Monaco is the official residence of the Sovereign Prince of Monaco. Built in 1191 as a Genoese fortress, during its long and often dramatic history it has been bombarded and besieged by many foreign powers. Since the end of the 13th century, it has been the stronghold and home of the Grimaldi family who first captured it in 1297."},
  "mont-choungui": {"article":"Mont Choungui","text":"Mont Choungui is a distinctively conical volcanic mountain in the southern part of the French island of Mayotte, in the Comoro archipelago of the western Indian Ocean. It is the second highest point of the island at 593 m (1,946 ft), the highest being Mont Bénara, and is visible from far out at sea.","elevation":593},
  "mont-saint-michel": {"article":"Mont-Saint-Michel","text":"Mont-Saint-Michel is a tidal island and mainland commune in Normandy, France. The island lies approximately one kilometre (half a nautical mile) off France's north-western coast, at the mouth of the Couesnon River near Avranches and is 7 hectares (17 acres) in area. The mainland part of the commune is 393 hectares (971 acres) in area so that the total surface of the commune is 400 hectares (990 acres).","elevation":17},
  "monte-alban": {"article":"Monte Albán","text":"Monte Albán is a large pre-Columbian archaeological site in the Santa Cruz Xoxocotlán Municipality in the southern Mexican state of Oaxaca (17.043° N, 96.767°W). The site is located on a low mountainous range rising above the plain in the central section of the Valley of Oaxaca, where the latter's northern Etla, eastern Tlacolula, and southern Zimatlán and Ocotlán (or Valle Grande) branches meet."},
  "monticello": {"article":"Monticello","text":"Monticello was the primary residence and plantation of Thomas Jefferson, a Founding Father, author of the Declaration of Independence, and the third president of the United States. Jefferson began designing Monticello after inheriting land from his father at the age of 14. Located just outside Charlottesville, Virginia, in the Piedmont region, the plantation was originally 5,000 acres (20 km2), with Jefferson using the forced labor of enslaved black people for extensive cultivation of tobacco and mixed crops, later shifting from tobacco cultivation to wheat in response to changing markets.","architects":["Thomas Jefferson"]},
  "moraine-lake": {"article":"Moraine Lake","text":"Moraine Lake is a snow and glacially fed alpine lake in Banff National Park, 14 kilometres (8.7 mi) outside the village of Lake Louise, Alberta, Canada. It is situated in the Valley of the Ten Peaks, at an elevation of approximately 1,884 metres (6,181 ft). The lake has a surface area of 50 hectares (120 acres). The lake, being fed almost completely by snow-melt and glacial-melt, does not reach its crest until middle to late June.","elevation":1884},
  "morelia": {"article":"Morelia","text":"Morelia is the capital and most populous city of the Mexican state of Michoacán. Situated in the Guayangareo Valley in the north-central part of the state, it is the municipal seat of the municipality of Morelia. The main pre-Hispanic cultures here were the Purépecha and the Matlatzinca, but no major cities were founded in the valley during this time.","built":"1541","elevation":1920},
  "morne-trois-pitons": {"article":"Morne Trois Pitons National Park","text":"Morne Trois Pitons National Park is a national park in Dominica established in July 1975, the first to be legally established in the country. It became a World Heritage Site in 1997. The park is named after its highest mountain, Morne Trois Pitons, meaning \"mountain of three peaks.\" The park is an area of significant volcanic activity.","built":"1975"},
  "mostar": {"article":"Stari Most","text":"The Old Bridge (Serbo-Croatian: Stari most), also known as the Mostar Bridge, is a rebuilt 16th-century Ottoman bridge in the city of Mostar in Bosnia and Herzegovina. It crosses the river Neretva and connects the two parts of the city, which is named after the bridge keepers (mostari) who guarded the Old Bridge during the Ottoman era.","built":"1566","height":24},
  "mount-athos": {"article":"Mount Athos","text":"Mount Athos is a mountain on the Athos peninsula in northeastern Greece directly on the Aegean Sea. It is an important center of Eastern Orthodox monasticism. The mountain and most of the Athos peninsula are governed as an autonomous region in Greece by the monastic community of Mount Athos, which is ecclesiastically under the direct jurisdiction of the Ecumenical Patriarch of Constantinople.","elevation":2033},
  "mount-fuji": {"article":"Mount Fuji","text":"Mount Fuji is an active stratovolcano located on the Japanese island of Honshu, with a summit elevation of 3,776.24 m (12,389 ft 3 in). It is the highest mountain in Japan, the second-highest volcano on any Asian island (after Mount Kerinci on the Indonesian island of Sumatra), and the seventh-highest peak of an island on Earth.","elevation":3777},
  "mount-nemrut": {"article":"Mount Nemrut","text":"Mount Nemrut or Nemrud is a 2,150-metre-high (7,054 ft) mountain in southeastern Turkey, notable for the summit where a number of large statues are erected around what is assumed to be a royal tomb from the 1st century BC. It is one of the highest peaks in the eastern Taurus Mountains. It was designated a UNESCO World Heritage Site in 1987.","elevation":2150},
  "mount-pelee": {"article":"Mount Pelée","text":"Mount Pelée or Mont Pelée is an active stratovolcano at the northern end of Martinique, an island and French overseas department in the Lesser Antilles Volcanic Arc of the Caribbean. Its volcanic cone is composed of stratified layers of hardened ash and solidified lava. Its most recent eruption was in 1932. The stratovolcano's 1902 eruption destroyed the town of Saint-Pierre, killing 29,000 to 30,000 people in the space of a few minutes, in the worst volcanic disaster of the 20th century.","elevation":1397},
  "mount-rushmore": {"article":"Mount Rushmore","text":"The Mount Rushmore National Memorial is a national memorial featuring a colossal sculpture carved into the granite face of Mount Rushmore in the Black Hills, about 2 mi (3 km) southwest of Keystone, South Dakota, United States. The sculptor, Gutzon Borglum, named it the Shrine of Democracy, and oversaw the execution from 1927 to 1941 with the help of his son, Lincoln Borglum.","elevation":1745},
  "mozambique-island": {"article":"Island of Mozambique","text":"The Island of Mozambique lies off northern Mozambique, between the Mozambique Channel and Mossuril Bay, and is part of Nampula Province. Prior to 1898, it was the capital of colonial Portuguese East Africa. With its rich history and sandy beaches, the Island of Mozambique is a UNESCO World Heritage Site and one of Mozambique's fastest-growing tourist destinations."},
  "mtskheta": {"article":"Jvari Monastery","text":"The name of this monastery translated as the \"Monastery of the Cross\". For other monasteries named after the cross, see Monastery of the Cross (disambiguation). Jvari Monastery is a sixth-century Georgian Orthodox monastery near Mtskheta, eastern Georgia. Jvari is a rare case of an Early Medieval Georgian church that has survived to the present day almost unchanged.","built":"6th century"},
  "muhammad-ali-mosque": {"article":"Muhammad Ali Mosque","text":"The Muhammad Ali Mosque, also known as the Mosque of Muhammad Ali, is a mosque located in the Citadel of Cairo, Egypt. It was commissioned by Muhammad Ali Pasha and built between 1832 and 1857. Overlooking the city, it is one of the most visible mosques and landmarks in the skyline of Cairo. Unlike the traditional Cairene architecture that preceded it, the mosque was built in an entirely Ottoman and European-influenced style, further setting it apart from other monuments.","built":"1848","height":82},
  "mulafossur": {"article":"Gásadalur","text":"Gásadalur is a village located on the west side of Vágar, Faroe Islands, and enjoys a panoramic view over to the island of Mykines. Gásadalur is located on the edge of Mykinesfjørður, surrounded by the highest mountains on Vágar. Árnafjall towers to a height of 722 metres (2,369 ft) to the north, and Eysturtindur to the east is 715 metres (2,346 ft)."},
  "muliaage-palace": {"article":"Muliaage","text":"The Muliaage palace or Muliaage is the official residence of the president of the Maldives. Muliaage, situated in Henveiru within the historic center of Malé, is located on Medhuziyaarai Magu, near significant landmarks, the Medhu Ziyaaraiy, the Malé Friday Mosque, and the Munnaru. The residence was designed by Ahmed Dhoshimeyna Kilegefan, father of Mohamed Amin Didi in 1913, at the request of King Muhammad Shamsuddine III, for his son and heir, Hassan Izzuddine, Crown Prince of the Maldives.","built":"1919"},
  "museum-island": {"article":"Museum Island","text":"The Museum Island is a museum complex on the northern part of Spree Island in the historic heart of Berlin, Germany. It is one of the capital's most visited sights and one of the most important museum sites in Europe. Originally built from 1830 to 1930, initially by order of the Prussian Kings, according to plans by five architects, the Museum Island was designated a UNESCO World Heritage Site in 1999 because of its testimony to the architectural and cultural development of museums in the 19th and 20th centuries.","elevation":39},
  "muskau": {"article":"Muskau Park","text":"Muskau Park is a landscape park in the Upper Lusatia region of Germany and Poland. It is the largest and one of the most famous English gardens in Central Europe, stretching along both sides of the German–Polish border on the Lusatian Neisse. The park was laid out from 1815 onwards at the behest of Prince Hermann von Pückler-Muskau (1785–1871), centered on his Schloss Muskau residence.","built":"1815"},
  "mustair": {"article":"Saint John Abbey, Müstair","text":"The Abbey of Saint John is an early medieval Benedictine monastery in the Swiss municipality of Val Müstair, in the Canton of Graubünden. By reason of its exceptionally well-preserved heritage of Carolingian art, it has been a UNESCO World Heritage Site since 1983.","built":"8th century"},
  "my-son": {"article":"Mỹ Sơn Sanctuary","text":"Mỹ Sơn is a cluster of abandoned and partially ruined Shaiva Hindu temples in central Vietnam, constructed between the 4th and the 13th century by the Kings of Champa, an Indianized kingdom of the Cham people. The temples are dedicated to the veneration of God in accordance with Shaivism, wherein God is named Shiva, or The Auspicious One."},
  "mycenae": {"article":"Mycenae","text":"Mycenae is an archaeological site near Mykines in Argolis, north-eastern Peloponnese, Greece. It is located about 120 kilometres (75 miles) south-west of Athens; 11 kilometres (7 miles) north of Argos; and 48 kilometres (30 miles) south of Corinth. The site is 19 kilometres (12 miles) inland from the Saronic Gulf and built upon a hill rising 274 metres (899 feet) above sea level."},
  "mystras": {"article":"Mystras","text":"Mystras or Mistras, also known in the Chronicle of the Morea as Myzethras or Myzithras, is a fortified town and a former municipality in Laconia, Peloponnese, Greece. Situated in the Taygetus range, above ancient Sparta, and below a \"Frankish\" castle, it served as the capital of the Byzantine Despotate of the Morea in the 14th and 15th centuries, experiencing a period of prosperity and cultural flowering during the Palaeologan Renaissance, attracting artists, architects, and intellectuals such as Gemistos Plethon.","elevation":310},
  "mzab-valley": {"article":"M'zab","text":"The M'zab, or Mzab, is a natural region of the northern Sahara Desert in Ghardaïa Province, Algeria. It is located 600 km (370 mi) south of Algiers and has approximately 360,000 inhabitants (2005 estimate)."},
  "nachi": {"article":"Nachi Falls","text":"Nachi Falls in Nachikatsuura, Wakayama Prefecture, Japan, is one of the best-known waterfalls in Japan. With a drop of 133 metres (436 ft) and 13 metres (43 ft) wide, it is the tallest waterfall with a single uninterrupted drop in Japan (although Japan also disputes Russia's right to Iturup Island, which has the 141 m (463 ft) high Ilya Muromets Waterfall); however, the tallest Japanese waterfalls with multiple drops are Hannoki Falls, at 497 m (1,631 ft) (seasonal), and Shōmyō Falls, at 350 m (1,150 ft) (year round).","height":133},
  "nakhon-si-thammarat": {"article":"Wat Phra Mahathat","text":"Wat Phra Mahathat Woramahawihan is the main Buddhist temple (wat) of Nakhon Si Thammarat Province in southern Thailand, a crucial trade crossroad between the Indian and Pacific Oceans. Founded in the 8th century, where a Hindu shrine once stood around 5th–8th centuries, the monastery has been a regional religious centre ever since."},
  "nalanda": {"article":"Nalanda mahavihara","text":"Nalanda was a renowned Buddhist mahavihara (great monastery) in medieval Magadha (modern-day Bihar), eastern India. Widely considered to be among the greatest centres of learning in the ancient world and often referred to as \"the world's first residential university\", it was located near the city of Rajagriha (now Rajgir), roughly 90 kilometres (56 mi) southeast of Pataliputra (now Patna)."},
  "namhansanseong": {"article":"Namhansanseong","text":"Namhansanseong is a historic Korean fortress city in Gwangju, Gyeonggi Province, South Korea. A UNESCO World Heritage Site, the fortress lies atop the mountain Namhansan and stretches 12 km in length. It served as an emergency capital city during the 1392–1910 Joseon period. The design is based on fortress architecture of East Asia, embodying aspects of four historical cultural styles: Joseon of Korea, the Azuchi-Momoyama Period of Japan, and Ming and Qing China."},
  "nan-madol": {"article":"Nan Madol","text":"Nan Madol is an archaeological site adjacent to the eastern shore of the island of Pohnpei, now part of the Madolenihmw district of Pohnpei state in the Federated States of Micronesia in the western Pacific Ocean. Nan Madol was the capital of the Saudeleur dynasty until about 1628. The city, constructed in a lagoon, consists of a series of small artificial islands linked by a network of canals."},
  "naqsh-e-jahan": {"article":"Naqsh-e Jahan Square","text":"The Naqsh-e Jahan Square, also known as the Shah Square prior to 1979, and sometimes known as the Imam Square, is a square situated at the center of Isfahan, Iran. Constructed between 1598 and 1629, it is now an important historical site, and one of UNESCO's World Heritage Sites. It is 160 metres (520 ft) wide by 560 metres (1,840 ft) long – an area of 89,600 square metres (964,000 sq ft).","built":"1591","elevation":1570},
  "nara": {"article":"Tōdai-ji","text":"Tōdai-ji is a Buddhist temple complex that was once one of the powerful Seven Great Temples, located in the city of Nara, Japan. The construction of the temple was an attempt to imitate Chinese temples from the much-admired Tang dynasty. Though it was originally founded in the year 738 CE, Tōdai-ji was not opened until the year 752 CE.","built":"AD 752"},
  "naumburg": {"article":"Naumburg Cathedral","text":"Naumburg Cathedral, located in Naumburg, Germany, is the former cathedral of the Bishopric of Naumburg-Zeitz. The church building, most of which dates back to the 13th century, is a renowned landmark of the German late Romanesque and was recognised as a UNESCO World Heritage Site in 2018. The west choir with the famous donor portrait statues of the twelve cathedral founders (Stifterfiguren) and the Lettner, works of the Naumburg Master, is one of the most significant early Gothic monuments.","built":"13th century","architects":["Johann Gottfried Werner"]},
  "nazca-lines": {"article":"Nazca lines","text":"The Nazca lines are a group of geoglyphs made in the soil of the Nazca Desert in southern Peru. The area was designated a UNESCO World Heritage Site in 1994. The lines were created between 500 BC and 500 AD by people making depressions or shallow incisions in the desert floor, removing pebbles and leaving different-colored dirt exposed.","built":"200 BC"},
  "nelsons-dockyard": {"article":"Nelson's Dockyard","text":"Nelson's Dockyard is a cultural heritage site and marina in English Harbour, located in Saint Paul on the Caribbean island of Antigua, in Antigua and Barbuda. It is the only continuously working Georgian era dockyard in the world. It was built in the early 18th century and abandoned by the British Royal Navy in 1889. The dockyard is named after Admiral Horatio Nelson, who lived in the Royal Navy Dockyard from 1784 through 1787."},
  "nerl-church": {"article":"Church of the Intercession on the Nerl","text":"The Church of the Intercession on the Nerl is a Russian Orthodox church and a symbol of medieval Russia. It is a monument of the Vladimir-Suzdal school of architecture. It is one of the oldest and best-preserved examples of a single-domed church building in Russia, a type that was widespread in Russian architecture. Dedicated to the Intercession of the Theotokos, the church is situated at the confluence of the Nerl and the Klyazma in Bogolyubovo, 13 km (8.1 mi) north-east of the medieval princely seat of Vladimir.","built":"12th century"},
  "nessebar": {"article":"Nesebar","text":"Nesebar is an ancient city and one of the major seaside resorts on the Bulgarian Black Sea Coast, located in Burgas Province. It is the administrative centre of the homonymous Nesebar Municipality. Often referred to as the \"Pearl of the Black Sea\", Nesebar is a rich city-museum defined by more than three millennia of ever-changing history.","elevation":30},
  "nesvizh-castle": {"article":"Nesvizh Castle","text":"Nesvizh Castle or Nyasvizh Castle is a residential castle of the Radziwiłł family in Nyasvizh (Nesvizh), Belarus. It is 183 metres (600 ft) above sea level. Built originally in the 16th and 17th centuries, throughout its history the site has been sacked, damaged and abandoned repeatedly, and has seen multiple different uses including as a storehouse.","built":"1583","elevation":188,"architects":["Giovanni Maria Bernardoni"]},
  "neuschwanstein": {"article":"Neuschwanstein Castle","text":"Neuschwanstein Castle is a 19th-century historicist palace on a rugged hill of the foothills of the Alps in the very south of Germany, near the border with Austria. It is located in the Swabia region of Bavaria, in the municipality of Schwangau, above the incorporated village of Hohenschwangau, which is also the location of Hohenschwangau Castle.","built":"1869","height":65,"architects":["Christian Jank","Eduard Riedel","Georg von Dollmann"]},
  "new-lanark": {"article":"New Lanark","text":"New Lanark is a village on the River Clyde, approximately 1.4 miles (2.3 kilometres) from Lanark, in Lanarkshire, and some 25 miles (40 km) southeast of Glasgow, Scotland. It was founded in 1785 and opened in 1786 by David Dale, who built cotton mills and housing for the mill workers. Dale built the mills there in a brief partnership with the English inventor and entrepreneur Richard Arkwright to take advantage of the water power provided by one of the waterfalls on the River Clyde."},
  "newgrange": {"article":"Newgrange","text":"Newgrange is a prehistoric monument in County Meath in Ireland, placed on a rise overlooking the River Boyne, eight kilometres (five miles) west of the town of Drogheda. It is an exceptionally grand passage tomb built during the Neolithic Period, around 3100 BC, making it older than Stonehenge and the Egyptian pyramids."},
  "ngorongoro": {"article":"Ngorongoro Conservation Area","text":"Ngorongoro Conservation Area is a protected area and a UNESCO World Heritage Site located in Ngorongoro District, 180 km (110 mi) west of Arusha City in Arusha Region, within the Crater Highlands geological area of northeastern Tanzania. The area is named after Ngorongoro Crater, a large volcanic caldera within the area.","built":"1959"},
  "nice": {"article":"Hotel Negresco","text":"The Hotel Negresco is a luxury hotel and site of the restaurant Le Chantecler, located on the Promenade des Anglais on the Baie des Anges in Nice, France. It was named after Henri Negresco (1868–1920), who had the palatial hotel constructed, and who opened it in 1912.","built":"1913","architects":["Édouard Niermans"]},
  "nikko": {"article":"Nikkō Tōshō-gū","text":"Nikkō Tōshō-gū is a Tōshō-gū Shinto shrine located in Nikkō, Tochigi Prefecture, Japan. Together with Futarasan Shrine and Rinnō-ji, it forms the Shrines and Temples of Nikkō UNESCO World Heritage Site, with 42 structures of the shrine included in the nomination. Five of them are designated as National Treasures of Japan, and three more as Important Cultural Properties.","built":"1617"},
  "noto": {"article":"Noto Cathedral","text":"Noto Cathedral is a Roman Catholic cathedral in Noto in Sicily, Italy. Its construction, in the style of the Sicilian Baroque, began in the early 18th century and was completed in 1776. It is dedicated to Saint Nicholas of Myra, and has been the cathedral of the Diocese of Noto since the diocese's establishment in 1844.","built":"1776","architects":["Rosario Gagliardi"]},
  "notre-dame": {"article":"Notre-Dame de Paris","text":"Notre-Dame de Paris, often referred to simply as Notre-Dame, is a medieval Catholic cathedral and basilica on the Île de la Cité (an island in the River Seine), in the 4th arrondissement of Paris, France. It is the cathedral church of the Roman Catholic Archdiocese of Paris. The cathedral, dedicated to the Virgin Mary (\"Our Lady\"), is considered one of the finest examples of French Gothic architecture.","built":"1163","height":69,"architects":["Jean de Chelles","Pierre de Montreuil","Pierre de Chelles"]},
  "novgorod": {"article":"Historic Monuments of Novgorod and Surroundings","text":"The Historic Monuments of Novgorod and Surroundings is a composite World Heritage Site which includes a number of medieval monuments in and around Veliky Novgorod, Russia. The site was inscribed in 1992."},
  "novodevichy": {"article":"Novodevichy Convent","text":"Novodevichy Convent, also known as Bogoroditse-Smolensky Monastery, is probably the best-known cloister of Moscow. Its name, sometimes translated as the New Maidens' Monastery, was devised to differ from the Old Maidens' Monastery within the Moscow Kremlin. The convent was founded by Grand Duke Vasily III on May 13, 1524 in honor of the Smolensk Icon of the Mother of God \"Hodegetria\" - the main shrine of Smolensk, in gratitude for the capture of Smolensk in 1514.","built":"1524"},
  "odesa": {"article":"Historic Centre of Odesa","text":"The Historic Centre of Odesa, Historical City Centre of Odesa, or Centre of Odesa is a city centre and World Heritage Site in Odesa, Ukraine. It was listed in 2023, and currently, it is on the list of World Heritage Sites in Danger because of the Russo-Ukrainian war."},
  "odzala": {"article":"Odzala-Kokoua National Park","text":"Odzala-Kokoua National Park (or Odzala National Park) is a national park in the Republic of the Congo. The park was first protected in 1935, declared a biosphere reserve in 1977, and granted official designation by presidential decree in 2001. Odzala-Kokoua has approximately 100 mammal species, and one of the continent's most diverse primate populations.","built":"1935","elevation":555},
  "ohrid": {"article":"Ohrid","text":"Ohrid is a city in North Macedonia and is the seat of the Ohrid Municipality. It is the largest city on Lake Ohrid and the eighth-largest city in the country, with it recording a population of over 38,000 inhabitants as of 2021. Ohrid is known for once having 365 churches, one for each day of the year, and has been referred to as the \"Jerusalem of the Balkans\".","elevation":700},
  "okavango-delta": {"article":"Okavango Delta","text":"The Okavango Delta or Okavango Grassland is a vast inland delta in Botswana formed where the Okavango River reaches a tectonic trough at an elevation of 930–1,000 m (3,050–3,280 ft) in the central part of the endorheic basin of the Kalahari Desert. It is a UNESCO World Heritage Site as one of the few interior delta systems that do not flow into a sea or ocean, with a wetland system that is largely intact."},
  "old-faithful": {"article":"Old Faithful","text":"Old Faithful is a cone geyser in Yellowstone National Park in Wyoming, United States. It was named in 1870 during the Washburn–Langford–Doane Expedition and was the first geyser in the park to be named. It is a highly predictable geothermal feature, erupting on average every 92 minutes, with the period between eruptions ranging from as short as 35 minutes to as long as 120 minutes."},
  "old-havana": {"article":"Old Havana","text":"Old Havana is the city-center (downtown) and one of the 15 municipalities (or boroughs) forming Havana, Cuba. It has the second highest population density in the city and contains the core of the original city of Havana. The positions of the original Walls of Havana are the modern boundaries of Old Havana. In 1982, Old Havana was inscribed in the UNESCO World Heritage List, because of its unique Baroque and neoclassical architecture, its fortifications, and its historical importance as a stop on the route to the New World.","elevation":11},
  "old-rauma": {"article":"Old Rauma","text":"Old Rauma is the wooden centre of the town of Rauma, Finland. It was inscribed on the UNESCO World Heritage List in 1991 because of its unique wooden architecture and its well-preserved medieval town layout. It is one of the only medieval towns in Finland. The area of Old Rauma is about 0.3 km2, with approximately six hundred buildings (counting both proper houses and smaller buildings like sheds) and about 800 people living in the area."},
  "olympia": {"article":"Olympia, Greece","text":"Olympia, officially Archaia Olympia, is a small town in Elis on the Peloponnese peninsula in Greece, famous for the nearby archaeological site of the same name. The site was a major Panhellenic religious sanctuary of ancient Greece, where the ancient Olympic Games were held every four years throughout classical antiquity, from the 8th century BC to the 4th century AD.","elevation":69},
  "omar-ali-saifuddien-mosque": {"article":"Omar Ali Saifuddien Mosque","text":"The Omar Ali Saifuddien Mosque. or unofficially Sultan Omar Ali Saifuddin Mosque (abbreviated as the SOAS Mosque), is a mosque in Bandar Seri Begawan, the capital of Brunei. It is one of the two state mosques (masjid negara), the other being Jame' Asr Hassanil Bolkiah Mosque. One of the biggest and most striking mosques in the Far East, it was completed in 1958 at a cost of US$5 million, built by the eponymous Omar Ali Saifuddien III, the 28th Sultan of Brunei.","built":"1954","height":52},
  "orange-theatre": {"article":"Roman Theatre of Orange","text":"The Roman Theatre of Orange is a Roman theatre in Orange, Vaucluse, France. It was built early in the 1st century AD. The structure is owned by the municipality of Orange and is the home of the summer opera festival, the Chorégies d'Orange. It is one of the best preserved of all Roman theatres, and served the Roman colony of Arausio (or, more specifically, Colonia Julia Firma Secundanorum Arausio: \"the Julian colony of Arausio established by the soldiers of the second legion\") which was founded in 40 BC.","built":"1st century BC","height":37},
  "orheiul-vechi": {"article":"Old Orhei","text":"Old Orhei is a Moldovan historical and archaeological complex located in Trebujeni, which is approximately 60 kilometres (37 mi) north-east of Chișinău on the Răut River in the Republic of Moldova."},
  "orkhon-valley": {"article":"Orkhon Valley","text":"The Orkhon Valley Cultural Landscape sprawls along the banks of the Orkhon River in Central Mongolia, some 320 km west from the capital Ulaanbaatar. It was inscribed by UNESCO in the World Heritage List as representing the development of nomadic pastoral traditions spanning more than two millennia."},
  "oura-church": {"article":"Oura Church","text":"The Oura Church or Oura Cathedral, officially the Basilica of the Twenty-Six Holy Martyrs of Japan, is a Catholic minor basilica and co-cathedral in Nagasaki, Japan, built soon after the end of the Japanese government's Seclusion Policy in 1853. It is named after the 26 Japanese Martyrs. For many years it was the only Western-style building declared a national treasure, and is said to be the oldest Christian church in Japan.","built":"1863","architects":["Louis-Theodore Furet"]},
  "ouro-preto": {"article":"Church of Saint Francis of Assisi (Ouro Preto)","text":"The Church of Saint Francis of Assisi is a Rococo Catholic church in Ouro Preto, Brazil. Its erection began in 1766 after a design by the Brazilian architect and sculptor Antônio Francisco Lisboa, otherwise known as Aleijadinho. Lisboa designed both the structure of the church and the carved decorations on the interior, which were only finished towards the end of the 19th century.","built":"1771","architects":["Aleijadinho"]},
  "padre-tembleque": {"article":"Aqueduct of Padre Tembleque","text":"The Aqueduct of Padre Tembleque, or Tembleque Aqueduct, is a Mexican aqueduct located between the towns of Zempoala, Hidalgo, and Otumba in the State of Mexico. The structure takes its name from a Spanish friar called Francisco de Tembleque.","height":39},
  "paharpur": {"article":"Somapura Mahavihara","text":"Somapura Mahavihara, also known as Paharpur Buddhist Vihara, is a major Mahayana and Vajrayana Buddhist monastery (mahavihara) in Paharpur, Badalgachhi, Naogaon, Bangladesh. It is among the best known Buddhist viharas in the Indian subcontinent and one of the most important archaeological sites in the country. It was designated as a UNESCO World Heritage Site in 1985."},
  "palau-de-la-musica": {"article":"Palau de la Música Catalana","text":"Palau de la Música Catalana is a concert hall in Barcelona, Catalonia, Spain. Designed in the Catalan modernista style by the architect Lluís Domènech i Montaner, it was built between 1905 and 1908 for Orfeó Català, a choral society founded in 1891 that was a leading force in the Catalan cultural movement that came to be known as the Renaixença (Catalan Rebirth).","built":"1908","architects":["Lluís Domènech i Montaner"]},
  "palenque": {"article":"Palenque","text":"Palenque, also anciently known in the Itzaʼ language as Lakamha (\"big water\" or \"big waters\"), was a Maya city-state in southern Mexico that perished in the 8th century. The Palenque ruins date from ca. 226 BC to ca. 799 AD. After its decline, it was overgrown by the jungle of cedar, mahogany, and sapodilla trees, but has since been excavated and restored."},
  "palermo": {"article":"Palermo Cathedral","text":"Palermo Cathedral is the cathedral church of the Roman Catholic Archdiocese of Palermo, located in Palermo, Sicily, southern Italy. It is dedicated to the Assumption of the Virgin Mary. As an architectural complex, it is characterized by the presence of different styles, due to a long history of additions, alterations and restorations, the last of which occurred in the 18th century.","built":"1185","elevation":40},
  "palmyra": {"article":"Palmyra","text":"Palmyra is an ancient city in central Syria. Located in the eastern part of the Levant, archaeological finds around the site date back to the Neolithic period, and documents first mention the city in the early second millennium BC. Palmyra changed hands on a number of occasions between different empires before becoming a subject of the Roman Empire in the first century AD."},
  "pampulha": {"article":"Pampulha Modern Ensemble","text":"The Pampulha Modern Ensemble is an urban project in Belo Horizonte, Minas Gerais state of Brazil. It was designed around an artificial lake, Lake Pampulha, in the district of Pampulha and includes a casino (currently Pampulha Art Museum), a ballroom (Casa do Baile), the Golf Yacht Club (currently Iate Tênis Clube) and the Church of Saint Francis of Assisi.","built":"1943","architects":["Oscar Niemeyer"]},
  "pamukkale": {"article":"Pamukkale","text":"Pamukkale, meaning \"cotton castle\" in Turkish, is a natural site in Denizli Province in southwestern Turkey. The area is famous for a carbonate mineral left by the flowing of thermal spring water. It is located in Turkey's Inner Aegean region, in the River Menderes valley, which has a temperate climate for most of the year."},
  "panama-canal": {"article":"Panama Canal","text":"The Panama Canal is an artificial 82-kilometer (51-mile) waterway in Panama that connects the Caribbean Sea in the Atlantic Ocean with the Pacific Ocean. It cuts across the narrowest point of the Isthmus of Panama and is a conduit for maritime trade between the Atlantic Ocean and the Pacific Ocean. Locks at each end lift ships up to Gatun Lake, an artificial fresh water lake 26 meters (85 ft) above sea level, created by damming the Chagres River and Lake Alajuela to reduce the amount of excavation work required for the canal.","built":"1914","elevation":26},
  "pannonhalma": {"article":"Pannonhalma Archabbey","text":"The Benedictine Pannonhalma Archabbey or Territorial Abbey of Saint Martin on Mount Pannonhalma (lat. Archiabbatia or Abbatia Territorialis Sancti Martini in Monte Pannoniae) is a medieval building in Pannonhalma and one of the oldest historical monuments in Hungary. Founded in 996, it is located near the town, on top of a hill (282 m).","built":"10th century"},
  "pantheon": {"article":"Pantheon, Rome","text":"The Pantheon is an ancient Polytheist temple in Rome, Italy, originally built under Roman emperor Augustus (27 BC–AD 14) and reconstructed under Hadrian (117–138). Since AD 609, it has served as the Roman Catholic Basilica of Saint Mary and the Holy Martyrs with the special Pontifical privilege of immemorial status. The Pantheon was built on the site of an earlier temple, which had been commissioned by Marcus Vipsanius Agrippa during the reign of Augustus.","built":"2nd century","height":43,"architects":["Apollodorus of Damascus"]},
  "paoay-church": {"article":"San Agustin Church (Manila)","text":"The Archdiocesan Shrine of Our Lady of Consolation and Cincture, also known as the San Agustin Church and Immaculate Conception Parish, is a Roman Catholic church under the auspices of the Order of Saint Augustine located inside the historic walled city of Intramuros in Manila, Philippines. Completed in 1607, it is the oldest stone church in the country.","built":"1571"},
  "paphos": {"article":"Nea Paphos (ancient city)","text":"Nea Paphos (\"New Paphos\") was an ancient city in Cyprus founded in the late 4th century BC. It was built as a successor to Palaepaphos (\"Old Paphos\") in modern Kouklia, which was the commercial, administrative, and religious center of the Cypriot city-state of Paphos. Nea Paphos was the island's capital under much of its Ptolemaic and Roman administrations, and like its predecessor Palaepaphos became a major maritime trading hub in the eastern Mediterranean.","built":"1962"},
  "paquime": {"article":"Casas Grandes","text":"Casas Grandes is a prehistoric archaeological site in the northern Mexican state of Chihuahua. Construction of the site is attributed to the Mogollon culture. Casas Grandes has been designated a UNESCO World Heritage Site under the purview of INAH and a \"Pueblo Mágico\" since 2015. Casas Grandes is one of the largest and most complex Mogollon culture sites in the region.","elevation":1476},
  "paramaribo": {"article":"Paramaribo","text":"Paramaribo, locally nicknamed Foto, is the capital and largest city of Suriname, located on the banks of the Suriname River in the Paramaribo District. Paramaribo has a population of roughly 252,581 people as of the 2025 estimate, almost half of Suriname's population. The historic inner city of Paramaribo has been a UNESCO World Heritage Site since 2002.","built":"1613","elevation":3},
  "paraty": {"article":"Paraty","text":"Paraty is a Brazilian municipality on the southern coast of the state of Rio de Janeiro. It is 258 kilometres from the state capital, the city of Rio de Janeiro. Alongside the Atlantic Ocean, the municipal area has an average altitude of just five metres above sea level. It covers 924.295 square kilometres and has an estimated population of 47,668, giving a population density of 48.95 inhabitants per square kilometre.","built":"1597","elevation":5},
  "park-guell": {"article":"Park Güell","text":"Park Güell is a complex of parks and gardens in Barcelona with architectural elements, located in the La Salut neighborhood of the Gràcia district in Barcelona, Catalonia, Spain. It is situated on the southern slope of the Turó del Carmel hill, part of the Collserola mountain range, overlooking the city. The separate Parc del Carmel lies on the northern side of the same hill.","built":"1926","architects":["Antoni Gaudí"]},
  "parthenon": {"article":"Parthenon","text":"The Parthenon is a former temple on the Athenian Acropolis, Greece, that was dedicated to the goddess Athena. Its decorative sculptures are considered some of the high points of classical Greek art, and the Parthenon is considered an enduring symbol of ancient Greece, Western civilisation, and democracy. The Parthenon was built in the 5th century BC in thanksgiving for the Greek victory over the Persian invaders during the Greco-Persian Wars.","built":"5th century BC","height":14,"architects":["Ictinus","Callicrates","Phidias"]},
  "pasargadae": {"article":"Tomb of Cyrus the Great","text":"The tomb of Cyrus the Great is located in Pasargadae, which was the first capital city of his Achaemenid Empire and is now an archaeological site in the Fars province of Iran. The mausoleum is a significant historical example of earthquake engineering as it is said to be the oldest base-isolated structure in the world, allowing it great resilience against seismic hazards.","built":"530 BC","height":11},
  "patmos": {"article":"Monastery of Saint John the Theologian","text":"The Monastery of Saint John the Theologian is a Greek Orthodox monastery founded in 1088 in Chora on the island of Patmos. It is named after St John of Patmos, the author of the Christian Book of Revelation who, according to the text, lived on the island when visions of the apocalypse came to him. Since its founding, the monastery has been a pilgrimage site and a place of Greek Orthodox learning and worship.","built":"11th century"},
  "pattadakal": {"article":"Pattadakal","text":"Pattadakal (Pattadakallu), also called Raktapura, is a complex of 7th and 8th century CE Hindu and Jain temples in northern Karnataka, India. Located on the west bank of the Malaprabha River in Bagalkot district, this UNESCO World Heritage Site is 23 kilometres (14 mi) from Badami and about 9.7 kilometres (6 mi) from Aihole, both of which are historically significant centres of Chalukya monuments.","built":"8th century"},
  "peles-castle": {"article":"Peleș Castle","text":"Peleș Castle is a Neo-Renaissance palace in the Royal Domain of Sinaia in the Carpathian Mountains, near Sinaia, in Prahova County, Romania, on an existing medieval route linking Transylvania and Wallachia, built between 1873 and 1914. Its inauguration was held in 1883. It was constructed for King Carol I of Romania.","built":"1873","architects":["Carol Benesch","Karel Zdeněk Líman","Carl Wilhelm Christian von Doderer"]},
  "pena-palace": {"article":"Pena Palace","text":"The Pena Palace is a Romanticist palace in São Pedro de Penaferrim, in the municipality of Sintra, on the Portuguese Riviera. The castle stands on the top of a hill in the Sintra Mountains overlooking the town of Sintra, and on a clear day it can be easily seen from Lisbon and much of its metropolitan area. It is a national monument and constitutes one of the major expressions of 19th-century Romanticism in the world.","built":"1838","architects":["Wilhelm Ludwig von Eschwege"]},
  "pergamon": {"article":"Pergamon","text":"Pergamon or Pergamum, also referred to by its modern Greek form Pergamos, was a rich and powerful ancient Greek city in Aeolis. It is located 26 kilometres (16 mi) from the modern coastline of the Aegean Sea on a promontory on the north side of the river Caicus (modern-day Bakırçay) and northwest of the modern city of Bergama, Turkey.","built":"8th century BC"},
  "perito-moreno": {"article":"Perito Moreno Glacier","text":"The Perito Moreno, Francisco Gormaz or Bismarck Glacier is a glacier located in Los Glaciares National Park in southwest Santa Cruz Province, Argentina, and originated in the Magallanes Region in Chile, being also part of the Bernardo O'Higgins National Park. It is one of the most important tourist attractions in the Argentine Patagonia.","elevation":244},
  "persepolis": {"article":"Persepolis","text":"Persepolis was the ceremonial capital of the Achaemenid Empire (c. 550–330 BC). It is situated in the plains of Marvdasht, encircled by the southern Zagros Mountains, Fars province of Iran. It is one of the key Iranian cultural heritage sites and a UNESCO World Heritage Site. The earliest remains of Persepolis date back to 515 BC.","built":"510s BC","elevation":1627},
  "petajavesi": {"article":"Petäjävesi Old Church","text":"The Petäjävesi Old Church is a wooden church located in Petäjävesi, Finland. It was built between 1763 and 1765, when Tavastia was still a part of Sweden. The bell tower was built in 1821. It was inscribed in 1994 on the UNESCO World Heritage List for its testimony to the wooden church architecture of the Nordic countries.","built":"1763","elevation":117,"architects":["Jacob Clementsson Leppänen"]},
  "petra": {"article":"Petra","text":"Petra is an ancient city and archaeological site in southern Jordan. Famous for its rock-cut architecture and water conduit systems, Petra is also called the \"Rose City\" because of the colour of the sandstone from which it is carved. The city is one of the New 7 Wonders of the World and a UNESCO World Heritage Site. The area around Petra has been inhabited from as early as 7000 BC, and was settled by the Nabataeans, a nomadic Arab people, in the 4th century BC.","built":"800 BC","elevation":800},
  "petronas-towers": {"article":"Petronas Towers","text":"The Petronas Towers, also known as the Petronas Twin Towers and colloquially the KLCC Twin Towers, are an interlinked pair of 88-storey supertall skyscrapers in Kuala Lumpur, Malaysia, standing at 451.9 m (1,483 ft). From 1998 to 2004, they were the tallest buildings in the world until they were surpassed by the Taipei 101 skyscraper in Taiwan.","built":"1993","height":452,"architects":["César Pelli","Adamson Associates"]},
  "pfalzgrafenstein": {"article":"Pfalzgrafenstein Castle","text":"Pfalzgrafenstein Castle, also known as the Pfalz, is a toll castle situated on Falkenau island in the Rhine River, adjacent to Kaub, Germany. First established in 1326/27 by King Ludwig IV the Bavarian, the castle served to collect river tolls from passing traffic. Also seeing military activity, it withstood a 39 day siege in 1504 in the War of the Succession of Landshut and was occupied by Spanish forces for 11 years from 1620 in the Thirty Year's War.","built":"1326","elevation":72},
  "philae": {"article":"Philae temple complex","text":"The Philae temple complex is an island-based temple complex in the reservoir of the Aswan Low Dam, downstream of the Aswan Dam and Lake Nasser, Egypt in Africa. Originally, the temple complex was located on Philae Island, near the expansive First Cataract of the Nile in Upper Egypt. These rapids and the surrounding area have been variously flooded since the initial construction of the Aswan Low Dam in 1902.","elevation":109},
  "philippi": {"article":"Philippi","text":"Philippi was a major mainland Greek city northwest of the nearby island, Thasos. Its original name was Crenides. The city was renamed by Philip II of Macedon in 356 BC and abandoned in the 14th century after the Ottoman conquest. The present village of Filippoi is located near the ruins of the ancient city within the modern city of Kavala, in turn a"},
  "phoenix-islands": {"article":"Phoenix Islands Protected Area","text":"The Phoenix Islands Protected Area is located in the Republic of Kiribati, an ocean nation in the central Pacific approximately midway between Australia and Hawaii. PIPA constitutes 11.34% of Kiribati's exclusive economic zone (EEZ), and with a size of 408,250 km2 (157,630 sq mi), it is one of the largest marine protected areas (MPA) and one of the largest protected areas of any type (land or sea) on Earth.","built":"2008"},
  "pico-cao-grande": {"article":"Pico Cão Grande","text":"The Pico Cão Grande (Portuguese for \"Great Dog Peak\") is a landmark needle-shaped volcanic plug peak in São Tomé and Príncipe, in the Caué District of São Tomé Island in Parque Natural Obô de São Tomé. Its summit is 663 m (2,175 ft) above sea level, and it rises about 370 m (1,210 ft) over the surrounding terrain. The volcanic plug was formed by magma solidifying in the vent of an active volcano.","elevation":668},
  "pig-beach": {"article":"Pig Beach","text":"Pig Beach located on Big Major Cay (also known as Major Cay) is a beach on an uninhabited island (or cay) located in Exuma, the Bahamas. The island takes its unofficial name from the fact that it is populated by a colony of wild boars who live on the island. It has become a tourist attraction in modern times. The pigs are known in popular culture as \"the Bahamas' swimming pigs\" although other islands with swimming pigs exist in the Bahamas."},
  "pile-dwellings": {"article":"Prehistoric pile dwellings around the Alps","text":"Prehistoric pile dwellings around the Alps are a series of prehistoric pile dwelling (or stilt house) settlements in and around the Alps built from about 5000 to 500 BC on the edges of lakes, rivers or wetlands. In 2011, 111 sites located variously in Switzerland (56), Italy (19), Germany (18), France (11), Austria (5) and Slovenia (2) were added to the UNESCO World Heritage Site list."},
  "pingyao": {"article":"Pingyao","text":"Pingyao, officially Pingyao Ancient City, is a walled city in central Shanxi, China, famed for its importance in Chinese economic history and for its well-preserved Ming and Qing urban planning and architecture. It is the only walled city seat in China to survive with both its historic street plan and its original building fabric substantially intact."},
  "pitch-lake": {"article":"Pitch Lake","text":"The Pitch Lake is the largest natural deposit of bitumen in the world, estimated to contain 10 million tons. It is located in Trinidad and Tobago, more specifically in La Brea in southwest Trinidad, within the Siparia Regional Corporation. The lake covers about 0.405 square kilometres (100 acres) and is reported to be 76.2 metres (250 feet) deep."},
  "piton-de-la-fournaise": {"article":"Piton de la Fournaise","text":"Piton de la Fournaise is a shield volcano on the eastern side of Réunion island, a French overseas department and region, in the Indian Ocean. It is currently one of the most active volcanoes in the world, along with Kīlauea in the Hawaiian Islands, Stromboli and Etna in Italy and Mount Erebus in Antarctica. The volcano is located within Réunion National Park, a World Heritage Site.","elevation":2621},
  "pitons": {"article":"Pitons (Saint Lucia)","text":"The Pitons are two mountainous volcanic plugs, volcanic spires, located in Saint Lucia. Petit Piton is 743 m (2,438 ft) high and Gros Piton is 798.25 m (2,618.9 ft) high; they are linked by the Piton Mitan ridge. Piton means mountain peak in French, so Petit and Gros Piton respectively refer to the smaller and larger peak.","elevation":786},
  "place-stanislas": {"article":"Place Stanislas","text":"The Place Stanislas is a large pedestrianised square in the French city of Nancy, in the Lorraine historic region. Built between 1752 and 1756 on the orders of Stanislaus I, former King of Poland and Grand Duke of Lithuania, then Duke of Lorraine, the square is one of the oldest examples of an architecturally consistent monumental public square and is an excellent example of 18th-century urban architecture.","built":"1755","architects":["Emmanuel Héré de Corny"]},
  "plantin-moretus": {"article":"Plantin–Moretus Museum","text":"The Plantin–Moretus Museum is a museum in Antwerp, Belgium which showcases the history of printing in Antwerp and the prominent role played in that history by the family of printers founded by Christophe Plantin and Jan Moretus in Antwerp in the second half of the 16th century. It is based in a building on the Vrijdagmarkt in Antwerp that served as the residence of the Plantin-Moretus family and the location of the printing company, the Officina Plantina, for four centuries.","built":"1877"},
  "plaza-de-espana": {"article":"Plaza de España, Seville","text":"The Plaza de España (\"Spain Square\", in English) is a plaza in Maria Luisa Park in Seville, Spain. It was built in 1928 for the Ibero-American Exposition of 1929. It is a landmark example of Regionalism Architecture, mixing elements of the Baroque Revival, Renaissance Revival and Moorish Revival (Neo-Mudéjar) styles of Spanish architecture.","built":"1928","architects":["Aníbal González"]},
  "plitvice": {"article":"Plitvice Lakes National Park","text":"Plitvice Lakes National Park is one of the oldest and largest national parks in Croatia. In 1979, Plitvice Lakes National Park was inscribed on the UNESCO World Heritage list, for its outstanding and picturesque series of tufa lakes, caves, and connected waterfalls. The national park was founded in 1949 and is in the mountainous karst area of central Croatia, at the border with Bosnia and Herzegovina.","built":"1949"},
  "poblet": {"article":"Poblet Abbey","text":"Poblet Abbey, otherwise the Royal Abbey of Santa Maria de Poblet, is a Cistercian monastery, founded in 1151 by Cistercian monks from France, located at the foot of the Prades Mountains, in the comarca of Conca de Barberà, in Catalonia (Spain). The main architect was Arnau Bargués. This monastery was the first of three sister monasteries, known as the Cistercian triangle, that helped consolidate power in Catalonia in the 12th century.","built":"1150","height":11,"architects":["Arnau Bargués"]},
  "pola-island": {"article":"Pola Island","text":"Pola Island is an island just offshore from the village of Vatia on Tutuila Island in American Samoa. It is also known as Cockscomb. Pola Island is designated as part of the National Park American Samoa and is a popular tourist attraction. It is located on the west side of Vatia Bay, and serves as both a landmark and an icon for Vatia.","elevation":7},
  "polonnaruwa": {"article":"Gal Vihara","text":"The Gal Vihara, and known originally as the Uttararama, is a rock temple of the Buddha situated in the ancient city Polonnaruwa, the capital of the ancient Kingdom of Polonnaruwa, now present-day Polonnaruwa, in North Central Province, Sri Lanka. It was fashioned in the 12th century by King Parakramabahu I. The central feature of the temple is four rock relief statues of the Buddha, which have been carved into the face of a large granite gneiss rock."},
  "pompeii": {"article":"Pompeii","text":"Pompeii was a city in what is now the municipality of Pompei, near Naples, in the Campania region of Italy. Along with Herculaneum, Stabiae, and many surrounding villas, it was buried under 4 to 6 m (13 to 20 ft) of volcanic ash and pumice in the eruption of Mount Vesuvius in 79 AD. Largely preserved under the ash, Pompeii offers a snapshot of Roman life, frozen at the moment it was buried, as well as insight into ancient urban planning.","built":"6th century BC"},
  "pont-du-gard": {"article":"Pont du Gard","text":"The Pont du Gard is an ancient Roman aqueduct bridge built in the first century AD to carry water over 50 km (31 mi) to the Roman colony of Nemausus (Nîmes). It crosses the river Gardon near the town of Vers-Pont-du-Gard in southern France. The Pont du Gard is one of the best preserved Roman aqueduct bridges. It was added to UNESCO's list of World Heritage sites in 1985 because of its exceptional preservation, historical importance, and architectural ingenuity.","built":"1st century","height":48},
  "pontcysyllte": {"article":"Pontcysyllte Aqueduct","text":"The Pontcysyllte Aqueduct is a navigable aqueduct that carries the Llangollen Canal across the River Dee in the Vale of Llangollen in northeast Wales. The 19-arched stone and cast iron structure is for use by narrowboats and was completed in 1805 having taken ten years to design and build. It is 12 feet (3.7 metres) wide and is the longest aqueduct in Great Britain as well as the highest canal aqueduct in the world.","height":40,"architects":["Thomas Telford","William Jessop"]},
  "ponte-vecchio": {"article":"Ponte Vecchio","text":"The Ponte Vecchio is a medieval stone closed-spandrel segmental arch bridge over the Arno, in Florence, Italy. The only bridge in Florence spared from destruction during World War II, it is noted for the shops built along it; building shops on such bridges was once a common practice. Butchers, tanners, and farmers initially occupied the shops; the present tenants are jewellers, art dealers, and souvenir sellers.","built":"1335","architects":["Neri di Fioravante"]},
  "port-arthur": {"article":"Port Arthur, Tasmania","text":"Port Arthur is a town and former convict settlement on the Tasman Peninsula, in Tasmania, Australia. It is located approximately 97 kilometres (60 mi) southeast of the state capital, Hobart. The site forms part of the Australian Convict Sites, a World Heritage property consisting of 11 remnant penal sites originally built within the British Empire during the 18th and 19th centuries on fertile Australian coastal strips.","elevation":192},
  "port-royal": {"article":"Port Royal","text":"Port Royal is a small town located at the end of the Palisadoes, at the mouth of Kingston Harbour, in southeastern Jamaica. Founded in 1494 by the Spanish, it was once the largest and most prosperous city in the Caribbean, functioning as the centre of shipping and commerce in the Caribbean Sea by the latter half of the 17th century."},
  "porta-nigra": {"article":"Porta Nigra","text":"The Porta Nigra (Latin for black gate), referred to by locals as the Porta, is a large Roman city gate in Trier, Germany. It is a monumental gateway representative of Hellenistic military architecture of the time. It is a UNESCO World Heritage Site. The name Porta Nigra originated in the Middle Ages due to the darkened colour of its stone; the original Roman name has not been preserved.","built":"AD 180"},
  "porto": {"article":"Porto","text":"Porto, also known in English as Oporto, is the second largest city in Portugal, after Lisbon. It is the capital of the Porto District and one of the Iberian Peninsula's major urban areas. Porto city proper, which is the entire municipality of Porto, is small compared to its metropolitan area, with an estimated population of 273,476 people in a municipal area of 41.42 km2 (16 sq mi).","elevation":104},
  "potala-palace": {"article":"Potala Palace","text":"Potala Palace is a museum complex in Lhasa, the capital of the Tibet Autonomous Region of China. It was formerly the winter palace of the Dalai Lamas, and from 1649 until 1959 served as the Dalai Lamas' residence. The palace complex became a museum following the annexation of Tibet by the People's Republic of China. The palace is named after Mount Potalaka, regarded in Buddhist tradition as the mythical abode of the bodhisattva Avalokiteśvara.","built":"AD 637","height":117},
  "potosi": {"article":"Potosí","text":"Potosí, known as Villa Imperial de Potosí in the colonial period, is the capital city and a municipality of the Department of Potosí in Bolivia. It is one of the highest cities in the world at a nominal 4,067 m (13,343 ft). Diego Huallpa, an indigenous prospector, is traditionally credited with the discovery of the Cerro Rico in 1545, which led to the founding and rapid growth of Potosí due to its extraordinary silver wealth.","built":"1545","elevation":4070},
  "prague-castle": {"article":"Prague Castle","text":"Prague Castle is a castle complex in Prague, Czech Republic serving as the official residence and workplace of the president of the Czech Republic. Built in the 9th century, the castle has long served as the seat of power for kings of Bohemia, Holy Roman emperors, and presidents of Czechoslovakia. As such, the term \"Prague Castle\" or simply \"Hrad\" (\"the Castle\") are often used as metonymy for the president and his staff and advisors.","built":"9th century","elevation":250,"architects":["Matthias of Arras","Benedikt Rejt","Jože Plečnik"]},
  "prambanan": {"article":"Prambanan","text":"Prambanan is a 9th-century Hindu temple compound in the Special Region of Yogyakarta, in southern Java, Indonesia, dedicated to the Trimūrti, the expression of God as the Creator (Brahma), the Preserver (Vishnu), and the Destroyer (Shiva). The temple compound is located approximately 17 kilometres (11 mi) northeast of Yogyakarta on the boundary between Central Java and Yogyakarta provinces.","built":"AD 850","height":47},
  "preah-vihear": {"article":"Preah Vihear","text":"Preah Vihear is an ancient edifice built by the Khmer Empire as a Hindu temple on top of a 525-metre (1,722 ft) cliff in the Dângrêk Mountains, in Cambodia. Over time, it became a Buddhist temple. As a key edifice of the empire's spiritual life, Preah Vihear was supported and modified by successive kings and thus bears elements of several architectural styles.","built":"AD 893"},
  "providence-island": {"article":"Providence Island, Liberia","text":"Providence Island (Historically known as Perseverance, Dozoa Island, or Darzoe Island) was the site of the first successful settlement of American freedmen by the American Colonization Society in Liberia. It has been proposed as a UNESCO World Heritage Site by the government of Liberia."},
  "puebla": {"article":"Historic centre of Puebla","text":"The historic centre of Puebla was declared a World Heritage Site by UNESCO in 1987. The Historic Monuments Zone of Puebla is considered the origin of Puebla. This Zone was decreed a Historic Monuments Zone in 1977 by presidential decree and 1 year later UNESCO declared it a World Heritage Site. The Historic Monuments Zone retains a lot of colonial buildings."},
  "pyramids-of-giza": {"article":"Giza pyramid complex","text":"The Giza pyramid complex (also called the Giza necropolis) in Egypt is home to the Great Pyramid, the pyramid of Khafre, and the pyramid of Menkaure, along with their associated pyramid complexes and the Great Sphinx. All were built during the Fourth Dynasty of the Old Kingdom of ancient Egypt, between c. 2600 – c. 2500 BC.","elevation":27},
  "qalat-al-bahrain": {"article":"Qal'at al-Bahrain","text":"The Qal'at al-Bahrain (also Qala'at al-Bahrain), also known as the Bahrain Fort or Portuguese Fort, is an archaeological site located in Bahrain. Archaeological excavations carried out since 1954 have unearthed antiquities from an artificial mound of 12 m (39 ft) height containing seven stratified layers, created by various occupants from 2300 BC up to the 18th century, including Kassites, Greeks, Portuguese and Persians, making it the oldest fortification in the Persian Gulf region."},
  "qalhat": {"article":"Qalhat","text":"Qalhāt is a village in Oman, over 20 km north of Sur. The residential area is to the northwest of Wādī Ḥilm, and the ruins of the ancient city are located to the southeast. The ancient city is referred to as Calatu by Marco Polo and as Calha in the map of Abraham Ortelius."},
  "quedlinburg": {"article":"Quedlinburg","text":"Quedlinburg is a town situated just north of the Harz mountains, in the district of Harz in the west of Saxony-Anhalt, Germany. As an influential and prosperous trading centre during the early Middle Ages, Quedlinburg became a center of influence under the Ottonian dynasty in the 10th and 11th centuries. The castle, church and old town with around 2,100 timber houses, dating from this time of influence, were added to the UNESCO's World Heritage List in 1994 because of their exceptional preservation and outstanding Romanesque architecture.","elevation":130},
  "quirigua": {"article":"Quiriguá","text":"Quiriguá is an ancient Maya archaeological site in the department of Izabal in south-eastern Guatemala. It is a medium-sized site covering approximately 3 square kilometres (1.2 sq mi) along the lower Motagua River, with the ceremonial center about 1 km (0.6 mi) from the north bank. During the Maya Classic Period (AD 200–900), Quiriguá was situated at the juncture of several important trade routes."},
  "quito": {"article":"Quito","text":"Quito, officially San Francisco de Quito, is the capital of Ecuador, and the province of Pichincha. It is the largest city in Pichincha and the second-largest city in Ecuador, with an estimated population of 1.7 million in the city and 2.8 million in its metropolitan area. Quito is in a valley on the eastern slopes of Pichincha, an active stratovolcano in the Andes.","built":"1534","elevation":2850},
  "quseir-amra": {"article":"Qusayr 'Amra","text":"Qusayr 'Amra or Quseir Amra, sometimes also named Qasr Amra, is the best-known of the desert castles located in present-day eastern Jordan. It was built some time between 723 and 743, by Walid Ibn Yazid, the future Umayyad caliph Walid II, whose dominance of the region was rising at the time. It is considered one of the most important examples of early Islamic art and architecture.","built":"AD 712","height":520},
  "qutb-minar": {"article":"Qutb Minar","text":"The Qutb Minar, also spelled Qutub Minar and Qutab Minar, is a minaret and victory tower, built during the Delhi sultanate, and comprising the Qutb complex, a UNESCO World Heritage Site in Mehrauli, South Delhi, India. It was mostly built between 1199 and 1220, contains 399 steps, and is one of the most frequented heritage spots in the city.","height":73},
  "ramappa": {"article":"Ramappa Temple","text":"The Rudreshwara Temple, more commonly known as the Ramappa Temple, is a Hindu temple located in the village of Palampet in eastern Telangana, India. An inscription on a basalt pillar found within a nearby courtyard records that the temple was commissioned in 1213 by Recherla Rudra, a military general of the Kakatiya dynasty, and constructed over a period of 40 years during the reign of Ganapati, the third sovereign of the dynasty."},
  "rani-ki-vav": {"article":"Rani ki Vav","text":"Rani ki Vav is a stepwell situated in the town of Patan in Gujarat, India. It is located on the banks of the Saraswati River. Its construction is attributed to Udayamati, the Wife of the 11th-century Chaulukya king Bhima I. Silted over, it was rediscovered in the 1940s and restored in the 1980s by the Archaeological Survey of India."},
  "ravenna": {"article":"Basilica of San Vitale","text":"The Basilica of San Vitale is a late antique church in Ravenna, Italy. The sixth-century church is an important surviving example of early Byzantine art and architecture, and its mosaics in particular are some of the most-studied works in Byzantine art. It is one of eight structures in Ravenna inscribed in the UNESCO World Heritage List.","built":"6th century"},
  "red-fort": {"article":"Red Fort","text":"The Red Fort is a historic Mughal fort located in the Old Delhi area of Delhi, India. Serving as the main residence of the Mughal emperors, it was commissioned by Emperor Shah Jahan on the 12th of May 1639; the fort was constructed following his decision to shift the Mughal capital from Agra to Delhi. Originally adorned in red and white, the fort's design is attributed to Ustad Ahmad Lahori, the architect of the Taj Mahal.","built":"1648","height":33},
  "regensburg": {"article":"Stone Bridge (Regensburg)","text":"The Stone Bridge (Steinerne Brücke) in Regensburg, Germany, is a 12th-century bridge across the Danube linking the Old Town with Stadtamhof. For more than 800 years, until the 1930s, it remained the city's only bridge across the river. It is a masterwork of medieval construction and an emblem of the city.","built":"1146"},
  "registan": {"article":"Registan","text":"Registan, officially the Registan Square is a historic public square in the city of Samarkand, Uzbekistan. It served as the heart of the Timurid Empire and later as the city's commercial, educational, and ceremonial center. The square is famed for its ensemble of three madrasas (Islamic schools): the Ulugh Beg Madrasa of the Timurid period, the Sherdar Madrasa and the Tilakari Madrasa, built later under the Uzbek Janid dynasty—which together represent some of the finest achievements of Islamic architecture in Central Asia.","built":"1417"},
  "reims": {"article":"Reims Cathedral","text":"Notre-Dame de Reims, known in English as Reims Cathedral (also spelt Rheims Cathedral), is a Catholic cathedral in the French city of the same name, the seat of the Archdiocese of Reims. The cathedral was dedicated to the Virgin Mary and was the traditional location for the coronation of the kings of France. The cathedral is considered to be one of the most important works of Gothic architecture.","built":"13th century","height":81,"architects":["Jean d'Orbais"]},
  "rhodes": {"article":"Palace of the Grand Master of the Knights of Rhodes","text":"The Palace of the Grand Master of the Knights of Rhodes, also known as the Kastello, is a medieval castle in the city of Rhodes, on the island of Rhodes in Greece. It is one of the few examples of Gothic architecture in Greece. The site was previously a citadel of the Knights Hospitaller that functioned as a palace, headquarters, and fortress.","built":"14th century"},
  "rialto-bridge": {"article":"Rialto Bridge","text":"The Rialto Bridge is the oldest of the four bridges spanning the Grand Canal in Venice, Italy. Connecting the sestieri (districts) of San Marco and San Polo, it has been rebuilt several times since its first construction as a pontoon bridge in 1173, and is now a significant tourist attraction in the city. The present stone bridge is a single span designed by Antonio da Ponte.","built":"1588","height":6.7,"architects":["Antonio da Ponte"]},
  "rideau-canal": {"article":"Rideau Canal","text":"The Rideau Canal is a 202-kilometre long canal that links the Ottawa River at Ottawa with the Cataraqui River and Lake Ontario at Kingston, Ontario, Canada. Its 46 locks raise boats from the Ottawa River 83 metres (272 feet) upstream along the Rideau River to the Rideau Lakes, and from there drop 50 metres (164 feet) downstream along the Cataraqui River to Kingston."},
  "riesenrad": {"article":"Wiener Riesenrad","text":"The Wiener Riesenrad, or simply Riesenrad, is a 64.75-metre (212 ft) tall Ferris wheel at the entrance of the Prater amusement park in Leopoldstadt, the 2nd district of Austria's capital Vienna. It is one of Vienna's most popular tourist attractions, and symbolises the district as well as the city for many people. Constructed in 1897, it was the world's tallest extant Ferris wheel from 1920 until 1985.","built":"1897","height":65,"architects":["Walter Bassett Basset","Hubert Cecil Booth"]},
  "rietveld-schroder": {"article":"Rietveld Schröder House","text":"The Rietveld Schröder House in Utrecht (Prins Hendriklaan 50) was built in 1924 by Dutch architect Gerrit Rietveld for Mrs. Truus Schröder-Schräder and her three children. She commissioned the house to be designed preferably without walls. Both Rietveld and Schröder espoused progressive ideals that included \"a fierce commitment to a new openness about relationships within their own families and to truth in their emotional lives.","built":"1924","architects":["Gerrit Rietveld","Truus Schröder-Schräder"]},
  "riga": {"article":"Vecrīga","text":"Vecrīga (\"Old Riga\") is the historical center and a neighbourhood (as Vecpilsēta, \"Old City\") of Riga, Latvia, located in the Central District on the east side of Daugava River. Vecrīga is famous for its old churches and cathedrals, such as Riga Cathedral, St. James's Cathedral and St. Peter's Church."},
  "rijksmuseum": {"article":"Rijksmuseum","text":"The Rijksmuseum is the national museum of the Netherlands dedicated to Dutch arts and history, located at the Museum Square in the borough of Amsterdam South, close to the Van Gogh Museum, the Stedelijk Museum Amsterdam, and the Royal Concertgebouw. The Rijksmuseum was founded in The Hague on 19 November 1798 and moved to Amsterdam in 1808, where it was first located in the Royal Palace and later in the Trippenhuis.","built":"1800","architects":["Pierre Cuypers"]},
  "rila": {"article":"Rila Monastery","text":"The Monastery of Saint John of Rila, also known as Rila Monastery, is the largest and most famous Eastern Orthodox monastery in Bulgaria. It is situated in the southwestern Rila Mountains, 117 km (73 mi) south of the capital Sofia in the deep valley of the Rilska River (\"Rila River\") at an elevation of 1,147 m (3,763 ft) above sea level, inside of Rila Monastery Nature Park and in close vicinity of the Rila Monastery Forest Nature Reserve.","built":"AD 946","elevation":1147},
  "ring-of-brodgar": {"article":"Ring of Brodgar","text":"The Ring of Brodgar (or Brogar, or Ring o' Brodgar) is a Neolithic henge and stone circle about 6 miles north-east of Stromness on Mainland, the largest island in Orkney, Scotland. It is part of the UNESCO World Heritage Site known as the Heart of Neolithic Orkney."},
  "rjukan": {"article":"Rjukan–Notodden Industrial Heritage Site","text":"The Rjukan–Notodden Industrial Heritage Site is a World Heritage Site in Telemark county, Norway, created to protect the industrial landscape around Lake Heddalsvatnet and Vestfjorddalen valley. The landscape is centered on the plant built by the Norsk Hydro company to produce calcium nitrate fertilizer from atmospheric nitrogen using the Birkeland–Eyde process."},
  "robben-island": {"article":"Robben Island","text":"Robben Island is an island in Table Bay, 6.9 kilometers west of the coast of Bloubergstrand, north of Cape Town, South Africa. It takes its name from the archaic Dutch word for seals (robben). The island is roughly oval in shape, 3.3km long north–south, and 1.9km wide, with an area of 5.1 sq. km. It is flat and only a few metres above sea level, as a result of an ancient erosion event.","elevation":17},
  "rock-islands": {"article":"Rock Islands","text":"The Rock Islands of Palau, also called Chelbacheb, are a collection of several hundred small limestone or coral uprises in the Southern Lagoon of Palau between Koror and Peleliu, now an incorporated part of Koror State. There are between 250 and 300 islands in the group according to different sources, with an aggregate area of 42 square kilometers (16 sq mi) and a maximum height of 207 meters (679 ft).","elevation":207},
  "rock-of-gibraltar": {"article":"Rock of Gibraltar","text":"The Rock of Gibraltar is a monolithic limestone mountain 426 m (1,398 ft) high dominating the western entrance to the Mediterranean Sea at the Strait of Gibraltar. It is situated near the end of a narrow 9-kilometre-long (5.6 mi) promontory stretching due south into the Mediterranean Sea and is located within the British territory of Gibraltar.","elevation":426},
  "rohtas": {"article":"Rohtas Fort","text":"Rohtas Fort is a 16th-century fortress located near the city of Dina in Jhelum district of the Punjab province, Pakistan. Commissioned by Sur emperor Sher Shah Suri, its construction was supervised by Raja Todar Mal and is now one of the largest and most formidable forts in Punjab. The fort remains remarkably intact and was declared a UNESCO World Heritage Site in 1997.","built":"1541"},
  "roi-mata": {"article":"Roi Mata","text":"Roi Mata (or Roy Mata, Roymata) was a chiefly title in the central islands of Vanuatu. It was borne by a long dynasty of chiefs, from the 11th to the 17th century. Among the bearers of the Roi Mata title, the most famous is the last one, a man believed to have lived around year 1600. That chief is often designated as \"Roi Mata\", with no formal distinction from its predecessors — a source of potential confusion."},
  "roros": {"article":"Røros (town)","text":"Røros or Plaassja (Southern Sami) is the administrative centre of Røros Municipality in Trøndelag county, Norway. The town is located along the river Hyttelva and along the Rørosbanen railway line, about 10 kilometres (6.2 mi) south of the village of Glåmos and about the same distance north of the village of Os i Østerdalen in neighboring Innlandet county.","elevation":620},
  "roskilde": {"article":"Roskilde Cathedral","text":"Roskilde Cathedral, in the city of Roskilde on the island of Zealand (Sjælland) in eastern Denmark, is a cathedral of the Lutheran Church of Denmark. The cathedral is one of the most important churches in Denmark, and the official royal burial church of the Danish monarchs. It is also a UNESCO World Heritage Site. This is due to two criteria: the architecture of the cathedral shows 800 years of European architectural styles, and it is one of the earliest examples in Scandinavia of a Gothic cathedral to be built in brick; it encouraged the spread of the Brick Gothic style throughout Northern Europe.","built":"13th century","architects":["Absalon"]},
  "royal-exhibition-building": {"article":"Royal Exhibition Building","text":"The Royal Exhibition Building is a UNESCO World Heritage-listed building in Melbourne, Victoria, Australia, built in 1879–1880 as part of the international exhibition movement, which presented over 50 exhibitions between 1851 and 1915 around the globe. The building sits on approximately 26 hectares (64 acres), is 150 metres (490 ft) long and is surrounded by four city streets.","built":"1879","architects":["Joseph Reed"]},
  "sabratha": {"article":"Sabratha","text":"Sabratha, in the Zawiya District of Libya, was the westernmost of the ancient \"three cities\" of Roman Tripolis, alongside Oea and Leptis Magna. From 2001 to 2007 it was the capital of the former Sabratha wa Sorman District. It lies on the Mediterranean coast about 70 km (43 mi) west of modern Tripoli. The extant archaeological site was inscribed as a UNESCO World Heritage Site in 1982.","elevation":12},
  "sacre-coeur": {"article":"Sacré-Cœur, Paris","text":"The Basilica of the Sacred Heart of Montmartre, commonly known as Sacré-Cœur Basilica or simply Sacré-Cœur, is a Catholic church and minor basilica in Paris dedicated to the Sacred Heart of Jesus. Sacré-Cœur Basilica is located at the summit of the butte of Montmartre. From its dome two hundred meters above the Seine, the basilica overlooks the entire city of Paris and its suburbs.","built":"1875","height":83,"architects":["Paul Abadie"]},
  "safranbolu": {"article":"Safranbolu","text":"Safranbolu is a town in Karabük Province in the Black Sea region of Turkey. It is the seat of Safranbolu District. Its population is 52,999 (2022). It is about 9 km north of the city of Karabük, 200 kilometres (120 mi) north of Ankara and about 100 km south of the Black Sea coast. The town's historic names in Greek were Theodoroupolis, Dadybra and later Saphrampolis.","elevation":485},
  "sagrada-familia": {"article":"Sagrada Família","text":"Basílica i Temple Expiatori de la Sagrada Família, or simply Sagrada Família, is a Catholic Basilica under construction in the Eixample district of Barcelona, Catalonia, Spain. Designed by the Spanish architect Antoni Gaudí, it is the tallest church in the world. On 7 November 2010, Pope Benedict XVI consecrated the church and proclaimed it a basilica.","built":"1882","height":173,"architects":["Antoni Gaudí"]},
  "saint-basils": {"article":"Saint Basil's Cathedral","text":"The Cathedral of Vasily the Blessed, commonly known as Saint Basil's Cathedral, is a Russian Orthodox church on Red Square in the historic centre of Moscow. It is one of the most popular cultural symbols of Russia. The building, now a museum, is officially known as the Cathedral of the Intercession of the Most Holy Theotokos on the Moat, or Pokrovsky Cathedral.","built":"1555","height":48,"architects":["Postnik Yakovlev"]},
  "saint-emilion": {"article":"Saint-Émilion","text":"Saint-Émilion is a commune in the Gironde department in Nouvelle-Aquitaine in Southwestern France. In the heart of the country of Libournais (the area around Libourne), in a region of wine hills, Saint-Émilion is a medieval city located at the crossroads of Bordeaux, Saintonge and Périgord. The town and surrounding vineyards was made a UNESCO World Heritage Site in 1999, owing to its long, living history of wine-making, Romanesque churches and ruins stretching all along steep and narrow streets.","elevation":23},
  "saint-jacques-tower": {"article":"Tour Saint-Jacques","text":"Tour Saint-Jacques is a monument located in the 4th arrondissement of Paris, France, on the Rive Droite. This 52-metre (171 ft) Flamboyant Gothic tower at the intersection of the Rue de Rivoli with Rue Nicolas-Flamel is all that remains of the former medieval Church of Saint-Jacques-de-la-Boucherie ('Saint James of the Meat Market'), which was partially rebuilt in the 16th-century and demolished in 1797, during the French Revolution, leaving only the tower.","built":"1523","height":54},
  "saint-louis": {"article":"Island of Saint-Louis","text":"The Island of Saint-Louis is the historic part of the city of Saint-Louis in Senegal. In 2000, it was inscribed by the UNESCO on the World Heritage list."},
  "saint-petersburg": {"article":"Church of the Savior on Blood","text":"The Church of the Savior on Spilled Blood is a Russian Orthodox church in Saint Petersburg, Russia which currently functions as a secular museum and church at the same time. The structure was constructed between 1883 and 1907. It is one of Saint Petersburg's major attractions. The church was erected on the site where Narodnaya Volya members assassinated Emperor Alexander II in March 1881.","built":"1907","height":81,"architects":["Alfred Parland"]},
  "saint-savin": {"article":"Abbey Church of Saint-Savin-sur-Gartempe","text":"The Abbey Church of Saint-Savin-sur-Gartempe is a Roman Catholic church located in Saint-Savin-sur-Gartempe, in Poitou, France. The Romanesque church was begun in the mid-11th century and contains many beautiful 11th- and 12th-century murals which are still in a remarkable state of preservation. The church is often referred to as the \"Romanesque Sistine Chapel\" and has been a UNESCO World Heritage Site since 1983.","built":"11th century","architects":["Charles Joly-Leterme","Charles Dorian"]},
  "saint-simeon": {"article":"Dead Cities","text":"The Dead Cities or Forgotten Cities are a group of 700 abandoned settlements in northwest Syria between Aleppo and Idlib. Around 40 villages grouped in eight archaeological parks situated in north-western Syria provide an insight into rural life in Late Antiquity and during the Byzantine period. Most of the villages, which date from the 1st to 7th centuries, were abandoned between the 8th and 10th centuries."},
  "saint-sophia": {"article":"Saint Sophia Cathedral, Kyiv","text":"The Saint Sophia Cathedral in Kyiv, Ukraine is an architectural monument of Kyivan Rus'. The former cathedral is one of the city's best known landmarks and the first heritage site in Ukraine to be inscribed on the World Heritage List along with the Kyiv Cave Monastery complex. The World Heritage Committee of UNESCO decided in June 2013 that Kyiv Pechersk Lavra, and St Sophia Cathedral along with its related monastery buildings would remain on the World Heritage List.","built":"1011"},
  "salamanca": {"article":"New Cathedral of Salamanca","text":"The Catedral de la Asunción de la Virgen (Cathedral of the Assumption of the Virgin Mary), popularly known as New Cathedral is, together with the Old Cathedral, one of the two cathedrals of Salamanca, Castile and León, Spain. It is the seat of the diocese of Salamanca. It was constructed between 1533 and 1733 mixing late Gothic, Plateresque and Baroque styles.","built":"1513","height":92,"architects":["Rodrigo Gil de Hontañón"]},
  "salar-de-uyuni": {"article":"Salar de Uyuni","text":"Salar de Uyuni is the largest salt flat in the world, with an area of approximately 10,582 square kilometres (4,086 mi2). It is situated in southwestern Bolivia, within the Daniel Campos Province of the Potosí Department, near the crest of the Andes Mountains, at an elevation of 3,656 m (11,995 ft) above sea level. The Salar was formed as a result of transformations of seven Late Pleistocene lakes whose progressive desiccation led to the accumulation of extensive evaporitic salt deposits.","elevation":3661},
  "saltaire": {"article":"Saltaire","text":"Saltaire is a Victorian model village near Shipley, West Yorkshire, England, south of the River Aire, Salts Mill was built between the railway and the Leeds and Liverpool Canal. The mill and houses were built for Titus Salt between 1851 and 1871 to allow his workers to live in better conditions than the slums of Bradford."},
  "salvador": {"article":"Elevador Lacerda","text":"The Lacerda Elevator (Elevador Lacerda) is a public urban elevator located in Salvador, Brazil, connecting the lower city (Cidade Baixa) to the upper city (Cidade Alta). The 72 metres (236 ft) elevator was built between 1869 and 1873; it was named after Antônio de Lacerda, director of the Commercial Association of Bahia.","built":"1869"},
  "salzburg": {"article":"Salzburg","text":"Salzburg is the fourth-largest city in Austria. In 2026, its population was 157,994. The city lies on the Salzach River, near the border with Germany and at the foot of the Alps mountains. The town occupies the site of the Roman settlement of Iuvavum. Founded as an episcopal see in 696, it became a seat of the archbishop in 798.","elevation":424},
  "samaipata": {"article":"El Fuerte de Samaipata","text":"El Fuerte de Samaipata or Fort Samaipata, also known simply as \"El Fuerte\", is a Pre-Columbian archaeological site and UNESCO World Heritage Site located in Florida Province, Santa Cruz Department, Bolivia. It is situated in the eastern foothills of the Bolivian Andes and is a popular tourist destination for Bolivians and foreigners alike.","elevation":1904},
  "samarra": {"article":"Great Mosque of Samarra","text":"The Great Mosque of Samarra or Al-Malwiya Mosque is a former congregational mosque, now in partial ruins, in Samarra, in the Saladin Governorate of Iraq. The mosque was commissioned in 848 CE and completed in 851 by the Abbasid caliph Al-Mutawakkil. At the time of construction it was the world's largest mosque. It is known for its 52-metre-high (171 ft) minaret encircled by a spiral ramp.","built":"AD 848"},
  "sambor-prei-kuk": {"article":"Sambor Prei Kuk","text":"Sambor Prei Kuk (Isanapura) is an archaeological site in Cambodia located in Kampong Thom Province, 30 km (19 mi) north of Kampong Thom, the provincial capital, 176 km (109 mi) east of Angkor and 206 km (128 mi) north of Phnom Penh. The now ruined complex dates back to the Pre-Angkorian Chenla Kingdom (late 6th to 9th century), established by king Isanavarman I as central royal sanctuary and capital, known then as \"Isanapura\"."},
  "san-agustin": {"article":"San Agustín Archaeological Park","text":"The San Agustín Archaeological Park is a large archaeological area located near the town of San Agustín in Huila Department in Colombia. The park contains the largest collection of religious monuments and megalithic sculptures in Latin America and is considered the world's largest necropolis. Belonging to the San Agustin culture, it was declared a UNESCO World Heritage Site in 1995."},
  "san-cristobal-de-la-laguna": {"article":"San Cristóbal de La Laguna","text":"San Cristóbal de La Laguna is a city and municipality in the northern part of the island of Tenerife in the Province of Santa Cruz de Tenerife, on the Canary Islands, Spain. The former capital of the Canary Islands, the city is the third-most populous city of the archipelago and the second-most populous city of the island.","built":"1496","elevation":553},
  "san-gimignano": {"article":"San Gimignano","text":"San Gimignano is a small walled medieval hill town in the province of Siena, Tuscany, north-central Italy. Known as the Town of Five Towers, San Gimignano is famous for its medieval architecture, unique in the preservation of about a dozen of its tower houses, which, with its hilltop setting and encircling walls, form \"an unforgettable skyline\".","elevation":324},
  "san-ignacio-mini": {"article":"San Ignacio Miní","text":"San Ignacio Miní was one of the many missions founded in 1610 in Argentina, by the Jesuits in what the colonial Spaniards called the Province of Paraguay of the Americas during the Spanish colonial period. It is located near present-day San Ignacio valley, some 60 kilometers (37 mi) north of Posadas, Misiones Province, Argentina."},
  "san-miguel-de-allende": {"article":"San Miguel de Allende","text":"San Miguel de Allende is the principal city in the municipality of San Miguel de Allende, located in the far eastern part of Guanajuato, Mexico. A part of the Bajío region, the town lies 274 km (170 mi) from Mexico City, 86 km (53 mi) from Querétaro and 97 km (60 mi) from the state capital of Guanajuato. The town's name derives from a 16th-century friar, Juan de San Miguel, and a martyr of Mexican Independence, Ignacio Allende, who was born in a house facing the central plaza.","built":"1542","elevation":1900},
  "san-pedro-de-la-roca": {"article":"Castillo de San Pedro de la Roca","text":"The Castillo de San Pedro de la Roca (also known by the less formal title of Castillo del Morro or as San Pedro de la Roca Castle) is a fortress located on the coast of the Cuban city of Santiago de Cuba. About 6 miles (10 km) southwest of the city centre, it overlooks the bay. The fortress was declared a World Heritage Site by UNESCO in 1997, cited as the best preserved and most complete example of Spanish-American military architecture."},
  "sanaa": {"article":"Old City of Sanaa","text":"The Old City of Sanaʽa is a recognised UNESCO World Heritage Site in the Amanat Al Asimah Governorate, Yemen. As of 2003, the district had a population of 63,398 inhabitants. The old fortified city has been inhabited for more than 2,500 years and contains many intact architectural sites. The oldest, partially standing architectural structure in the Old City of Sanaʽa is Ghumdan Palace.","elevation":2266},
  "sanchi": {"article":"Sanchi Stupa","text":"Sanchi Stupa is a Buddhist complex, famous for its Great Stupa, on a hilltop at Sanchi Town in Raisen District of the State of Madhya Pradesh, India. It is located about 23 kilometres from Raisen town, the district headquarters and 46 kilometres (29 mi) northeast of Bhopal, capital of Madhya Pradesh. The Great Stupa at Sanchi is one of the oldest stone structures in India, and an important monument to the historical architecture of India."},
  "sanssouci": {"article":"Sanssouci","text":"Schloss Sanssouci is a historical building in Potsdam, near Berlin. Built by Prussian King Frederick the Great as his summer palace, it is often counted among the German rivals of Versailles. While Sanssouci is in the more intimate Rococo style and is far smaller than its French Baroque counterpart, it is similarly notable for the numerous temples and follies in the surrounding park.","built":"1745","elevation":40,"architects":["Georg Wenzeslaus von Knobelsdorff"]},
  "santiago-cathedral": {"article":"Santiago de Compostela Cathedral","text":"The Santiago de Compostela Archcathedral Basilica (Spanish and Galician: Catedral Basílica de Santiago de Compostela) is part of the Metropolitan Archdiocese of Santiago de Compostela and is an integral component of the Santiago de Compostela World Heritage Site in Galicia, Spain. The cathedral is the reputed burial place of Saint James the Great, one of the apostles of Jesus Christ.","built":"9th century","height":75,"architects":["Fernando de Casas Novoa"]},
  "santiniketan": {"article":"Santiniketan","text":"Santiniketan is a neighbourhood of Bolpur town in the Bolpur subdivision of Birbhum district in West Bengal, India, approximately 152 km north of Kolkata. It was established by Debendranath Tagore, and later expanded by his son, Rabindranath Tagore whose vision became what is now a university town with the creation of Visva-Bharati.","built":"1863","elevation":56},
  "santo-domingo": {"article":"Ciudad Colonial (Santo Domingo)","text":"Ciudad Colonial is the historic central neighborhood of the Dominican Republic's capital Santo Domingo. It is the oldest continuously inhabited European-established settlement in the Americas. The area has been declared a World Heritage Site by UNESCO. It is also known as Zona Colonial (Colonial Zone) or more colloquially as \"La Zona\" (The Zone)."},
  "santorini": {"article":"Santorini","text":"Santorini, officially Thira or Thera, is a Greek island in the southern Aegean Sea, about 200 km (120 mi) southeast from the mainland. It is the largest island of a small, circular archipelago formed by the Santorini caldera. It is the southernmost member of the Cyclades group of islands, with an area of approximately 73 km2 (28 mi2) and a 2021 census population of 15,480.","elevation":567},
  "sarmizegetusa": {"article":"Sarmizegetusa Regia","text":"Sarmizegetusa Regia was the capital and the most important military, religious and political centre of the Dacians before the wars with the Roman Empire. Built on top of a 1200 m high mountain, the fortress, consisting of six citadels, was the core of a strategic and defensive system in the Orăștie Mountains (in present-day Romania)."},
  "sarnath": {"article":"Sarnath","text":"Sarnath (also known as Deer Park, Sarangnath, Isipatana Deer Park, Rishipattana, Migadaya, or Mrigadava) is a town northeast of Varanasi, in Uttar Pradesh, India. It was here that the Buddha gave his first sermon after attaining enlightenment at Bodh Gaya. The Lion Capital of Ashoka, raised on a column in Sarnath in 250 BCE by the first Buddhist emperor Ashoka, commemorates this event."},
  "schokland": {"article":"Schokland","text":"Schokland is a former island in the Dutch Zuiderzee, in the municipality of Noordoostpolder. Schokland was an elongated strip of peat land which ceased to be an island when the Noordoostpolder was reclaimed from the sea in 1942. It is now just a slightly elevated part of the polder, with a still partly intact retaining wall of the waterfront of Middelbuurt."},
  "schonbrunn": {"article":"Schönbrunn Palace","text":"Schönbrunn Palace was the main summer residence of the Habsburg rulers, located in Hietzing, the 13th district of Vienna. The name Schönbrunn (meaning \"beautiful spring\") has its roots in an artesian well from which water was consumed by the court. The 1,441-room Baroque palace is one of the most important architectural, cultural, and historic monuments in the country.","built":"1638","elevation":193,"architects":["Johann Bernhard Fischer von Erlach","Nicolò Pacassi"]},
  "schwerin-castle": {"article":"Schwerin Castle","text":"Schwerin Castle, also known as Schwerin Palace, is a 19th-century Schloss built in the historicist style located in the city of Schwerin, the capital of Mecklenburg-Vorpommern state, Germany. It is situated on an island in the city's main lake, Lake Schwerin. For centuries, the castle on the present site was the residence of the dukes and grand dukes of Mecklenburg and later Mecklenburg-Schwerin, although few parts of the pre-19th-century castle have survived.","elevation":45,"architects":["Georg Adolph Demmler","Gottfried Semper","Friedrich August Stüler"]},
  "scott-monument": {"article":"Scott Monument","text":"The Scott Monument is a Victorian Gothic monument to Scottish author Sir Walter Scott. It is the second-largest monument to a writer in the world after the José Martí monument in Havana. It stands in Princes Street Gardens in Edinburgh, opposite the former Jenners building on Princes Street and near Edinburgh Waverley Railway Station, which is named after Scott's Waverley novels.","built":"1840"},
  "segovia-aqueduct": {"article":"Aqueduct of Segovia","text":"The Aqueduct of Segovia is a Roman aqueduct in Spain, built around the first century AD to channel water from springs in the mountains 17 kilometres (11 mi) to Segovia's fountains, public baths and private houses, in use until 1973. Its elevated section, with its complete arcade of 167 arches, is one of the best-preserved Roman aqueduct bridges and the foremost symbol of Segovia, as evidenced by its presence on the city's coat of arms.","built":"2nd century","height":28},
  "selimiye": {"article":"Selimiye Mosque, Edirne","text":"The Selimiye Mosque is an Ottoman imperial mosque, located in the city of Edirne (formerly Adrianople), Turkey. It was commissioned by Sultan Selim II and was built by the imperial architect Mimar Sinan between 1568 and 1575. It was considered by Sinan to be his masterpiece and is one of the highest achievements of Islamic architecture as a whole and Ottoman architecture in particular.","built":"1575","height":71,"architects":["Mimar Sinan"]},
  "semmering": {"article":"Semmering Railway","text":"The Semmering Railway in Austria, which starts at Gloggnitz and leads over the Semmering to Mürzzuschlag, was the first mountain railway in Europe built with a standard gauge track. It is commonly referred to as the world's first true mountain railway, given the very difficult terrain and the considerable altitude difference that was mastered during its construction.","built":"1854"},
  "seongsan": {"article":"Seongsan Ilchulbong","text":"Seongsan Ilchulbong, also called Sunrise Peak, is a volcano on eastern Jeju Island, in Seongsan-ri, Seogwipo, Jeju Province, South Korea. It is 182 meters high and has a volcanic crater at the top. Considered one of South Korea's most beautiful tourist sites, it is famed for being the easternmost mountain on Jeju, and thus the best spot on the island to see the first sunrise of the year.","elevation":182},
  "serengeti": {"article":"Serengeti","text":"The Serengeti is a geographical region in Africa, spanning the Mara and Arusha Regions of Tanzania and extending to southwestern Kenya. The protected area within the region includes approximately 30,000 km2 (12,000 sq mi) of land, including the Serengeti National Park and several game reserves. The Serengeti hosts one of the world's largest land animal migration (in terms of total body weight), which helps secure it as one of the Seven Natural Wonders of Africa."},
  "sergiev-posad": {"article":"Trinity Lavra of St. Sergius","text":"The Trinity Lavra of St. Sergius is a lavra and the most important Russian monastery, being the spiritual centre of the Russian Orthodox Church. The monastery is situated in the town of Sergiyev Posad, about 70 kilometres (43 mi) to the northeast from Moscow by the road leading to Yaroslavl, and currently is home to over 300 monks.","built":"1337"},
  "seville-giralda": {"article":"Giralda","text":"The Giralda is the bell tower of Seville Cathedral in Seville, Spain. It was built as the minaret for the Great Mosque of Seville in al-Andalus, during the reign of the Almohad dynasty, with a Renaissance-style belfry added by the Catholics after the expulsion of the Muslims from the area. The cathedral, including the Giralda, was registered in 1987 as a World Heritage Site by UNESCO, along with the Alcázar and the General Archive of the Indies.","built":"1198","height":104},
  "sewell": {"article":"Sewell, Chile","text":"Sewell is an uninhabited Chilean mining town located on the slopes of the Andes in the commune of Machalí in Cachapoal Province, Libertador General Bernardo O'Higgins Region, at an altitude of between 2,000 and 2,250 metres. In 2006, it was designated as a UNESCO World Heritage Site. It is known as a former company town, developed by Braden Copper Company for housing the workers (and their families) associated with the operations of El Teniente, the largest underground copper mine in the world.","elevation":2150},
  "sgang-gwaay": {"article":"Ninstints","text":"SG̱ang Gwaay Llnagaay (\"Red Cod Island\"), commonly known by its English name Ninstints, is a village site of the Haida people and part of the Gwaii Haanas National Park Reserve and Haida Heritage Site on Haida Gwaii on the North Coast of British Columbia, Canada. The village site is a UNESCO World Heritage Site, as well as Canadian National Historic Site and National Marine Conservation site."},
  "shakhrisyabz": {"article":"Ak-Saray Palace","text":"Ak-Saray Palace is a ruined palace and historic site in Shahrisabz, Uzbekistan. The palace was built at the beginning of the Timurid period, between 1380 and 1404, under the reign of Timur. In 2000, the palace was declared a UNESCO World Heritage Site.","built":"1380"},
  "shaolin": {"article":"Shaolin Monastery","text":"Shaolin Monastery, also known as Shaolin Temple, is a Mahayana Buddhist monastic institution associated with the development of Chan Buddhism and Shaolin kung fu. It is located at the foot of Wuru Peak of the Mount Song mountain range in Dengfeng, Zhengzhou prefecture, in Henan, China. The name reflects its location in the ancient grove of Mount Shaoshi, in the hinterland of the Mount Song range.","built":"AD 495"},
  "sheikh-safi": {"article":"Sheikh Safi al-Din Khānegāh and Shrine Ensemble","text":"Sheikh Safi al-Din Khānegāh and Shrine Ensemble is a Sufi khānegāh and shrine complex that contains the tomb of Sheikh Safi-ad-Din Ardabili. It is located in the city of Ardabil, in the province of Ardabil, Iran. In 2010, the religious funerary complex was added to the UNESCO World Heritage List. The mausoleum was added to the Iran National Heritage List on 6 January 1932 and is administered by the Cultural Heritage, Handicrafts and Tourism Organization of Iran.","built":"1334"},
  "sheikh-zayed-mosque": {"article":"Sheikh Zayed Grand Mosque","text":"The Sheikh Zayed Grand Mosque is a mosque located in Abu Dhabi, the capital city of the United Arab Emirates. It is the country's largest mosque, and is the key place of worship for daily Islamic prayers. There is a smaller replica of this mosque in Surakarta, a city in Indonesia. The Grand Mosque was constructed between 1994 and 2007 and was inaugurated in December 2007.","built":"2007","architects":["Yusef Abdelki"]},
  "sheki": {"article":"Palace of Shaki Khans","text":"The Palace of Shaki Khans in Shaki, northwestern Azerbaijan, is a historic monument that once served as the summer residence of the Shaki khans. It was constructed in 1797 under the rule of Muhammad Husayn Khan Mushtaq. The Palace of Shaki Khans was nominated for inclusion on the UNESCO World Heritage List in 1998 by Gulnara Mehmandarova, then President of the Azerbaijan Committee of the International Council on Monuments and Sites (ICOMOS).","built":"1762","height":10},
  "shibam": {"article":"Shibam","text":"Shibam, officially the Old Walled City of Shibam, is a town in Wadi Hadhramaut in eastern Yemen with about 7,000 inhabitants. It is the seat of the Shibam District in the Hadhramaut Governorate. It is known for its mudbrick-made high-rise buildings, with some of the buildings reaching as high as eleven stories. The design centred around protecting the residents of the city from Bedouin attacks.","built":"16th century","elevation":683},
  "shirakawa-go": {"article":"Historic Villages of Shirakawa-gō and Gokayama","text":"The Historic Villages of Shirakawa-gō and Gokayama are one of Japan's UNESCO World Heritage Sites. The cultural property consists of three historic mountain villages over an area of 68 hectares (170 acres) in the remote Shogawa river valley, stretching across the border of Gifu and Toyama Prefectures in central Japan. Shirakawa-gō is located in the village of Shirakawa in Gifu Prefecture."},
  "shore-temple": {"article":"Shore Temple","text":"The Shore Temple (c. 725 AD) is a complex of temples and shrines that overlooks the shore of the Bay of Bengal. It is located in Mahabalipuram, about 60 kilometres (37 mi) south of Chennai in Tamil Nadu, India. It is a structural temple, built with blocks of granite, dating from the 8th century AD. At the time of its creation, the site was a busy port during the reign of Narasimhavarman II of the Indian Pallava dynasty.","built":"AD 732"},
  "shuri-castle": {"article":"Shuri Castle","text":"Shuri Castle is a Ryukyuan gusuku castle in the historic Shuri district of Naha, the capital of Okinawa Prefecture, Japan. Between 1429 and 1879, it was the palace of the Ryukyu Kingdom, before becoming largely neglected. In 1945, during the Battle of Okinawa, it was almost completely destroyed. The site of Shuri Castle has been protected by the central government as a National Historic Site since 1972.","built":"14th century"},
  "shushtar": {"article":"Shoushtar Historical Hydraulic System","text":"The Shoushtar Historical Hydraulic System is a complex irrigation system of the island city Shoushtar from the Sasanian era. It consists of 13 dams, bridges, canals and structures which work together as a hydraulic system. Located in Iran's Khuzestan province, it was registered on UNESCO's list of World Heritage Sites in 2009 and is Iran's 10th cultural heritage site to be registered on the United Nations' list."},
  "sibenik": {"article":"Šibenik Cathedral","text":"The Cathedral of St. James or simply Šibenik Cathedral is a triple-nave Catholic cathedral with three apses and a dome (32 m high inside) in Šibenik, Croatia. It is the episcopal seat of the Diocese of Šibenik. It is often known as \"St. Jacob's\", because Croatian, like many other languages, uses the same name for both \"James\" and \"Jacob\".","built":"1431","architects":["Giorgio da Sebenico"]},
  "sidi-bou-said": {"article":"Sidi Bou Said","text":"Sidi Bou Saïd is a town in northern Tunisia, located about 20 km northeast of the capital, Tunis. Named after the religious figure Abu Said al-Baji, it was formerly known as Jbel el-Menar. The town is a popular tourist destination, celebrated for its distinctive blue-and-white architecture. It is accessible via the TGM train line, which runs from Tunis to La Marsa.","elevation":98},
  "siena": {"article":"Piazza del Campo","text":"Piazza del Campo is the main public space of the historic center of Siena, a city in Tuscany, Italy. Its name comes from the Italian word campanilismo, which translates to \"local pride\" and campanile \"bell tower.\" The campo is regarded as one of Europe's greatest medieval squares. It is renowned worldwide for its beauty and architectural integrity."},
  "sigatoka-dunes": {"article":"Sigatoka Sand Dunes","text":"The Sigatoka Sand Dunes are located directly west of the mouth of the Sigatoka River, about 3 kilometres (1.9 mi) west of the town of Sigatoka on the island of Viti Levu in Fiji. The dune system extends over an area of 650 hectares (1,600 acres), with almost half being within Sigatoka Sand Dunes National Park."},
  "sighisoara": {"article":"Sighișoara","text":"Sighișoara is a city on the Târnava Mare River in Mureș County, central Romania. Located in the historic region of Transylvania, Sighișoara had a population of 23,927 according to the 2021 census. It is a popular tourist destination for its well-preserved old town, which is listed by UNESCO as a World Heritage Site since 1999.","built":"1224","elevation":380},
  "sigiriya": {"article":"Sigiriya","text":"Sigiriya or Sinhagiri is an ancient rock fortress located in the northern Matale District near the town of Dambulla in the Central Province, Sri Lanka. It is a site of historical and archaeological significance that is dominated by a massive column of granite approximately 180 m (590 ft) high. According to the ancient Sri Lankan chronicle the Cūḷavaṃsa, this area was a large forest, then after storms and landslides it became a hill and was selected by King Kashyapa (CE 477–495) for his new capital.","height":180},
  "simien-mountains": {"article":"Simien Mountains","text":"The Simien Mountains, in northern Ethiopia, northeast of Gondar in Amhara Region, are part of the Ethiopian Highlands. They are a World Heritage Site (since 1978) and are part of the Simien Mountains National Park. The mountains consist of plateaus separated by valleys and rising to pinnacles. The highest Ethiopian mountain is Ras Dejen at 4,550 m with the second highest peak of Kidis Yared at 4,453 m; other peaks include Mount Biuat at 4,437 m.","elevation":4550},
  "skara-brae": {"article":"Heart of Neolithic Orkney","text":"Heart of Neolithic Orkney is a group of Neolithic monuments on the Mainland of the Orkney Islands, Scotland. The name was adopted by UNESCO when it proclaimed these sites as a World Heritage Site on 2 December 1999."},
  "skellig-michael": {"article":"Skellig Michael","text":"Skellig Michael, also called Great Skellig, is a twin-pinnacled crag 11.6 kilometres (7.2 mi) west of the Iveragh Peninsula in County Kerry, Ireland. Its twin island, Little Skellig (Sceilg Bheag), is smaller and inaccessible. The two islands were formed c. 374–360 million years ago during a period of mountain formation, along with the local MacGillycuddy's Reeks mountain range.","elevation":218},
  "skogskyrkogarden": {"article":"Skogskyrkogården","text":"Skogskyrkogården is a cemetery located in the Gamla Enskede district south of central Stockholm, Sweden. It was inaugurated in 1920 and was inscribed on the UNESCO World Heritage List in 1994. Its design, by Gunnar Asplund and Sigurd Lewerentz, reflects the development of architecture from Nordic Classicism to mature functionalism.","built":"1915","architects":["Gunnar Asplund"]},
  "socotra": {"article":"Socotra","text":"Socotra locally known as Saqatri, is a Yemeni island in the Indian Ocean. It is situated between the Gulf of Aden, the Guardafui Channel and the Arabian Sea, and lies near major shipping routes. The largest of the six islands in the Socotra archipelago, it comprises around 95% of the landmass of the archipelago. It lies 380 kilometres (205 nautical miles) south of the Arabian Peninsula and 232 km (125 nmi) east of the Horn of Africa.","elevation":1503},
  "soltaniyeh": {"article":"Soltaniyeh","text":"Soltaniyeh is a city in the Central District of Soltaniyeh County, Zanjan province, Iran, serving as capital of both the county and the district.","elevation":1784},
  "soufriere-hills": {"article":"Soufrière Hills","text":"The Soufrière Hills is an active, complex stratovolcano with many lava domes forming its summit on the Caribbean island of Montserrat, an overseas territory of the United Kingdom. After a long period of dormancy, the Soufrière Hills volcano became active in 1995 and continued to erupt until 2010. Its last eruption was in 2013.","elevation":1050},
  "sousse": {"article":"Medina of Sousse","text":"The Medina of Sousse is a Medina quarter in Sousse, Governorate of Sousse, Tunisia. Designated by the UNESCO a World Heritage Site in 1988, it is a typical example of the architecture of the early centuries of Islam in Maghreb. It encompasses a Kasbah, fortifications and the Great Mosque of Sousse. The Medina today houses the Archaeological Museum of Sousse."},
  "spa": {"article":"Spa, Belgium","text":"Spa is a municipality and city of Wallonia in the province of Liège, Belgium, whose name became an eponym for mineral baths with supposed curative properties. It is in a valley in the Ardennes mountains 35 km (22 mi) south-east of Liège and 45 km (28 mi) south-west of Aachen. In 2006, Spa had a population of 10,543 and an area of 39.85 km2 (15.39 sq mi), giving a population density of 265/km2 (690/sq mi)."},
  "spasskaya-tower": {"article":"Spasskaya Tower","text":"The Spasskaya Tower, also translated as the Saviour Tower, is the main tower on the eastern wall of the Moscow Kremlin which overlooks Red Square.","built":"1491","height":71,"architects":["Pietro Antonio Solari"]},
  "speicherstadt": {"article":"Speicherstadt","text":"The Speicherstadt in Hamburg, Germany, is the largest warehouse district in the world where the buildings stand on timber-pile foundations—oak logs, in this particular case. It is located in the port of Hamburg, in the HafenCity quarter, and was built from 1883 to 1927. The district was built as a free zone to transfer goods without paying customs.","built":"1927","architects":["Carl Johann Christian Zimmermann"]},
  "speyer-cathedral": {"article":"Speyer Cathedral","text":"Speyer Cathedral, officially the Imperial Cathedral Basilica of the Assumption and St Stephen, in Latin: Domus sanctae Mariae Spirae is a historical religious building in Speyer, Germany. It is the seat of the Roman Catholic Bishop of Speyer and is suffragan to the Roman Catholic Archdiocese of Bamberg. The cathedral, which is dedicated to St.","built":"1080","architects":["Otto of Bamberg"]},
  "spis-castle": {"article":"Spiš Castle","text":"The ruins of Spiš Castle in eastern Slovakia form one of the six largest castle sites in Slovakia. The castle is situated above the town of Spišské Podhradie and the village of Žehra, in the region known as Spiš. It was included in the UNESCO list of World Heritage Sites in 1993 (together with the adjacent locations of Spišská Kapitula and Žehra).","built":"12th century","elevation":610},
  "st-catherines": {"article":"Saint Catherine's Monastery","text":"Saint Catherine's Monastery, officially the Sacred Autonomous Royal Monastery of Saint Catherine of the Holy and God-Trodden Mount Sinai, is a Christian monastery located in the Sinai Peninsula of Egypt. Located at the foot of Mount Sinai, it was built between 548 and 565, and is the world's oldest continuously inhabited Christian monastery.","elevation":1570},
  "st-gall": {"article":"Abbey of Saint Gall","text":"The Abbey of Saint Gall is a dissolved abbey (747–1805) in a Catholic religious complex in the city of St. Gallen in Switzerland. The Carolingian-era monastery existed from 719, founded by Saint Othmar on the spot where Saint Gall had erected his hermitage. It became an independent principality between 9th and 13th centuries, and was for many centuries one of the chief Benedictine abbeys in Europe.","built":"AD 720"},
  "st-george-bermuda": {"article":"Historic Town of St George and Related Fortifications, Bermuda","text":"The Historic Town of St George and Related Fortifications is the name used by the United Nations Educational, Scientific and Cultural Organization's (UNESCO) World Heritage Committee to identify collectively as a World Heritage Site St. George's Town, founded in 1612 (following the 1609 wreck on Bermuda's reefs of the Sea Venture), and a range of fortifications, batteries, and magazines built between 1612 and 1939, the last of which was removed from use in 1953."},
  "st-peters": {"article":"St. Peter's Basilica","text":"The Papal Basilica of Saint Peter in the Vatican, or simply St. Peter's Basilica, is a church of the Italian Renaissance located in Vatican City, an independent microstate enclaved within the city of Rome, Italy. It was initially planned in the 15th century by Pope Nicholas V and then Pope Julius II to replace the ageing Old St.","built":"1506","height":137,"architects":["Michelangelo","Giuliano da Sangallo","Donato Bramante"]},
  "st-stephens": {"article":"St. Stephen's Cathedral, Vienna","text":"St. Stephen's Cathedral is a Roman Catholic church in Vienna, Austria, and the mother church of the Archdiocese of Vienna. It is the seat of the Archbishop of Vienna, Josef Grünwidl. The current Romanesque and Gothic form of the cathedral, seen today in the Stephansplatz, was largely initiated by Duke Rudolf IV (1339–1365) and stands on the ruins of two earlier churches, the first a parish church consecrated in 1147.","built":"1137","height":136},
  "st-thaddeus": {"article":"Monastery of Saint Thaddeus","text":"The Monastery of Saint Thaddeus is an Armenian monastery in a mountainous area of West Azerbaijan province, Iran. Although much of the present structure was erected by Crown Prince Abbas Mirza in 1811, the monastery is one of the oldest church buildings in the world. Also known as Kare Kilisa, this historic site is located approximately 20 kilometers from the town of Chaldiran in Iran, in the region historically referred to as Ancient Armenia in the East.","built":"7th century"},
  "statue-of-liberty": {"article":"Statue of Liberty","text":"The Statue of Liberty (Liberty Enlightening the World, French: La Liberté éclairant le monde) is a colossal neoclassical sculpture of a robed and crowned woman located on Liberty Island, part of New York City, in New York Harbor. The copper-clad statue, a gift to the United States from the people of France, was designed by French sculptor Frédéric Auguste Bartholdi, and its metal framework built by Gustave Eiffel.","built":"1886","height":46,"architects":["Eugène Viollet-le-Duc"]},
  "stingray-city": {"article":"Stingray City, Grand Cayman","text":"Stingray City is a series of shallow sandbars found in the North Sound of Grand Cayman, Cayman Islands. It is a tourist attraction, where southern stingrays are found in abundance and visitors can pet and interact with the animals. There are two sandbars, one which is in the shallows and the other one which is deeper and where it is possible to dive with stingrays."},
  "stoclet-house": {"article":"Stoclet Palace","text":"The Stoclet Palace, also known as the Stoclet House, is a historic mansion in Woluwe-Saint-Pierre, a municipality of Brussels, Belgium. It was designed by the Austrian-Moravian architect Josef Hoffmann for the Belgian financier Adolphe Stoclet, and built between 1905 and 1911, in the Vienna Secession style. It is located at 279–281, avenue de Tervueren/Tervurenlaan, bordering the Square Léopold II/Leopold II-plein.","built":"1905","architects":["Josef Hoffmann"]},
  "stone-spheres": {"article":"Stone spheres of Costa Rica","text":"The stone spheres of Costa Rica are an assortment of over 300 petrospheres in Costa Rica, on the Diquís Delta and on Isla del Caño. Locally, they are also known as bolas de piedra. The spheres are commonly attributed to the extinct Diquís culture, and they are sometimes referred to as the Diquís spheres. They are the best-known stone sculptures of the Isthmo-Colombian area."},
  "stone-town": {"article":"Stone Town","text":"The Stone Town of Zanzibar, also known as Mji Mkongwe (Swahili for 'old town'), is the old part of Zanzibar City, the main city of Zanzibar, in Tanzania. The newer portion of the city is known as Ng'ambo, Swahili for 'the other side'. Stone Town is located on the western coast of Unguja, the main island of the Zanzibar Archipelago."},
  "stonehenge": {"article":"Stonehenge","text":"Stonehenge is a prehistoric megalithic structure on Salisbury Plain in Wiltshire, England, two miles (3 km) west of Amesbury. It consists of an outer ring of vertical sarsen standing stones, each around 13 feet (4.0 m) high, seven feet (2.1 m) wide, and weighing around 25 tons, topped by connecting horizontal lintel stones which are held in place with mortise and tenon joints—a feature unique among contemporary monuments.","built":"30th century BC"},
  "stralsund": {"article":"Stralsund","text":"Stralsund, officially the Hanseatic City of Stralsund, is the fifth-largest city in the northeastern German state of Mecklenburg-Western Pomerania after Rostock, Schwerin, Neubrandenburg and Greifswald, and the second-largest city in the Pomeranian part of the state. It is located on the southern coast of the Strelasund, a sound of the Baltic Sea separating the island of Rügen from the Pomeranian mainland.","built":"1234","elevation":9},
  "strasbourg": {"article":"Strasbourg Cathedral","text":"Strasbourg Cathedral or the Cathedral of Our Lady of Strasbourg, is a Catholic cathedral in Strasbourg, Alsace, France. Although considerable parts of it are still in Romanesque architecture, it is widely considered to be among the finest examples of Rayonnant Gothic architecture. Architect Erwin von Steinbach is credited for major contributions from 1277 to his death in 1318, and beyond through his son Johannes von Steinbach, and his grandson Gerlach von Steinbach, who succeeded him as chief architects.","built":"1015","height":142,"architects":["Erwin von Steinbach","Johannes von Steinbach","Johannes Gerlach"]},
  "stromboli": {"article":"Stromboli","text":"Stromboli is an island in the Tyrrhenian Sea, off the north coast of Sicily, containing Mount Stromboli, one of the four active volcanoes in Italy. It is one of the seven Aeolian Islands, a volcanic arc north of Sicily, and the mythological home of Aeolus. The island, with an area of 12.6 square kilometres (4.9 sq mi), represents the upper third of the volcano.","elevation":926},
  "studenica": {"article":"Studenica Monastery","text":"The Studenica Monastery is a 12th-century Serbian Orthodox monastery situated 39 kilometres (24 mi) southwest of Kraljevo and 40.9 kilometres (25.4 mi) east of Ivanjica, in central Serbia. Studenica Monastery is a major monument of medieval architecture. Studenica was declared a Monument of Culture of Exceptional Importance in 1979, and is protected by the state.","built":"1186"},
  "stupinigi": {"article":"Palazzina di caccia of Stupinigi","text":"The Palazzina di caccia of Stupinigi (Italian for 'hunting residence' of Stupinigi) is one of the Residences of the Royal House of Savoy in the Metropolitan City of Turin in northern Italy, part of the UNESCO World Heritage Sites list. Built as a royal hunting lodge in the early 18th century, it is located in Stupinigi, a suburb (italian frazione) of the town of Nichelino, 10 km (6 mi) southwest of Turin.","architects":["Filippo Juvarra"]},
  "sukhothai": {"article":"Sukhothai Historical Park","text":"Sukhothai Historical Park covers the ruins of Sukhothai, literally 'dawn of happiness', capital of the Sukhothai Kingdom in the 13th and 14th centuries, in north central Thailand. It is near the city of Sukhothai Thani, capital of Sukhothai province. The city's walls form a rectangle about 2 km (1.2 mi) east-west by 1.6 km (0.99 mi) north-south."},
  "sukur": {"article":"Sukur","text":"Sukur or Sukur Cultural Landscape is a UNESCO World Heritage Site located on a hill above the village of Sukur in the Adamawa State of Nigeria. It is situated in the Mandara Mountains, close to the border with Cameroon. Its UNESCO inscription is based on the cultural heritage, material culture, and the naturally-terraced fields."},
  "summer-palace": {"article":"Summer Palace","text":"The Summer Palace or Yihe Garden consists of a vast ensemble of lakes, gardens and palaces located in Beijing. An imperial garden during the Qing dynasty, it includes Longevity Hill, Kunming Lake, and Seventeen-Arch Bridge. It covers an expanse of 2.9 square kilometres (1.1 sq mi), three-quarters of which is water. Longevity Hill is about 60 metres (200 ft) high and has many buildings positioned in sequence."},
  "sundarbans": {"article":"Sundarbans","text":"Sundarbans is a mangrove forest area in the Ganges Delta formed by the confluence of the Ganges, Brahmaputra and Meghna Rivers in the Bay of Bengal. It spans the area from the Hooghly River in India's state of West Bengal to the Baleswar River in Bangladesh's Khulna Division. It comprises closed and open mangrove forests, land used for agricultural purpose, mudflats and barren land, and is intersected by multiple tidal streams and channels."},
  "suomenlinna": {"article":"Suomenlinna","text":"Suomenlinna, or Sveaborg, is a sea fortress composed of eight islands, of which six have been fortified. Located about four kilometres (2.5 mi) southeast of the city center of Helsinki, Finland, Suomenlinna is a popular destination for both tourists and locals, who enjoy it as a picturesque picnic site. Construction of the fortress began in 1748 under the Swedish Crown as a defense against Russia.","built":"1748"},
  "susa": {"article":"Susa","text":"Susa was an ancient city in the lower Zagros Mountains about 250 km (160 mi) east of the Tigris, between the Karkheh and Dez Rivers in Iran. It represents the current city of Shush, located on the site of ancient Susa. One of the most important cities of the Ancient Near East, Susa served as the capital of Elam and the winter capital of the Achaemenid Empire, and remained a strategic centre during the Parthian and Sasanian periods.","built":"4000 BC"},
  "suzhou-gardens": {"article":"Classical Gardens of Suzhou","text":"The Classical Gardens of Suzhou are a group of gardens in the city of Suzhou, in Jiangsu, China, that are on the UNESCO World Heritage List. Spanning a period of almost one thousand years, from the Northern Song to the late Qing dynasties (11th-19th century), these gardens, most of them built by scholars, standardized many of the key features of classical Chinese garden design with constructed landscapes mimicking natural scenery of rocks, hills and rivers with strategically located pavilions and pagodas."},
  "svaneti-towers": {"article":"Svan towers","text":"Svan towers refers to the tower houses built as defensive dwellings in the Georgian historical region of Svaneti (present-day Samegrelo-Zemo Svaneti). These towers are unique to the region and were primarily built between the 9th and 12th centuries, during the Georgian Golden Age. However, the origins of the tower likely date back to prehistory."},
  "sydney-harbour-bridge": {"article":"Sydney Harbour Bridge","text":"The Sydney Harbour Bridge is a steel through arch bridge in Sydney, New South Wales, Australia, spanning Sydney Harbour from the central business district (CBD) to the North Shore. The view of the bridge, the harbour, and the nearby Sydney Opera House is widely regarded as an iconic image of Sydney, and of Australia itself.","built":"1932","height":134},
  "sydney-opera-house": {"article":"Sydney Opera House","text":"The Sydney Opera House is a multi-venue performing arts centre in Sydney, New South Wales, Australia. Located on the foreshore of Sydney Harbour, it is widely regarded as one of the world's most famous and distinctive buildings, and a masterpiece of 20th-century architecture. Designed by Danish architect Jørn Utzon and completed by an Australian architectural team headed by Peter Hall, the building was formally opened by Queen Elizabeth II on 20 October 1973, 16 years after Utzon's 1957 selection as winner of an international design competition.","built":"1973","height":67,"architects":["Jørn Utzon","Peter Hall"]},
  "syracuse": {"article":"Greek Theatre of Syracuse","text":"The Greek theatre of Syracuse lies on the south slopes of the Temenite hill, overlooking the modern city of Syracuse in southeastern Sicily, Italy. It was first built in the 5th century BC, rebuilt in the 3rd century BC and renovated again in the Roman period. Today, it is a part of the UNESCO World Heritage Site of \"Syracuse and the Rocky Necropolis of Pantalica\".","built":"4th century"},
  "table-mountain": {"article":"Table Mountain","text":"Table Mountain is a flat-topped mountain forming a prominent landmark overlooking the city of Cape Town in South Africa. It is a significant tourist attraction, with many visitors either using the cableway or hiking to the top. The mountain has 2,285 plant species, of which around 80% are fynbos (Afrikaans for 'fine bush').","elevation":1085},
  "tabriz-bazaar": {"article":"Bazaar of Tabriz","text":"The Bazaar of Tabriz is a historic market in central Tabriz, Iran. It is one of the oldest bazaars in the Middle East and one of Iran's UNESCO World Heritage Sites.","built":"18th century"},
  "taj-mahal": {"article":"Taj Mahal","text":"The Taj Mahal is an ivory-white marble mausoleum on the right bank of the river Yamuna in Agra, Uttar Pradesh, India. It was commissioned in 1631 by the fifth Mughal emperor, Shah Jahan (r. 1628–1658), to house the tomb of his late wife, Mumtaz Mahal; it also houses the tomb of Shah Jahan himself. The tomb is the centrepiece of a 17-hectare (42-acre) complex, which includes a mosque and a guest house, and is set in formal gardens bounded on three sides by a crenellated wall.","built":"1631","height":73,"architects":["Ahmad Lahori"]},
  "takht-e-soleyman": {"article":"Takht-e Soleymān","text":"Takht-e Soleymān is an archaeological site in West Azerbaijan, Iran dating back to the Sasanian Empire. It lies midway between Urmia and Hamadan, very near the present-day town of Takab, and 400 km (250 mi) west of Tehran. The fortified site, which is located on a hill created by the outflow of a calcium-rich spring pond, was recognized as a World Heritage Site in July 2003.","built":"5th century BC","elevation":2200},
  "takht-i-bahi": {"article":"Takht-i-Bahi","text":"Takht-i-Bahi, is an Indo-Parthian archaeological site of an ancient Buddhist monastery in Mardan, Khyber-Pakhtunkhwa, Pakistan. The site is considered among the most important relics of Buddhism in all of what was once Gandhara. The monastery was founded in the 1st century CE, and was in use until the 7th century. The complex is regarded by archaeologists as being particularly representative of the architecture of Buddhist monastic centers from its era."},
  "talayotic-menorca": {"article":"Naveta d'Es Tudons","text":"The Naveta d'Es Tudons, or Naveta of Es Tudons, is the most remarkable megalithic chamber tomb in the Balearic island of Menorca, Spain. It is located in the Western part of the island, on the Ciutadella de Menorca-Mahón road, approximately 3 miles out from Ciutadella, and 200 m south of the road. It stands on slightly rising ground in a sloping valley.","built":"1000 BC"},
  "tallinn": {"article":"Tallinn Old Town","text":"Tallinn Old Town is the oldest part of Tallinn, Estonia. Old Town of Tallinn has managed to wholly preserve its structure of medieval and Hanseatic origin. Old Town represents an exceptionally intact 13th century city plan. Since 1997, the area has been registered in the UNESCO World Heritage List. The old town is bordered by the Walls of Tallinn."},
  "taos-pueblo": {"article":"Taos Pueblo","text":"Taos Pueblo, also called the Pueblo of Taos, Pueblo de Taos, or Teotho, is an ancient Tiwa-speaking Pueblo inhabited by the Taos people. The Pueblo is one of the 575 federally-recognized Native American governments in the United States, and a UNESCO World Heritage Site. Taos Pueblo is the oldest continuously inhabited city in the United States and is the only U.S."},
  "taputapuatea": {"article":"Taputapuatea","text":"Taputapuātea is a commune of French Polynesia, an overseas territory of France in the Pacific Ocean. The commune of Taputapuātea is located on the island of Raiatea, in the administrative subdivision of the Leeward Islands, themselves part of the Society Islands. At the 2022 census it had a population of 5,007. The commune was named after a large marae complex which was the religious center of eastern Polynesia for roughly 1000 years."},
  "taroko": {"article":"Taroko National Park","text":"Taroko National Park is one of the nine national parks in Taiwan and was named after the Taroko Gorge, the landmark gorge of the park carved by the Liwu River. The park spans Taichung Municipality, Nantou County, and Hualien County and is located in Xiulin Township. The Taroko Gorge forms one of only three river-carved gorges in the world cut entirely through pure marble, ranking alongside Bhedaghat Gorge in Jabalpur, India and Trigrad Gorge in Bulgaria.","built":"1986"},
  "tarraco": {"article":"Tarragona Amphitheatre","text":"The Roman Amphitheatre of Tarraco is a Roman amphitheatre in the Roman colonia of Tarraco –present-day Tarragona, Spain–, capital of the Roman province of Hispania Tarraconensis. It was built in the 2nd century AD near the local forum. It measured 130 by 102 metres (427 ft × 335 ft), and it could house up to 15,000 spectators."},
  "taxila": {"article":"Taxila","text":"Taxila, historically known as Takṣaśilā, is a city and a World Heritage Site in the Rawalpindi District of Punjab, Pakistan. Founded around c. 1000 BC, it is one of the oldest cities in Asia, and has a population of over 136,900 as of 2023. Situated on the eastern bank of the Indus River — the pivotal junction of the South Asia and Central Asia — it was possibly founded around 1000 BCE."},
  "teatro-amazonas": {"article":"Amazon Theatre","text":"The Amazon Theatre is an opera house located in Manaus, Brazil. It is the location of the annual Festival Amazonas de Ópera (Amazonas Opera Festival) and the home of the Amazonas Philharmonic Orchestra which regularly rehearses and performs at the Amazon Theatre along with choirs, musical concerts and other performances.","built":"1896"},
  "teide": {"article":"Teide National Park","text":"Teide National Park is a national park located in Tenerife, Canary Islands, Spain. The national park is centered on Mount Teide, the highest mountain of Spain (3,718 meters high) in addition, the highest volcano in the Atlantic Ocean islands and the third highest volcano in the world from its base in the ocean floor (7.500 meters high).","built":"1954","elevation":2278},
  "telc": {"article":"Telč","text":"Telč is a town in Jihlava District in the Vysočina Region of the Czech Republic. It has about 5,100 inhabitants. The town is located in a hilly landscape in the Křižanov Highlands and is surrounded by a system of fishponds. The town's economy depends on tourism. Telč is known for its historic centre, which is protected as an urban monument reservation and is a UNESCO World Heritage Site.","built":"1099","elevation":514},
  "temple-of-confucius": {"article":"Temple and Cemetery of Confucius and the Kong Family Mansion in Qufu","text":"Temple and Cemetery of Confucius and the Kong Family Mansion in Qufu, Shandong Province of China, include Temple of Confucius, Cemetery of Confucius and the Kong Family Mansion. Since 1994, the Temple of Confucius has been part of the UNESCO World Heritage Site \"Temple and Cemetery of Confucius and the Kong Family Mansion in Qufu\"."},
  "temple-of-heaven": {"article":"Temple of Heaven","text":"The Temple of Heaven is a complex of imperial religious Confucian buildings situated in the southeastern part of central Beijing. The complex was visited by the Emperors of the Ming and then later restored by the Qing dynasties for annual ceremonies of prayer to Heaven for a good harvest and other seasonal rites."},
  "temple-of-the-tooth": {"article":"Temple of the Tooth","text":"Sri Dalada Maligawa, commonly known in English as the Temple of the Sacred Tooth Relic, is a Buddhist temple in Kandy, Sri Lanka. It is located in the Royal Palace Complex of the former Kingdom of Kandy, which houses the relic of the tooth of the Buddha. Since ancient times, the relic has played an important role in local politics because it is believed that whoever holds the relic holds the governance of the country.","built":"1595"},
  "teotihuacan": {"article":"Teotihuacan","text":"Teotihuacan is an ancient Mesoamerican city located in a sub-valley of the Valley of Mexico, which is located in the State of Mexico, 40 kilometers (25 mi) northeast of modern-day Mexico City. Teotihuacan is known today as the site of many of the most architecturally significant Mesoamerican pyramids built in the pre-Columbian Americas, namely the Pyramid of the Sun and the Pyramid of the Moon.","built":"180 BC"},
  "terracotta-army": {"article":"Terracotta Army","text":"The Terracotta Army is a collection of terracotta sculptures depicting the armies of Qin Shi Huang, the first emperor of China. It is a form of funerary art buried with the emperor in 210–209 BCE in his mausoleum with the purpose of protecting him in his afterlife. The figures, dating from approximately the late 200s BCE, were discovered in 1974 by local farmers in Lintong County, outside Xi'an, Shaanxi, China.","built":"248 BC"},
  "thaba-bosiu": {"article":"Thaba Bosiu","text":"Thaba Bosiu is a constituency and sandstone plateau with an area of approximately 2 km2 (0.77 sq mi) and a height of 1,804 meters above sea level. It is located between the Orange and Caledon Rivers in the Maseru District of Lesotho, 24 km east of the country's capital Maseru. It was once the capital of Lesotho, having been King Moshoeshoe's stronghold.","elevation":1804},
  "thang-long": {"article":"Imperial Citadel of Thăng Long","text":"The Imperial Citadel of Thăng Long is a complex of historic buildings associated with the history of Vietnam located in the centre of Hanoi, Vietnam. Its construction began in 1010 and was completed in early 1011 under the reign of Emperor Lý Thái Tổ of the Lý dynasty. Most of the existing structure is dated to the extensive reconstruction of the old Imperial Citadel ordered by Gia Long in 1805, but the Citadel (except for the North Gate and the Flag Tower) was largely demolished by the French to allow more land for offices and barracks."},
  "the-baths": {"article":"The Baths","text":"The Baths is a beach area on the island of Virgin Gorda among the British Virgin Islands in the Caribbean."},
  "thimlich-ohinga": {"article":"Thimlich Ohinga","text":"Thimlich Ohinga is a complex of stone-built ruins in Migori County in Kenya. It is the largest of 138 sites containing 521 stone structures that were built near Lake Victoria in Kenya. These sites are highly clustered. The main enclosure of Thimlich Ohinga has walls that are 1–3 m (3.3–9.8 ft) in thickness, and 1–4.2 m (3.3–13.8 ft) in height."},
  "thingvellir": {"article":"Þingvellir","text":"Þingvellir was the site of the Alþing, the annual parliament of Iceland from the year 930 until the last session held at Þingvellir in 1798. Since 1881, the parliament has been located within Alþingishúsið in Iceland's capital, Reykjavík. Þingvellir is now a national park in the municipality of Bláskógabyggð in southwestern Iceland, about 40 km (25 miles) northeast of Reykjavík. Þingvellir is a site of historical, cultural, and geological significance, and is one of the most popular tourist destinations in Iceland.","built":"1928","elevation":120},
  "tiananmen": {"article":"Tiananmen","text":"The Tiananmen, also Tian'anmen, is the entrance gate of the Forbidden City imperial palace complex and Imperial City in the center of Beijing, China. It is widely used as a national symbol. First built in 1420 during the Ming dynasty, Tiananmen was the entrance to the Emperor's residence, through which all visitors to the palace walked.","height":32},
  "tigers-nest": {"article":"Paro Taktsang","text":"Paro Taktsang is a sacred Vajrayana Himalayan Buddhist site located in the cliffside of the upper Paro valley in Bhutan. It is one of thirteen Tiger's Nest caves in which Padmasambhava practiced and taught Vajrayana. A later monastery complex was built in 1692 by the 4th Druk Desi Tenzin Rabgey around the Taktsang Senge Samdup cave, where Guru Padmasambhava meditated and practised with students, including Yeshe Tsogyal, before departing the kingdom of Tibet in the early 9th century.","built":"1692"},
  "tikal": {"article":"Tikal","text":"Tikal is the ruin of an ancient city, which was likely to have been called Yax Mutal, found in a rainforest in Guatemala. One of the largest archaeological sites and urban centers of the pre-Columbian Maya civilization, it is located in the archaeological region of the Petén Basin in what is now the Petén Department in northern Guatemala."},
  "timbuktu": {"article":"Timbuktu","text":"Timbuktu is a city in Mali, situated 20 kilometres (12 miles) north of the Niger River. It is the capital of the Tombouctou Region, one of the 19 administrative regions of Mali, with a population of around eighty-four thousand people in the 2023 census. Archaeological evidence suggests prehistoric settlements in the region, predating the city's Islamic scholarly and trade prominence in the medieval period.","elevation":261},
  "timgad": {"article":"Timgad","text":"Timgad or Thamugadi nicknamed the \"Pompeii of North Africa\", was a Roman city in the Aurès Mountains of Algeria. It was founded by the Roman Emperor Trajan around 100 CE. The full name of the city was Colonia Marciana Ulpia Traiana Thamugadi. Emperor Trajan named the city in commemoration of his mother Marcia, eldest sister Ulpia Marciana, and father Marcus Ulpius Traianus."},
  "tivoli": {"article":"Tivoli Gardens","text":"Tivoli Gardens, also known simply as Tivoli, is an amusement park and pleasure garden in Copenhagen, Denmark. The park opened on 15 August 1843 and is the second-oldest operating amusement park in the world, after Dyrehavsbakken in nearby Klampenborg, also in Denmark. With 4.25 million visitors in 2024, Tivoli is the most visited amusement park in Scandinavia and second-most popular seasonal amusement park in the world after Europa-Park.","built":"1843"},
  "tiwanaku": {"article":"Tiwanaku","text":"Tiwanaku is a Pre-Columbian archaeological site in western Bolivia, near Lake Titicaca, about 70 kilometers from La Paz, and it is one of the largest sites in South America. It is just north of another ancient building site, Qhunqhu Wankani. Surface remains currently cover around 4 square kilometers and include decorated ceramics, monumental structures, and megalithic blocks."},
  "tlacotalpan": {"article":"Tlacotalpan","text":"Tlacotalpan is a city in Tlacotalpan Municipality in the Mexican state of Veracruz, declared a World Heritage Site by UNESCO in 1998 primarily for its architecture and colonial-era layout. The town was established in 1550 on what was originally an island in the Papaloapan River. From the colonial era to the 20th century, it was an important port, one of few interior river ports in Latin America.","built":"1847","elevation":10},
  "toledo": {"article":"Toledo, Spain","text":"Toledo is a city and municipality in Spain. It is the capital of the province of Toledo and the de jure seat of the government and parliament of the autonomous community of Castilla–La Mancha. Toledo is primarily located on the right (north) bank of the Tagus in central Iberia, nestled in a bend of the river. Built on a previous Carpetanian settlement, Toledo developed into an important Roman city of Hispania, later becoming the capital of the Visigothic Kingdom and seat of a powerful archdiocese.","elevation":523},
  "tomar": {"article":"Convent of Christ (Tomar)","text":"The Convent of Christ of Tomar, also called Convent of Christ (Convento de Cristo) or Monastery of Christ (Mosteiro de Cristo), is a former Catholic convent in Tomar, Portugal. Originally a 12th-century Templar stronghold, when the order was dissolved in the 14th century the Portuguese branch was turned into the Knights of the Order of Christ, that later supported Portugal's maritime discoveries of the 15th century."},
  "tomb-of-askia": {"article":"Tomb of Askia","text":"The Tomb of Askia, in Gao, Mali, is believed to be the burial place of Askia Muhammad I, one of the Songhai Empire's most prolific emperors. It was built at the end of the fifteenth century and is designated as a UNESCO World Heritage Site. Although Askia Mohammed I is the only individual who was buried within the tomb, several other Askias are buried in the courtyard.","built":"1495","height":17},
  "tongariro": {"article":"Mount Tongariro","text":"Mount Tongariro is a compound volcano in the Taupō Volcanic Zone of the North Island of New Zealand. It is located 20 km (12 mi) to the southwest of Lake Taupō, and is the northernmost of the three active volcanoes that dominate the landscape of the central North Island.","elevation":1978},
  "torres-del-paine": {"article":"Cordillera Paine","text":"The Cordillera Paine is a group of mountains (a cordillera) in Torres del Paine National Park in Chilean Patagonia. It is 280 km (170 mi) north of Punta Arenas, and about 1,960 km (1,220 mi) south of the Chilean capital Santiago. The cordillera is part of the Commune of Torres del Paine in Última Esperanza Province of Magallanes and Antártica Chilena Region.","elevation":2884},
  "torun": {"article":"Medieval Town of Toruń","text":"Medieval Town of Toruń is the oldest historic district of the city of Toruń. It is one of Poland's World Heritage Sites (added in 1997) and Seven Wonders of Poland. According to UNESCO, its value lies in its being \"a small historic trading city that preserves to a remarkable extent its original street pattern and outstanding early buildings, and which provides an exceptionally complete picture of the medieval way of life\"."},
  "tournai": {"article":"Tournai Cathedral","text":"The Cathedral of Our Lady, or Tournai Cathedral, is a Roman Catholic cathedral, see of the Diocese of Tournai in Tournai, Belgium. It has been classified both as a Wallonia major heritage site since 1936 and as a World Heritage Site since 2000.","built":"12th century","height":83},
  "tower-bridge": {"article":"Tower Bridge","text":"Tower Bridge is a Grade I listed combined bascule, suspension, and, until 1960, cantilever bridge in London, built between 1886 and 1894, designed by Horace Jones and engineered by John Wolfe Barry with the help of Henry Marc Brunel. It crosses the River Thames close to the Tower of London and is one of five London bridges owned and maintained by the City Bridge Foundation, a charitable trust founded in 1282.","built":"1886","height":65,"architects":["Horace Jones"]},
  "tower-of-hercules": {"article":"Tower of Hercules","text":"The Tower of Hercules is an ancient Roman lighthouse in A Coruña, Galicia, Spain, overlooking the Atlantic coast. It is the only fully preserved Roman lighthouse still used for maritime signalling. Built in the late 1st century, the tower is located on a peninsula about 2.4 km (1.5 mi) from the centre of A Coruña, Galicia, in northwestern Spain.","built":"1st century","height":49},
  "tower-of-london": {"article":"Tower of London","text":"The Tower of London, officially His Majesty's Royal Palace and Fortress of the Tower of London, is a historic citadel and castle on the north bank of the River Thames in London, England. It lies within the London Borough of Tower Hamlets, which is separated from the eastern edge of the square mile of the City of London by the open space known as Tower Hill.","built":"1066"},
  "trakai": {"article":"Trakai Island Castle","text":"Trakai Island Castle is an island castle located in Trakai, Lithuania, on an island in Lake Galvė. The construction of the stone castle was begun in the 14th century by Kęstutis, and around 1409 major works were completed by his son Vytautas the Great, who died in this castle in 1430. Trakai was one of the main centers of the Grand Duchy of Lithuania and the castle held great strategic importance."},
  "trang-an": {"article":"Tràng An Scenic Landscape Complex","text":"Tràng An is a scenic area located in Ninh Bình Province, near Hoa Lư, Vietnam renowned for its boat cave tours. On 23 June 2014, at the 38th session of the World Heritage Committee in Doha, the Trang An Scenic Landscape Complex was inscribed as a UNESCO World Heritage Site. The Trang An Scenic Landscape Complex includes Hoa Lư and Tam Cốc/Bích Động."},
  "trevi-fountain": {"article":"Trevi Fountain","text":"The Trevi Fountain is an 18th-century fountain in the Trevi district in Rome, Italy, designed by Italian architect Nicola Salvi and completed by Giuseppe Pannini in 1762. Standing 26.3 metres (86 ft) high and 49.15 metres (161.3 ft) wide, it is the largest Baroque fountain in the world and one of the most famous fountains in the world.","built":"1732","height":26,"architects":["Nicola Salvi","Giuseppe Pannini"]},
  "trinidad-cuba": {"article":"Trinidad, Cuba","text":"Trinidad is a town in the province of Sancti Spíritus, central Cuba. Together with the nearby Valle de los Ingenios, it has been a UNESCO World Heritage Site since 1988, because of its historical importance as a center of the sugar trade in the 18th and 19th centuries. Trinidad is one of the best-preserved cities in the Caribbean from the time when the sugar trade was the main industry in the region.","built":"1514","elevation":60},
  "trinidad-mission": {"article":"La Santísima Trinidad de Paraná","text":"La Santísima Trinidad de Paraná, or the Most Holy Trinity of Paraná, is the name of a former Jesuit reduction in Paraguay. It is an example of one of the many Jesuit reductions, small colonies established by the missionaries in various locations in South America, such as Brazil, Argentina and Paraguay throughout the 17th and 18th century."},
  "triple-bridge": {"article":"The works of Jože Plečnik in Ljubljana – Human Centred Urban Design","text":"The works of Jože Plečnik in Ljubljana – Human Centred Urban Design is a UNESCO World Heritage Site in Ljubljana, Slovenia, listed in 2021. The site encompasses selected the most prominent works of Slovenian architect Jože Plečnik in Ljubljana with their original function. During the interwar period, Plečnik worked to transform Ljubljana from a provincial city to the capital of the Slovenian nation by creating a series of public spaces and public institutions and integrating them into the pre-existing urban fabric.","architects":["Jože Plečnik"]},
  "troodos": {"article":"Painted Churches in the Troodos Region","text":"The Painted Churches in the Troödos Region is a UNESCO World Heritage Site in the Troödos Mountains of central Cyprus. The complex comprises ten Byzantine churches and monasteries richly decorated with Byzantine and post-Byzantine murals: Church of Agios Nikolaos (St. Nicholas) tis Stegis in Kakopetria: An 11th-century monastery and the oldest surviving katholikon in Cyprus"},
  "troy": {"article":"Troy","text":"Troy or Ilion was an ancient city located in present-day Çanakkale, Turkey. It is best known as the setting for the Greek myth of the Trojan War. The modern-day archaeological site, also known as Hisarlık, is open to the public as a tourist destination, and was added to the UNESCO World Heritage list in 1998. Troy was repeatedly destroyed and rebuilt during its 4000 years of settlement.","built":"3000 BC"},
  "trulli": {"article":"Trullo","text":"A trullo (plural, trulli) is a traditional Apulian dry stone hut with a conical roof. Their style of construction is specific to the Itria Valley, in the Murge area of the Italian region of Apulia. Trulli were generally constructed as temporary field shelters and storehouses or as permanent dwellings by small proprietors or agricultural labourers."},
  "trunk-bay": {"article":"Trunk Bay","text":"Trunk Bay is a body of water and a beach on St. John in the United States Virgin Islands. Trunk Bay is part of the Virgin Islands National Park. Trunk Bay is named for the Leatherback turtle, which is endemic to the USVI and are locally known as trunks. The beach area is divided into two halves, the main Trunk Bay beach and swim area and Burgesman Cove which is located on the west end of Trunk Bay near Jumby Bay."},
  "tsingy": {"article":"Tsingy de Bemaraha Strict Nature Reserve","text":"Tsingy de Bemaraha Strict Nature Reserve is a nature reserve located near the western coast of Madagascar in Melaky Region. The area was listed as a UNESCO World Heritage Site in 1990 due to the unique geography, preserved mangrove forests, and wild bird and lemur populations.","built":"1991"},
  "two-lovers-point": {"article":"Two Lovers Point","text":"Two Lovers Point is a prominent cape and seaside cliff in Tamuning, Guam, that overlooks northern Tumon Bay and the Philippine Sea. One of four National Natural Landmarks on Guam, it is closely associated with the folktale of two doomed lovers and is a major tourist attraction. The Point is part of the limestone plateau that forms the northern part of Guam."},
  "tyre": {"article":"Tyre, Lebanon","text":"Tyre is a city in Lebanon, and one of the oldest continuously inhabited cities in the world. It was one of the earliest Phoenician metropolises and the legendary birthplace of Europa, her brothers Cadmus and Phoenix, and Carthage's founder Dido (Elissa). The city has many ancient sites, including the Tyre Hippodrome, and was added as a whole to the list of UNESCO World Heritage Sites in 1984.","built":"2750 BC","elevation":10},
  "uluru": {"article":"Uluru","text":"Uluru, also known as Ayers Rock and officially gazetted as Uluru / Ayers Rock, is a large sandstone monolith. It crops out near the centre of Australia in the southern part of the Northern Territory, 335 km (208 mi) south-west of Alice Springs. Uluru is sacred to the Pitjantjatjara, the Aboriginal people of the area, one of the groups collectively known as the Aṉangu.","elevation":863},
  "umayyad-mosque": {"article":"Old city of Damascus","text":"The old city of Damascus is the historic city centre of Damascus, Syria. The old city, which is one of the oldest continuously inhabited cities in the world, contains numerous archaeological sites, including some historical churches and mosques. Many cultures have left their mark, especially Hellenistic, Roman, Byzantine and Islamic."},
  "umm-er-rasas": {"article":"Umm ar-Rasas","text":"Umm ar-Rasas is located 30 km southeast of Madaba in the Amman Governorate in central Jordan. It was once accessible by branches of the King's Highway, and is situated in the semi-arid steppe region of the Jordanian Desert. The site has been associated with the biblical settlement of Mephaat mentioned in the Book of Jeremiah."},
  "unam": {"article":"Ciudad Universitaria, Mexico City","text":"Ciudad Universitaria (University City) is the main campus of the National Autonomous University of Mexico (UNAM), located in Coyoacán borough in the southern part of Mexico City. Designed by architects Mario Pani and Enrique del Moral, it encloses the Olympic Stadium, about 40 faculties and institutes, the Cultural Center, an ecological reserve, the Central Library, the National Library of Mexico and a few museums.","built":"1954","architects":["Mario Pani","Enrique del Moral"]},
  "underground-river": {"article":"Puerto Princesa Subterranean River National Park","text":"The Puerto Princesa Subterranean River National Park is a protected area in the Philippines. The park is located in the Saint Paul Mountain Range on the western coast of the island of Palawan, about 80 kilometers (50 mi) north of the city of Puerto Princesa, and contains the Puerto Princesa Subterranean River (also known as the Puerto Princesa Underground River or just Underground River).","built":"1999"},
  "urbino": {"article":"Ducal Palace, Urbino","text":"The Ducal Palace is a Renaissance building in the Italian city of Urbino in the Marche. One of the most important monuments in Italy, it's been listed as a UNESCO World Heritage Site since 1998.","built":"1472","architects":["Luciano Laurana","Francesco di Giorgio","Maso di Bartolomeo"]},
  "urnes-stave-church": {"article":"Urnes Stave Church","text":"Urnes Stave Church is a 12th-century stave church at Ornes, along the Lustrafjorden, in Luster Municipality in Vestland county, Norway. The church sits on the eastern side of the fjord, directly across the fjord from the village of Solvorn and about five kilometres (3 mi) east of the village of Hafslo. It is among the oldest stave churches in Norway, with parts of the lumber construction dating from the latter half of the 11th century.","built":"12th century"},
  "uxmal": {"article":"Uxmal","text":"Uxmal is an ancient Maya city of the classical period located in present-day Mexico. It is considered one of the most important archaeological sites of Maya culture, along with Palenque, Chichen Itza and Calakmul in Mexico, Caracol and Xunantunich in Belize, and Tikal in Guatemala. It is located in the Puuc region of the western Yucatán Peninsula, and is considered one of the Maya cities most representative of the region's dominant architectural style."},
  "vaduz-castle": {"article":"Vaduz Castle","text":"Vaduz Castle is the palace and official residence of the Prince of Liechtenstein. The castle gave its name to the town of Vaduz, the capital of Liechtenstein, which it overlooks from an adjacent old hilltop."},
  "vall-de-boi": {"article":"Sant Climent, Taüll","text":"Sant Climent de Taüll, also known as the Church of St. Clement of Tahull, is a Roman Catholic church in Catalonia, Spain. It is an example of Romanesque architecture. Other influences include the Lombard and Byzantine styles, which can be seen throughout the exterior and interior of the building. The church is a basilica plan structure with three naves, each of them with a terminal apse, and large columns separating the side naves."},
  "vallee-de-mai": {"article":"Vallée de Mai","text":"Vallée de Mai Nature Reserve (\"May Valley\") is a nature park on the island of Praslin in the Seychelles. It consists of a well-preserved palm forest, flagship species made up of the island endemic coco de mer, as well as five other endemic palms. In 1983, it was inscribed as a UNESCO World Heritage Site, ranking as one of the world's smallest natural properties on the list at just 19.5 hectares (48 acres).","built":"1966"},
  "valletta": {"article":"Valletta","text":"Valletta, also known as Città Umilissima (transl. the Humblest City), is the capital city of Malta and one of its 68 council areas. Located between the Grand Harbour to the east and Marsamxett Harbour to the west, its population as of 2021 was 5,157. As Malta's capital city, it is a commercial centre for shopping, bars, dining, and café life.","built":"1566","elevation":56},
  "valparaiso": {"article":"Valparaíso","text":"Valparaíso is a major city, commune, seaport, and naval base facility in the Valparaíso Region of Chile. Valparaíso was originally named after Valparaíso de Arriba, in Castile-La Mancha, Spain. With a population of 284,938, it is the 10th-largest commune in Chile. Greater Valparaíso is the second-most populous metro area in the country.","built":"1536","elevation":21},
  "van-nelle": {"article":"Van Nelle Factory","text":"The former Van Nelle Factory on the Schie in Rotterdam, is considered a prime example of the modernist and functionalist architecture. It has been a designated UNESCO World Heritage Site since 2014. Soon after it was built, prominent architects described the factory as \"the most beautiful spectacle of the modern age\" (Le Corbusier in 1932) and \"a poem in steel and glass\" (Robertson in 1930).","built":"1931","architects":["Brinkman & Van der Vlugt","Michiel Brinkman","Jo van den Broek"]},
  "vatnajokull": {"article":"Vatnajökull","text":"Vatnajökull is the largest and most voluminous ice cap in Iceland, and the second largest in area in Europe after the Severny Island ice cap of Novaya Zemlya. It is in the south-east of the island, covering approximately 8% of the country."},
  "venice": {"article":"Venice","text":"Venice is a coastal city in northeastern Italy and the capital of the region of Veneto, as well as the Metropolitan City of Venice. It is built on a group of 126 islands that are separated by expanses of open water and by canals; portions of the city are linked by 472 bridges. The islands are in the shallow Venetian Lagoon, an enclosed bay lying between the mouths of the Po and the Piave rivers (more exactly between the Brenta and the Sile).","built":"AD 421","elevation":2},
  "veresk-bridge": {"article":"Trans-Iranian Railway","text":"The Trans-Iranian Railway was a major railway building project started in Pahlavi Iran in 1927 and completed in 1938, under the direction of the then-Iranian monarch Reza Shah. It was entirely built with indigenous capital, and links the capital Tehran with Bandar Shahpur (now: Bandar-e Emam Khomeyni) on the Persian Gulf in the south and Bandar Shah (now: Bandar Torkaman) on the Caspian Sea in the north, via Ahvaz and Qom.","built":"1938"},
  "verla": {"article":"Verla","text":"Verla at Jaala, Kouvola, Finland, is a well-preserved 19th-century mill village. Situated along the northern Kymi River, the mill, nearby power plants, and residential houses were inscribed on the UNESCO World Heritage List in 1996 due to its testimony to the lumber industry in the 19th century and the lives of the industrial workers of that time."},
  "verona-arena": {"article":"Verona Arena","text":"The Verona Arena is a Roman amphitheatre located in the historic center of Verona, Italy. It is among the best-preserved ancient amphitheatres to have survived into the modern era. This remarkable state of preservation is largely due to systematic restoration efforts that began in the 16th century. During the summer months, the Arena hosts the Arena di Verona Festival, with opera seasons that have run uninterrupted except by wars since 1913.","built":"AD 30","height":31},
  "versailles": {"article":"Palace of Versailles","text":"The Palace of Versailles is a château and historic monument in Versailles in the Yvelines department of France, southwest of Paris. It served as the principal residence of the French kings Louis XIV, Louis XV, and Louis XVI. The king, the court, and the royal government lived there permanently from 6 May 1682 until 6 October 1789, except during the Regency years (1715–1723).","built":"1661","architects":["Louis Le Vau","François d'Orbay","Jules Hardouin-Mansart"]},
  "vezelay": {"article":"Vézelay Abbey","text":"Vézelay Abbey is a Benedictine and Cluniac monastery in Vézelay in the east-central French department of Yonne. It was constructed between 1120 and 1150. The Benedictine abbey church, now the Basilica of Sainte-Marie-Madeleine (Saint Mary Magdalene), with its complex program of imagery in sculpted capitals and portals, is one of the great masterpieces of Burgundian Romanesque art and architecture.","built":"9th century","height":24},
  "victoria-falls": {"article":"Victoria Falls","text":"Victoria Falls is a waterfall on the Zambezi River, located on the border between Zambia and Zimbabwe. It is one of the world's largest waterfalls, with a width of 1,708 m (5,604 ft). The region around it has a high degree of biodiversity in both plants and animals. Archaeology and oral history describe a long record of African knowledge of the site.","height":108},
  "vigan": {"article":"Vigan","text":"Vigan, officially the City of Vigan, is a component city and capital of the province of Ilocos Sur, Philippines. According to the 2024 census, it has a population of 54,498 people. Located on the western coast of the large island of Luzon, facing the South China Sea, it is a UNESCO World Heritage Site and it is one of the few Spanish colonial towns left in the Philippines whose old structures have mostly remained intact.","built":"1572","elevation":69},
  "villa-deste": {"article":"Villa d'Este","text":"The Villa d'Este is a 16th-century villa in Tivoli, near Rome. It is a masterpiece of Italian architecture and garden design, famous for its terraced hillside Italian Renaissance garden and the ingenuity of its architectural features (fountains, ornamental basins, ceilings, etc.), it is an incomparable example of a 16th-century Italian garden, which later had a huge influence on landscape design in Europe.","architects":["Pirro Ligorio"]},
  "villa-romana-del-casale": {"article":"Villa Romana del Casale","text":"The Villa Romana del Casale is a large and elaborate Roman villa or palace located approximately 3 km from the town of Piazza Armerina, Sicily. Excavations have revealed Roman mosaics that according to the Grove Dictionary of Art, are the richest, largest, and most varied collection that remains there, and for which the site was designated as a UNESCO World Heritage Site in 1997."},
  "villa-rotonda": {"article":"Villa La Rotonda","text":"Villa La Rotonda is a Renaissance villa just outside Vicenza in Northern Italy designed by Italian Renaissance architect Andrea Palladio, and begun in 1567, though not completed until 1605. The villa's official name is Villa Almerico Capra Valmarana, but it is also known as \"La Rotonda\", \"Villa Rotonda\", \"Villa Capra\", and \"Villa Almerico Capra\".","architects":["Andrea Palladio","Vincenzo Scamozzi"]},
  "villa-savoye": {"article":"Villa Savoye","text":"Villa Savoye is a modernist villa and gatelodge in Poissy, on the outskirts of Paris, France. It was designed by the Swiss-French architect Le Corbusier and his cousin Pierre Jeanneret with interior and furnishing by Charlotte Perriand, and built between 1928 and 1931 using reinforced concrete. As an exemplar of Le Corbusier's \"five points\" for new constructions, the villa is representative of the origins of modern architecture and is one of the most easily recognizable and renowned examples of the International style.","built":"1931","height":9.4,"architects":["Le Corbusier"]},
  "villa-tugendhat": {"article":"Villa Tugendhat","text":"Villa Tugendhat is an architecturally significant building in Brno, Czech Republic. It is one of the pioneering prototypes of modern architecture in Europe, and was designed by the German architects Ludwig Mies van der Rohe and Lilly Reich. It was built between 1928 and 1930 for Fritz Tugendhat and his wife Greta, of the wealthy and influential Jewish Czech Tugendhat family.","built":"1930","architects":["Ludwig Mies van der Rohe","Lilly Reich"]},
  "vilnius": {"article":"Vilnius Cathedral","text":"The Vilnius Cathedral, formally the Archcathedral Basilica of St. Stanislaus and St. Ladislaus, is the Roman Catholic cathedral of the Archdiocese of Vilnius and a minor basilica in Vilnius, Lithuania. Since the 14th century it serves as the seat of the Bishops and Metropolitan Archbishops of Vilnius. Located on the Cathedral Square in the historic centre of the city, it is one of the Lithuania's most important religious and architectural monuments.","built":"1387","architects":["Laurynas Gucevičius"]},
  "vinales": {"article":"Viñales Valley","text":"Viñales Valley is a karstic depression in Cuba. The valley has an area of 132 km2 (51 sq mi) and is located in the Sierra de los Órganos mountains (part of Guaniguanico range), just north of Viñales in the Pinar del Río Province. In 1999, the valley was inscribed as a UNESCO World Heritage Site as a natural and cultural landscape because of its use of traditional tobacco-growing techniques.","elevation":138},
  "virunga": {"article":"Virunga National Park","text":"Virunga National Park is a national park in the Albertine Rift Valley in the eastern part of the Democratic Republic of the Congo. It was created in 1925. In elevation, it ranges from 680 m (2,230 ft) in the Semliki River valley to 5,109 m (16,762 ft) in the Rwenzori Mountains. From north to south it extends approximately 300 km (190 mi), largely along the international borders with Uganda and Rwanda in the east.","built":"1925"},
  "visby": {"article":"Visby","text":"Visby is an urban area in Sweden and the seat of Gotland Municipality in Gotland County on the island of Gotland with 24,330 inhabitants as of 2017. Visby is also the episcopal see for the Diocese of Visby. The Hanseatic city of Visby is one of the best-preserved medieval cities in Scandinavia, and, since 1995, it has been on the UNESCO World Heritage Site list.","elevation":22},
  "visegrad-bridge": {"article":"Mehmed Paša Sokolović Bridge","text":"The Mehmed Paša Sokolović Bridge is a historic bridge over the Drina River in Višegrad, in the Republika Srpska region of Bosnia and Herzegovina. It was completed in 1577 by the Ottoman court architect Mimar Sinan on the order of the Grand Vizier Mehmed Paša Sokolović. In 2003 bridge was included into the List of National Monuments of Bosnia and Herzegovina by KONS, and UNESCO inclusion into the World Heritage List followed in 2007.","built":"1577","architects":["Mimar Sinan"]},
  "vittoriano": {"article":"Victor Emmanuel II Monument","text":"The Victor Emmanuel II National Monument, also known as the Vittoriano or for synecdoche Altare della Patria (\"Altar of the Fatherland\"), is a large national monument built between 1885 and 1935 to honour Victor Emmanuel II, the first king of a unified Italy, in Rome, Italy. It occupies a site between the Piazza Venezia and the Capitoline Hill.","built":"2nd millennium","height":81,"architects":["Giuseppe Sacconi"]},
  "vizcaya-bridge": {"article":"Vizcaya Bridge","text":"The Vizcaya Bridge (Bizkaiko Zubia in Basque, Puente de Vizcaya in Spanish) is a transporter bridge that links the towns of Portugalete and Las Arenas (part of Getxo) in the Biscay province of Spain, crossing the mouth of the Nervión River. People in the area, and even the official website, commonly call it the Puente Colgante (literally \"hanging bridge\", used for suspension bridge in Spanish), although its structure is quite different from a suspension bridge.","built":"1893","height":45,"architects":["Alberto Palacio"]},
  "vlkolinec": {"article":"Vlkolínec","text":"Vlkolínec is a village under the administration of the town of Ružomberok in Slovakia. Historically, however, it was a separate village. The first written mention of the village came from 1376 and after 1882 it became part of Ružomberok. Its name is probably derived from the Slovak word \"vlk\", i.e. wolf. Vlkolínec has been listed as a UNESCO World Heritage Site since 1993, and is one of ten Slovak villages that have been given the status of a folk architecture reservations."},
  "volcanoes-np": {"article":"Volcanoes National Park","text":"Volcanoes National Park is a national park in northwestern Rwanda. It covers 160 km2 (62 sq mi) of rainforest and encompasses five of the eight volcanoes in the Virunga Mountains, namely Karisimbi, Bisoke, Muhabura, Gahinga and Sabyinyo. It borders Virunga National Park in the Democratic Republic of the Congo and Mgahinga Gorilla National Park in Uganda.","built":"1969"},
  "volklingen": {"article":"Völklingen Ironworks","text":"The Völklingen Ironworks is a former blast furnace complex located in the German town of Völklingen, Saarland. Pig iron production occurred at the site from 1882 through 1986. As one of the only intact ironworks surviving from the 19th and early-20th centuries in Europe and North America, it was declared a UNESCO World Heritage Site in 1994 because of its exceptional preservation and its testimony to ferrous metallurgy and the Industrial Revolution."},
  "volubilis": {"article":"Volubilis","text":"Volubilis is a partly excavated Amazigh-Roman city in Morocco, situated near the city of Meknes, that may have been the capital of the Kingdom of Mauretania, at least from the time of King Juba II. Before Volubilis, the capital of the kingdom may have been at Gilda. Built in a fertile agricultural area, it developed from the 3rd century BC onward as an Amazigh, then proto-Carthaginian, settlement before being the capital of the kingdom of Mauretania.","built":"400 BC"},
  "volunteer-point": {"article":"Volunteer Point","text":"Volunteer Point is a headland on the east coast of East Falkland, in the Falkland Islands, north-northeast of Stanley, and east of Johnson's Harbour and Berkeley Sound. It lies at the end of a narrow peninsula, which protects Volunteer Lagoon. It is named after the ship Volunteer, which visited the islands in 1815. Volunteer Point hosts the islands' largest king penguin colony along its beach."},
  "voronet": {"article":"Voroneț Monastery","text":"The Voroneț Monastery is a medieval monastery in the Romanian village of Voroneț, now a part of the town Gura Humorului. It is one of the famous painted monasteries from southern Bukovina, in Suceava County. The monastery was constructed by Stephen the Great in 1488 over a period of 3 months and 3 weeks to commemorate the victory at Battle of Vaslui."},
  "wachau": {"article":"Melk Abbey","text":"Melk Abbey is a Benedictine abbey above the town of Melk, Lower Austria, on a rocky outcrop overlooking the Danube river, adjoining the Wachau valley, that belongs to the Austrian Congregation. The abbey contains the tomb of Saint Coloman of Stockerau and the remains of several members of the House of Babenberg, Austria's first ruling dynasty.","built":"1089","architects":["Jakob Prandtauer"]},
  "wadi-rum": {"article":"Wadi Rum","text":"Wadi Rum, also Wādī al-Ramm, known also as the Valley of the Moon or Red mountains, is a valley cut into the sandstone and granite rock in southern Jordan, near the border with Saudi Arabia and about 60 km (37 mi) to the east of the city of Aqaba. With an area of 720 km2 (280 mi2) it is the largest wadi (river valley) in Jordan.","height":1750},
  "wallblake-house": {"article":"Wallblake House","text":"Wallblake House is a heritage plantation house and museum annex in The Valley, Anguilla in the northeastern Caribbean. Built in 1787 by Will Blake, a sugar planter, it is stated to be the oldest structure on the island. Although gutted by the French in the late 1790s, it was rebuilt by the British and today has been fully restored, with its kitchen complex, stables and slave quarters intact.","built":"1787"},
  "warsaw": {"article":"Old Town, Warsaw","text":"Warsaw Old Town, also known as Old Town, and historically known as Old Warsaw, is a neighbourhood, and an area of the City Information System, in the city of Warsaw, Poland, located within the district of Śródmieście. It is the oldest portion of the city, and contains numerous historic buildings, mostly from 17th and 18th centuries, such as the Royal Castle, city walls, St."},
  "wartburg": {"article":"Wartburg","text":"The Wartburg is a castle originally built in the Middle Ages. At an elevation of 410 metres (1,350 ft) in the state of Thuringia, Germany, it is situated on a southwest-facing precipice and overlooks the town of Eisenach to the north. It was the home of St. Elisabeth of Hungary, the place where Martin Luther translated the New Testament of the Bible into German, the site of the Wartburg festival of 1817 and the supposed setting for the possibly legendary Sängerkrieg.","built":"1067","elevation":393},
  "wat-arun": {"article":"Wat Arun","text":"Wat Arun Ratchawararam Ratchawaramahawihan or Wat Arun is a Buddhist temple (wat) in the Bangkok Yai district of Bangkok, Thailand. It is situated in Thonburi on the west bank of the Chao Phraya River. The temple derives its name from the Hindu god Aruṇa, often personified as the rays of the rising sun. Built with a fusion of Indian influences, incorporating elements of both Hindu and Buddhist symbolism, as well as reflecting Siamese tradition and identity.","built":"1656"},
  "wat-phou": {"article":"Vat Phou","text":"Vat Phou is a ruined Khmer-Hindu temple complex in southern Laos. There was a sanctuary on the site, centred on a spring and an offering place for a tutelary spirit dating back to pre-historic times. The first megalithic stone structures had been built probably as early as the second century BCE, consisting of two stone cells, a carving of a crocodile, serpent stairs, and offering platforms."},
  "weimar": {"article":"Goethe and Schiller Monument","text":"The original Goethe and Schiller Monument is in Weimar, Germany. It incorporates Ernst Rietschel's 1857 bronze double statue of Johann Wolfgang von Goethe (1749–1832) and Friedrich Schiller (1759–1805), who are probably the two most revered figures in German literature. The monument has been described \"as one of the most famous and most beloved monuments in all of Germany\" and as the beginning of a \"cult of the monument\".","built":"1857"},
  "west-lake": {"article":"Leifeng Pagoda","text":"The Leifeng Pagoda is a five-story, eight-sided tower located on Sunset Hill south of West Lake in Hangzhou, Zhejiang, China. Originally constructed in the year AD 975, it collapsed in 1924 but was rebuilt in 2002. Since then, it has become a popular tourist attraction. A view of the original pagoda at dusk was one of the famous Ten Scenes of West Lake and it was notable for featuring as a location in the Legend of the White Snake."},
  "western-wall": {"article":"Western Wall","text":"The Western Wall is an ancient retaining wall of the built-up hill known to Jews and Christians as the Temple Mount of Jerusalem. Its most famous section, known by the same name, often shortened by Jews to the Kotel or Kosel, is known in the West as the Wailing Wall, and in the Arab world and Islamic world as the Buraq Wall.","built":"19 BC","height":19},
  "westminster-abbey": {"article":"Westminster Abbey","text":"Westminster Abbey, formally titled the Collegiate Church of Saint Peter at Westminster, is an Anglican church in the City of Westminster, London, England. Since 1066, it has been the location of the coronations of 40 English and British monarchs and a burial site for 18 English, Scottish, and British monarchs. At least 16 royal weddings have taken place at the abbey since 1100.","built":"10th century"},
  "white-city": {"article":"White City, Tel Aviv","text":"The White City is a collection of over 4,000 buildings in Tel Aviv from the 1930s built in a unique form of the International Style, commonly known as Bauhaus, by German Jewish architects who fled to the British Mandate of Palestine from Germany (and other Central and Eastern European countries with German cultural influences) after the rise to power of the Nazis."},
  "white-tower": {"article":"White Tower of Thessaloniki","text":"The White Tower of Thessaloniki is a monument and museum on the waterfront of the city of Thessaloniki, capital of the region of Macedonia in northern Greece. The present tower likely replaced an old Byzantine fortification, known to have been mentioned around the 12th century, that the Ottoman Empire reconstructed to fortify the city's fortress some time after Sultan Murad II captured Thessaloniki in 1430.","built":"15th century","height":34},
  "wieliczka": {"article":"Wieliczka Salt Mine","text":"The Wieliczka Salt Mine is a salt mine in the town of Wieliczka, near Kraków in southern Poland. From Neolithic times, sodium chloride (table salt) was produced there from the upwelling brine. The Wieliczka salt mine, excavated from the 13th century, produced table salt continuously until 1996, as one of the world's oldest operating salt mines.","built":"13th century"},
  "wieskirche": {"article":"Wieskirche","text":"The Pilgrimage Church of Wies is a Roman Catholic oval Rococo church, designed in the late 1740s and completed in 1754. It is the major work of the brothers Johann Baptist and Dominikus Zimmermann, the latter of whom lived nearby for the last eleven years of his life. It is located in the foothills of the Alps, in the municipality of Steingaden, Germany.","built":"1754","architects":["Dominikus Zimmermann"]},
  "wild-goose-pagoda": {"article":"Giant Wild Goose Pagoda","text":"The Giant Wild Goose Pagoda or Big Wild Goose Pagoda is a seven-storey Buddhist pagoda in the Daci'en Temple complex in southern Xi'an, Shaanxi, China. It was first built in 652, when Xi'an was the Tang capital Chang'an, under the direction of the monk and translator Xuanzang. The original five-storey structure was rebuilt during the reign of Wu Zetian and repaired in later dynasties; the present brick exterior reflects major work carried out during the Ming dynasty.","built":"AD 648"},
  "willemstad": {"article":"Willemstad","text":"Willemstad is the capital and largest city of Curaçao, an island in the southern Caribbean Sea that is a constituent country of the Kingdom of the Netherlands. It was the capital of the Netherlands Antilles prior to that entity's dissolution in 2010. The city accounts for around 90% of Curaçao's population, with 136,660 inhabitants as of 2011.","built":"1634","elevation":37},
  "wittenberg": {"article":"All Saints' Church, Wittenberg","text":"All Saints' Church, commonly referred to as Schlosskirche (Castle Church) to distinguish it from the Stadtkirche (Town Church) of St. Mary's, sometimes known as the Reformation Memorial Church, is a Lutheran church in Wittenberg, Saxony-Anhalt, Germany. It is the site where, according to Philip Melanchthon, the Ninety-five Theses were posted by Martin Luther in 1517, launching the beginning of the Protestant Reformation.","built":"1346","height":88,"architects":["Conrad Pflüger"]},
  "worlitz": {"article":"Dessau-Wörlitz Garden Realm","text":"The Dessau-Wörlitz Garden Realm is a cultural landscape and World Heritage Site in Germany, located between the city of Dessau and the town of Wörlitz in Central Germany. One of the first and largest English parks in Germany and continental Europe, it was created in the late 18th century under the regency of Duke Leopold III of Anhalt-Dessau.","built":"18th century","architects":["Friedrich Wilhelm von Erdmannsdorff"]},
  "wouda": {"article":"Wouda pumping station","text":"The ir. D.F. Wouda Steam Pumping Station (ir. D.F. Woudagemaal) is a pumping station in the Netherlands, and the largest still operational steam-powered pumping station in the world. On 7 October 1920 Queen Wilhelmina opened the pumping station. It was built to pump excess water out of Friesland, a province in the north of the Netherlands.","built":"1920"},
  "wurzburg": {"article":"Würzburg Residence","text":"The Würzburg Residence is a palace in Würzburg, Germany. Johann Lukas von Hildebrandt and Maximilian von Welsch, representatives of the Austrian/Southern German Baroque style, were involved in the construction, as well as Robert de Cotte and Germain Boffrand, who were followers of the French style. Balthasar Neumann, court architect of the Bishop of Würzburg, was the principal architect of the Residence, which was commissioned by the Prince-Bishop of Würzburg Johann Philipp Franz von Schönborn and his brother Friedrich Carl von Schönborn in 1720, and completed in 1744.","built":"1719","architects":["Johann Balthasar Neumann"]},
  "xanthos": {"article":"Xanthos","text":"Xanthos or Xanthus, also referred to by scholars as Arna, its Lycian name, was an ancient city near the present-day village of Kınık, in Antalya Province, Turkey. The ruins are located on a hill on the left bank of the River Xanthos. The number and quality of the surviving tombs at Xanthos are a notable feature of the site, which, together with nearby Letoon, was declared to be a UNESCO World Heritage Site in 1988."},
  "xixia-tombs": {"article":"Western Xia mausoleums","text":"The Western Xia mausoleums include nine imperial mausoleums and about 250 tombs of imperial relatives and officials of the Western Xia dynasty. The burial complex occupies an area of some 50 km2 (19 sq mi) at the foot of the Helan Mountains some 40 km (25 mi) westward from the capital city of the Western Xia, Xingqing, what is modern-day Yinchuan, now capital of the Ningxia Hui Autonomous Region in northwestern China.","built":"11th century"},
  "xochicalco": {"article":"Xochicalco","text":"Xochicalco is a pre-Columbian archaeological site in Miacatlán in the western part of the Mexican state of Morelos. The name Xochicalco may be translated from Nahuatl as \"in the house of Flowers\". The site is located 38 km southwest of Cuernavaca, about 122 km by road from Mexico City. The site is open to visitors all week, from 10 am to 5 pm, although access to the observatory is only allowed after noon."},
  "xochimilco": {"article":"Xochimilco","text":"Xochimilco is a borough of Mexico City. The borough is centered on the formerly independent city of Xochimilco, which was established on what was the southern shore of Lake Xochimilco in the precolonial period. Today, the borough consists of the 18 barrios, or neighborhoods, of this city along with 14 pueblos, or villages, that surround it, covering an area of 125 km2 (48 sq mi).","elevation":2238},
  "yasawi": {"article":"Mausoleum of Khoja Ahmed Yasawi","text":"The Mausoleum of Khawaja Ahmed Yasawi is a mausoleum in the city of Turkestan, in southern Kazakhstan. The structure was commissioned in 1389 by Timur, who ruled the area as part of the expansive Timurid Empire, to replace a smaller 12th-century mausoleum of the famous Turkic poet and Sufi mystic, Khoja Ahmed Yasawi (1093–1166).","built":"14th century"},
  "yazd": {"article":"Jameh Mosque of Yazd","text":"The Jāmeh Mosque of Yazd is a Friday mosque (jāmeh) located in the city of Yazd, in the province of Yazd, Iran. Built on the site of a 9th-century CE fire temple, the mosque was completed during the 14th and 15th centuries CE and renovated in subsequent years. Between 1982 and 2005 the mosque was depicted on the obverse of the Iranian 200 rial banknote.","built":"9th century","height":52},
  "yogyakarta": {"article":"Yogyakarta","text":"Yogyakarta is the capital city of the Special Region of Yogyakarta in Indonesia, in the south-central part of the island of Java. As the only Indonesian royal city still ruled by a monarchy, Yogyakarta is regarded as an important centre for classical Javanese fine arts and culture such as ballet, batik textiles, drama, literature, music, poetry, silversmithing, visual arts, and wayang puppetry.","built":"1756","elevation":113},
  "yungang": {"article":"Yungang Grottoes","text":"The Yungang Grottoes, formerly the Wuzhoushan Grottoes, are ancient Chinese Buddhist temple grottoes built during the Northern Wei dynasty near the city of Datong, then called Pingcheng, in the province of Shanxi. They are excellent examples of rock-cut architecture and one of the three most famous ancient Buddhist sculptural sites of China, along with Longmen and Mogao."},
  "zabid": {"article":"Zabid","text":"Zabid (also spelled Zabīd, Zabeed and Zebid) is a town with an urban population of around 52,590 people, located on Yemen's western coastal plain. It is one of the oldest towns in Yemen, and has been a UNESCO World Heritage Site since 1993. However, in 2000, the historic core placed on the List of World Heritage in Danger.","elevation":114},
  "zamosc": {"article":"Zamość","text":"Zamość is a historical city in southeastern Poland. It is situated in the southern part of Lublin Voivodeship, about 90 km (56 mi) from Lublin, 247 km (153 mi) from Warsaw. In 2021, the population of Zamość was 62,021. Zamość was founded in 1580 by Jan Zamoyski, Grand Chancellor of Poland, who envisioned an ideal city.","built":"1580","elevation":212},
  "zelena-hora": {"article":"Pilgrimage Church of Saint John of Nepomuk","text":"The Pilgrimage Church of Saint John of Nepomuk at Zelená hora (meaning \"Green Hill\", German: Grünberg) is a religious building at the edge of Žďár nad Sázavou, Czech Republic, near the historical border between Moravia and Bohemia. It is the final work of Johann Santini Aichel, a Bohemian architect who combined the Borrominiesque Baroque with references to Gothic elements in both construction and decoration.","built":"1719","architects":["Jan Santini Aichel"]},
  "zhangjiajie": {"article":"Zhangjiajie","text":"Zhangjiajie is a prefecture-level city in the northwestern part of Hunan Province, China. It comprises the district of Yongding, Wulingyuan and counties of Cili and Sangzhi. It contains the Zhangjiajie National Forest Park, part of the Wulingyuan Scenic Area which was designated as a UNESCO World Heritage Site in 1992."},
  "ziggurat-of-ur": {"article":"Ziggurat of Ur","text":"The Ziggurat (or Great Ziggurat) of Ur is a Neo-Sumerian ziggurat in what was the city of Ur near Nasiriyah, in present-day Dhi Qar Province, Iraq. The structure was built during the Early Bronze Age (21st century BC) by King Ur-Nammu of the Third Dynasty of Ur. It had crumbled to ruins by the 6th century BC of the Neo-Babylonian period, when it was restored by King Nabonidus.","built":"21st century BC"},
  "zollverein": {"article":"Zollverein Coal Mine Industrial Complex","text":"The Zollverein Coal Mine Industrial Complex (German Zeche Zollverein) is a large former industrial site in the city of Essen, North Rhine-Westphalia, Germany. The first coal mine on the premises was founded in 1847, and mining activities took place from 1851 until 23 December 1986. For decades, starting in the late 1950s, the two parts of the site, Zollverein Coal Mine and Zollverein Coking Plant (erected 1957–1961, closed on 30 June 1993), ranked among the largest of their kinds in Europe.","built":"1847"},
  "zytglogge": {"article":"Old City (Bern)","text":"The Old City is the medieval city center of Bern, Switzerland. Built on a narrow hill bordered on three sides by the river Aare, its compact layout has remained essentially unchanged since its construction during the twelfth to the fifteenth century. Despite a major fire in 1405, after which much of the city was rebuilt in sandstone, and substantial construction efforts in the eighteenth century, Bern's old city has retained its medieval character."},
};
